@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');

:root {
  /* Colors - Primitives */
  --hmte-navy:          #011f4b;
  --hmte-navy-light:    #02305e;
  --hmte-navy-deep:     #001333;
  --hmte-navy-rgb:      1, 31, 75;
  
  --hmte-gold:          #F5B82E;
  --hmte-gold-deep:     #DFA11E;
  --hmte-gold-glow:     rgba(245, 184, 46, 0.08);
  --hmte-gold-rgb:      245, 184, 46;
  
  --tre-black:          #020b14; /* Deepest Navy Black for Hero & CTA */
  --tre-black-deep:     #01070e;
  --tre-off-white:      #F8F7F4; /* Pure modern warm off-white background */
  --tre-paper:          #F0EDE8;
  --tre-paper-deep:     #FFFFFF;
  
  /* Status Colors */
  --hmte-success:       #2F7D59;
  --hmte-warning:       #B7791F;
  --hmte-teal:          #155E75;
  --hmte-cyan:          #22C7D7;
  
  /* Semantic Tokens (Light Theme Default) */
  --bg:                 var(--tre-off-white);
  --bg-elevated:        var(--tre-paper-deep);
  --fg:                 #0F2437; /* Dark Navy-slate text */
  --fg-muted:           #5c6e7e;
  --fg-faint:           #9ab0c2;
  --line:               #e2dbce;
  --accent:             var(--hmte-navy);
  --accent-secondary:   var(--hmte-gold);
  
  /* Fonts */
  --font-display:       "Geist", "Inter", system-ui, -apple-system, sans-serif;
  --font-body:          "Plus Jakarta Sans", "Inter", system-ui, -apple-system, sans-serif;
  --font-mono:          "JetBrains Mono", ui-monospace, monospace;
  
  /* Font Sizes */
  --fs-display-xl:      96px;
  --fs-display-lg:      72px;
  --fs-display-md:      56px;
  --fs-h1:              48px;
  --fs-h2:              40px;
  --fs-h3:              28px;
  --fs-h4:              22px;
  --fs-body-lg:         18px;
  --fs-body:            16px;
  --fs-sm:              14px;
  --fs-xs:              13px;
  --fs-eyebrow:         12px;
  
  /* Line Heights & Tracking */
  --lh-display:         1.02;
  --lh-heading:         1.1;
  --lh-body:            1.6;
  --lh-tight:           1.3;
  --tracking-display:   -0.025em;
  --tracking-tight:     -0.015em;
  --tracking-normal:    0;
  --tracking-eyebrow:   0.08em;
  
  /* Spacing */
  --space-1:            4px;
  --space-2:            8px;
  --space-3:            12px;
  --space-4:            16px;
  --space-5:            24px;
  --space-6:            32px;
  --space-7:            48px;
  --space-8:            64px;
  --space-9:            96px;
  --space-10:           120px;
  --space-11:           160px;
  --space-12:           200px;
  
  --section-y:          var(--space-11);
  --section-y-sm:       var(--space-9);
  
  --content-max:        1320px;
  --public-shell-max:   1200px;
  --public-gutter:      16px;
  --gutter:             32px;
  --gutter-sm:          16px;
  
  /*
   * Radius, Border, Shadows
   *
   * Skala ini dinaikkan saat situs dipindah dari sudut tajam ke permukaan
   * lembut. Nilai lama (6/8/12/18) membuat tombol, kolom isian, dan kartu
   * warisan tetap terbaca tajam meski halaman barunya sudah membulat. Angka
   * di sini sengaja disejajarkan dengan --sr-* di css/ui-soft.css.
   */
  --radius-sm:          10px;
  --radius-md:          14px;
  --radius-lg:          20px;
  --radius-xl:          26px;
  --radius-pill:        9999px;
  
  --border-w:           1px;
  --border-w-thick:     2px;
  
  --shadow-menu:
    0 4px 20px -4px rgba(1, 31, 75, 0.1),
    0 12px 40px -12px rgba(1, 31, 75, 0.15);
  
  /* Motion */
  --ease-out:           cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out:        cubic-bezier(0.4, 0.0, 0.2, 1);
  --dur-fast:           150ms;
  --dur-base:           250ms;
  --dur-slow:           400ms;
  
  /* Z-Index */
  --z-header:           50;
  --z-modal:            80;
  --z-toast:            90;
}
/* ============================================================
   NEWSROOM / BERITA
   Editorial, scroll-led treatment isolated to /berita.
   ============================================================ */
.newsroom-shell {
  width: min(1360px, calc(100vw - 64px));
  margin-inline: auto;
}

/*
 * Field, mesh and arc now come from the shared <HeroBackdrop variant="arc" />
 * layer — see css/hero-backdrop.css. Only the box metrics stay here.
 */
.newsroom-hero {
  min-height: 94svh;
  padding: 164px 0 52px;
}

.newsroom-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(280px, 0.55fr);
  grid-template-rows: 1fr auto;
  gap: 72px 64px;
  min-height: calc(94svh - 216px);
}

.newsroom-hero-copy {
  align-self: center;
  animation: newsroom-enter 900ms var(--ease-out) both;
}

.newsroom-overline,
.newsroom-category,
.newsroom-feature-date,
.newsroom-card-meta,
.newsroom-card-footer,
.newsroom-card-index {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.newsroom-overline {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 28px;
  color: var(--hmte-gold);
}

.newsroom-overline::before {
  width: 34px;
  height: 1px;
  content: '';
  background: currentColor;
}

.newsroom-hero h1 {
  max-width: 9.5ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(68px, 9.5vw, 144px);
  font-weight: 500;
  line-height: 0.88;
  letter-spacing: -0.07em;
  text-wrap: balance;
}

.newsroom-hero h1 span {
  color: var(--hmte-gold);
}

.newsroom-hero-aside {
  align-self: end;
  padding-bottom: 22px;
  animation: newsroom-enter 900ms 140ms var(--ease-out) both;
}

.newsroom-hero-aside > p {
  max-width: 34ch;
  margin: 0 0 40px;
  color: rgba(255, 255, 255, 0.72);
  font-size: clamp(16px, 1.45vw, 20px);
  line-height: 1.55;
}

.newsroom-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.newsroom-stats div {
  padding: 16px 12px 0 0;
}

.newsroom-stats dt {
  margin-bottom: 8px;
  /* .44 di atas navy cuma ~4.1:1, di bawah ambang AA 4.5:1 untuk teks 10px. */
  color: rgba(255, 255, 255, 0.65);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.newsroom-stats dd {
  margin: 0;
  color: var(--tre-off-white);
  font-family: var(--font-display);
  font-size: 26px;
}

.newsroom-scroll-cue {
  display: inline-flex;
  grid-column: 1 / -1;
  align-items: center;
  justify-content: space-between;
  align-self: end;
  width: 100%;
  padding-top: 20px;
  color: rgba(255, 255, 255, 0.58);
  border-top: 1px solid rgba(255, 255, 255, 0.18);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: color var(--dur-base) var(--ease-out);
}

.newsroom-scroll-cue:hover,
.newsroom-scroll-cue:focus-visible {
  color: var(--hmte-gold);
}

.newsroom-scroll-cue svg,
.newsroom-read-link svg,
.newsroom-card-footer svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.newsroom-scroll-cue svg {
  animation: newsroom-arrow 1.8s var(--ease-in-out) infinite;
}

.newsroom-feature-section,
.newsroom-feed {
  background: var(--tre-off-white);
}

.newsroom-feature-section {
  padding: 112px 0 128px;
}

.newsroom-section-heading {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) minmax(220px, 0.42fr);
  align-items: end;
  gap: 18px;
  margin-bottom: 38px;
  padding-bottom: 22px;
  border-bottom: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
}

.newsroom-section-heading > span {
  color: var(--hmte-gold-deep);
  font-family: var(--font-mono);
  font-size: 12px;
}

.newsroom-section-heading h2 {
  margin: 0;
  color: var(--hmte-navy);
  font-family: var(--font-display);
  font-size: clamp(42px, 5vw, 70px);
  font-weight: 500;
  line-height: 0.96;
  letter-spacing: -0.045em;
}

.newsroom-section-heading p {
  justify-self: end;
  margin: 0;
  color: var(--fg-muted);
  font-size: 14px;
}

.newsroom-feature {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(340px, 0.72fr);
  min-height: 650px;
  overflow: hidden;
  border-radius: var(--sr-lg, 24px);
  color: var(--tre-off-white);
  background: var(--hmte-navy);
  box-shadow: var(--sr-shadow-2);
}

.newsroom-feature-media {
  position: relative;
  min-height: 540px;
  overflow: hidden;
  background: var(--hmte-navy-deep);
}

.newsroom-feature-media::after {
  position: absolute;
  inset: 0;
  content: '';
  background: linear-gradient(90deg, transparent 68%, rgba(var(--hmte-navy-rgb), 0.26));
  pointer-events: none;
}

.newsroom-feature-media img {
  object-fit: cover;
  transition: transform 800ms var(--ease-out), filter 500ms var(--ease-out);
}

.newsroom-feature:hover .newsroom-feature-media img {
  transform: scale(1.035);
  filter: saturate(1.06);
}

.newsroom-feature-copy {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 42px;
}

.newsroom-feature-copy > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.newsroom-category {
  color: var(--hmte-gold);
}

.newsroom-feature-date {
  /* .44 di atas navy cuma ~4.1:1, di bawah ambang AA 4.5:1 untuk teks 11px. */
  color: rgba(255, 255, 255, 0.65);
}

.newsroom-feature h3 {
  margin: auto 0 28px;
  color: #fff;
  font-family: var(--font-display);
  font-size: clamp(34px, 3.3vw, 54px);
  font-weight: 500;
  line-height: 1.02;
  letter-spacing: -0.04em;
}

.newsroom-feature-copy > p {
  display: -webkit-box;
  margin: 0 0 36px;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.64);
  line-height: 1.65;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.newsroom-read-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 18px;
  color: var(--tre-off-white);
  border-top: 1px solid rgba(255, 255, 255, 0.22);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.newsroom-read-link svg {
  transition: transform var(--dur-base) var(--ease-out);
}

.newsroom-feature:hover .newsroom-read-link svg {
  transform: translateX(5px);
}

.newsroom-feed {
  padding: 0 0 144px;
}

.newsroom-feed-top {
  padding-top: 20px;
}

.newsroom-section-heading--feed {
  margin-bottom: 0;
}

/* Satu palang tersegmen, sama seperti .soft-pills, bukan deretan pil bergaris. */
.newsroom-filter {
  display: flex;
  gap: 6px;
  width: fit-content;
  max-width: 100%;
  margin: 20px 0 36px;
  padding: 5px;
  overflow-x: auto;
  border-radius: var(--sr-pill, 999px);
  background: rgba(var(--hmte-navy-rgb), 0.06);
  scrollbar-width: none;
}

.newsroom-filter::-webkit-scrollbar {
  display: none;
}

.newsroom-filter button {
  flex: 0 0 auto;
  min-height: 36px;
  padding: 0 15px;
  color: var(--sr-ink-soft, var(--fg-muted));
  border: 0;
  border-radius: var(--sr-pill, 999px);
  background: transparent;
  font-family: var(--font-body);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition:
    color var(--dur-base) var(--ease-out),
    background var(--dur-base) var(--ease-out),
    box-shadow var(--dur-base) var(--ease-out);
}

.newsroom-filter button:hover {
  color: var(--hmte-navy);
}

.newsroom-filter button.is-active {
  color: var(--hmte-navy);
  background: var(--sr-card, #fff);
  box-shadow: var(--sr-shadow-1);
}

.newsroom-filter button:focus-visible {
  outline: 2px solid var(--hmte-navy);
  outline-offset: 2px;
}

/*
 * Kisi ini dulu satu bidang bergaris: gap 1px di atas latar gelap. Kartu berita
 * sudah punya gambar sendiri, jadi garis sambungan cuma menambah kebisingan.
 * Sekarang tiap kartu berdiri sendiri dengan sudut membulat dan bayangan.
 */
.newsroom-grid {
  display: grid;
  grid-auto-flow: dense;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.newsroom-card {
  min-width: 0;
  overflow: hidden;
  border-radius: var(--sr-lg, 24px);
  background: var(--sr-card, #fff);
  box-shadow: var(--sr-shadow-1);
  content-visibility: auto;
  contain-intrinsic-size: 540px;
  transition: box-shadow 320ms var(--ease-out), transform 320ms var(--ease-out);
}

/*
 * Spesifisitas sengaja disamakan dengan aturan reveal di bawah
 * (.newsroom-grid.is-observed .newsroom-card.is-visible), kalau tidak angkatan
 * hover kalah oleh transform: translateY(0) milik reveal.
 */
.newsroom-grid .newsroom-card:hover,
.newsroom-grid.is-observed .newsroom-card.is-visible:hover {
  transform: translateY(-3px);
  box-shadow: var(--sr-shadow-2);
}

@media (prefers-reduced-motion: reduce) {
  .newsroom-grid .newsroom-card:hover,
  .newsroom-grid.is-observed .newsroom-card.is-visible:hover {
    transform: none;
  }
}

.newsroom-grid.is-observed .newsroom-card {
  opacity: 0;
  transform: translateY(34px);
}

.newsroom-grid.is-observed .newsroom-card.is-visible {
  opacity: 1;
  transform: translateY(0);
  transition:
    opacity 700ms var(--reveal-delay, 0ms) var(--ease-out),
    transform 700ms var(--reveal-delay, 0ms) var(--ease-out);
}

.newsroom-card:nth-child(7n + 1) {
  grid-column: span 2;
}

.newsroom-card article {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 530px;
}

.newsroom-card-media {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--tre-paper);
}

.newsroom-card:nth-child(7n + 1) .newsroom-card-media {
  aspect-ratio: 2 / 1;
}

.newsroom-card-media::after {
  position: absolute;
  inset: 0;
  content: '';
  background: linear-gradient(180deg, transparent 64%, rgba(0, 19, 51, 0.28));
  opacity: 0;
  transition: opacity 500ms var(--ease-out);
}

.newsroom-card-media img {
  object-fit: cover;
  transition: transform 700ms var(--ease-out);
}

.newsroom-card:hover .newsroom-card-media img {
  transform: scale(1.045);
}

.newsroom-card:hover .newsroom-card-media::after {
  opacity: 1;
}

.newsroom-card-index {
  position: absolute;
  z-index: 1;
  right: 14px;
  bottom: 12px;
  color: #fff;
}

.newsroom-card-copy {
  display: flex;
  flex: 1 1;
  flex-direction: column;
  padding: 24px;
  transition: background 450ms var(--ease-out);
}

.newsroom-card:hover .newsroom-card-copy {
  background: rgba(var(--hmte-gold-rgb), 0.08);
}

.newsroom-card-meta,
.newsroom-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.newsroom-card-meta {
  color: var(--fg-soft);
}

.newsroom-card-meta span {
  color: var(--hmte-navy);
}

.newsroom-card h3 {
  max-width: 24ch;
  margin: 28px 0 14px;
  color: var(--hmte-navy);
  font-family: var(--font-display);
  font-size: clamp(22px, 2vw, 31px);
  font-weight: 500;
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.newsroom-card-copy > p {
  display: -webkit-box;
  margin: 0 0 34px;
  overflow: hidden;
  color: var(--fg-muted);
  font-size: 14px;
  line-height: 1.6;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.newsroom-card-footer {
  margin-top: auto;
  padding-top: 16px;
  color: var(--fg-soft);
  border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.13);
}

.newsroom-card-footer svg {
  width: 18px;
  height: 18px;
  margin-left: auto;
  color: var(--hmte-navy);
  transition: transform var(--dur-base) var(--ease-out);
}

.newsroom-card:hover .newsroom-card-footer svg {
  transform: translateX(5px);
}

.newsroom-load-more {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-top: 28px;
  padding: 22px 24px;
  color: var(--hmte-navy);
  border: 0;
  border-radius: var(--sr-md, 18px);
  background: var(--sr-card, #fff);
  box-shadow: var(--sr-shadow-1);
  font-family: var(--font-body);
  font-weight: 600;
  cursor: pointer;
  transition: color var(--dur-base) var(--ease-out), background var(--dur-base) var(--ease-out);
}

.newsroom-load-more span:last-child {
  color: var(--fg-muted);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.newsroom-load-more:hover,
.newsroom-load-more:focus-visible {
  color: #fff;
  background: var(--hmte-navy);
}

.newsroom-load-more:hover span:last-child,
.newsroom-load-more:focus-visible span:last-child {
  color: rgba(255, 255, 255, 0.66);
}

@keyframes newsroom-enter {
  from {
    opacity: 0;
    transform: translateY(28px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ============================================================
   PROGRAM DETAIL WORKSPACE
   Compact HMTE editorial system with data-dense interactions.
   ============================================================ */

.program-workspace-hero {
  position: relative;
  padding: 142px 0 0;
  overflow: hidden;
  color: var(--tre-off-white);
  background:
    radial-gradient(circle at 80% 16%, rgba(var(--hmte-gold-rgb), 0.13), transparent 24%),
    linear-gradient(135deg, var(--hmte-navy-deep), var(--hmte-navy) 66%, #082d5b);
}

.program-workspace-hero::before {
  position: absolute;
  inset: 0;
  content: '';
  opacity: 0.22;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 72px 72px;
  -webkit-mask-image: linear-gradient(to bottom, black, transparent 88%);
          mask-image: linear-gradient(to bottom, black, transparent 88%);
}

.program-workspace-hero .public-shell {
  position: relative;
  z-index: 1;
}

.program-workspace-breadcrumb {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 26px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.program-workspace-breadcrumb a,
.program-workspace-breadcrumb span {
  color: rgba(255, 255, 255, 0.6);
}

.program-workspace-breadcrumb a {
  text-decoration: none;
}

.program-workspace-breadcrumb a:hover {
  color: var(--hmte-gold);
}

.program-workspace-breadcrumb span::before {
  margin-right: 11px;
  content: '/';
  color: rgba(255, 255, 255, 0.22);
}

.program-workspace-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(340px, 0.7fr);
  gap: clamp(36px, 6vw, 84px);
  align-items: end;
  min-height: 320px;
}

.program-workspace-intro {
  padding-bottom: 54px;
}

.program-workspace-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 17px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.program-workspace-kicker > span {
  color: var(--hmte-gold);
}

.program-workspace-kicker > strong {
  padding: 5px 8px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.74);
}

.program-workspace-kicker > strong.status-selesai { color: #a9e5bd; }
.program-workspace-kicker > strong.status-sedang-berjalan { color: #8fe7ef; }
.program-workspace-kicker > strong.status-terencana { color: #ffd26f; }

.program-workspace-intro h1 {
