  .program-workspace-intro { padding-bottom: 36px; }
  .program-workspace-intro h1 { font-size: clamp(42px, 13vw, 62px); }
  .program-workspace-intro > p { font-size: 14px; }
  .program-workspace-visual { min-height: 230px; }
  .program-workspace-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .program-workspace-metrics > div:nth-child(n + 3) { border-top: 1px solid rgba(255, 255, 255, 0.16); }
  .program-workspace-section { padding: 32px 0 80px; }
  .program-workspace-shell { border-radius: 14px; }
  .program-workspace-tabs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .program-workspace-tabs button:nth-child(2) { border-right: 0; }
  .program-workspace-tabs button:nth-child(n + 3) { border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1); }
  .program-summary-copy { padding: 34px 22px; }
