  .program-timeline-view,
  .program-documents-view,
  .program-team-view { padding: 30px 20px; }
  .program-view-heading { align-items: flex-start; flex-direction: column; gap: 18px; }
  .program-timeline-rail { grid-template-columns: 1fr; margin-left: 6px; }
  .program-timeline-rail button { padding: 17px 16px 17px 28px; border-top: 0; border-left: 1px solid rgba(var(--hmte-navy-rgb), 0.17); }
  .program-timeline-rail button > i { top: 19px; left: -6px; }
  .program-timeline-rail button > strong { margin-top: 9px; }
  .program-timeline-rail button > em { margin-top: 10px; }
  .program-timeline-detail { padding: 25px; }
  .program-timeline-detail > time { position: static; display: block; margin-top: 18px; }
  .program-document-list button { grid-template-columns: 42px minmax(0, 1fr); }
  .program-document-list button > em { grid-column: 2; }
  .program-team-list { grid-template-columns: 1fr; }
  .program-related-compact article { grid-template-columns: 30px minmax(0, 1fr); }
  .program-related-compact aside { grid-column: 2; align-items: flex-start; }
