  .program-workspace-metrics > div { padding-inline: 11px; }
  .program-workspace-tabs button { min-height: 52px; padding-inline: 9px; font-size: 10px; }
  .program-summary-copy h2,
  .program-view-heading h2 { font-size: 32px; }
  .program-focus-detail { margin: 14px; }
}

@media (prefers-reduced-motion: reduce) {
