  .program-focus-detail,
  .program-timeline-detail,
  .program-document-preview,
  .program-leader-detail,
  .program-animated-progress span { animation: none; }
  .program-workspace-visual img,
  .program-workspace-tabs button,
  .program-focus-buttons button,
  .program-timeline-rail button,
  .program-timeline-rail button > i,
  .program-document-list button { transition: none; }
}

@keyframes newsroom-arrow {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(5px); }
}

@supports (animation-timeline: view()) {
  .newsroom-feature-media img {
    animation: newsroom-image-drift linear both;
    animation-timeline: view();
    animation-range: entry -12% exit 112%;
  }

  @keyframes newsroom-image-drift {
    from { transform: scale(1.08) translateY(-3%); }
    to { transform: scale(1.08) translateY(3%); }
  }
}

@media (max-width: 1050px) {
  .newsroom-shell {
    width: min(100% - 40px, 1360px);
  }

  .newsroom-hero-grid {
    grid-template-columns: minmax(0, 1.25fr) minmax(260px, 0.6fr);
  }

  .newsroom-feature {
    grid-template-columns: 1.25fr 0.75fr;
  }

  .newsroom-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .newsroom-card:nth-child(7n + 1) {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .newsroom-shell {
    width: min(100% - 32px, 1360px);
  }

  .newsroom-hero {
    min-height: 820px;
    padding: 128px 0 30px;
  }

  .newsroom-hero-grid {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr;
    gap: 48px;
    min-height: 662px;
  }

  .newsroom-hero h1 {
    max-width: 8.5ch;
    font-size: clamp(60px, 18vw, 96px);
  }

  .newsroom-hero-aside {
    align-self: start;
    padding: 0;
  }

  .newsroom-hero-aside > p {
    margin-bottom: 28px;
  }

  .newsroom-scroll-cue {
    grid-column: auto;
  }

  .newsroom-feature-section {
    padding: 78px 0 88px;
  }

  .newsroom-section-heading {
    grid-template-columns: 40px 1fr;
  }

  .newsroom-section-heading p {
    grid-column: 2;
    justify-self: start;
  }

  .newsroom-feature {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .newsroom-feature-media {
    min-height: 420px;
  }

  .newsroom-feature-copy {
    min-height: 480px;
    padding: 30px;
  }

  .newsroom-grid {
    grid-template-columns: 1fr;
  }

  .newsroom-card:nth-child(7n + 1) {
    grid-column: auto;
  }

  .newsroom-card:nth-child(7n + 1) .newsroom-card-media,
  .newsroom-card-media {
    aspect-ratio: 16 / 10;
  }
}

@media (max-width: 480px) {
  .newsroom-hero {
    min-height: 760px;
  }

  .newsroom-hero-grid {
    min-height: 602px;
  }

  .newsroom-hero h1 {
    font-size: clamp(54px, 17vw, 78px);
  }

  .newsroom-stats dd {
    font-size: 22px;
  }

  .newsroom-section-heading h2 {
    font-size: 40px;
  }

  .newsroom-feature-media {
    min-height: 290px;
  }

  .newsroom-feature-copy {
    min-height: 440px;
    padding: 24px;
  }

  .newsroom-feature h3 {
    font-size: 32px;
  }

  .newsroom-feed {
    padding-bottom: 96px;
  }

  .newsroom-card article {
    min-height: 500px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .newsroom-hero-copy,
  .newsroom-hero-aside,
  .newsroom-scroll-cue svg,
  .newsroom-feature-media img,
  .newsroom-grid.is-observed .newsroom-card,
  .newsroom-grid.is-observed .newsroom-card.is-visible {
