  padding-top: 24px;
  border-top: 1px solid var(--line);
}

.curr-legend b {
  color: var(--hmte-navy);
  margin-right: 6px;
  font-weight: 700;
}

/* OS Window Interactive Table - Reskinned to Light Mode */
.curr-os {
  border: 1px solid var(--line);
  background: #fbfbfa;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow:
    0 24px 64px rgba(1, 31, 75, 0.05),
    0 4px 16px rgba(1, 31, 75, 0.02);
}

.os-menubar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  padding: 0 20px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.6);
  -webkit-backdrop-filter: blur(8px);
          backdrop-filter: blur(8px);
}

.os-brand, .os-status {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fg-muted);
}

.os-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--hmte-navy);
  font-weight: 700;
}

.os-dot {
  width: 8px;
  height: 8px;
  background: var(--hmte-gold);
  display: inline-block;
  border-radius: 50%;
}

.os-status {
  font-size: 10px;
  font-weight: 500;
}

.os-desktop {
  min-height: 640px;
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 20px;
  padding: 24px;
  background: 
    radial-gradient(circle at 80% 20%, rgba(245, 184, 46, 0.05), transparent 40%),
    linear-gradient(135deg, #fbfbfa, #f4f3ef);
}

.os-dock {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  padding: 16px 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.7);
  border-radius: var(--radius-md);
}

.sem-icon {
  width: 76px;
  aspect-ratio: 1;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.9);
  color: var(--hmte-navy);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  font-family: var(--font-mono);
  border-radius: var(--radius-sm);
  transition: transform var(--dur-base) var(--ease-out),
              background var(--dur-base) var(--ease-out),
              border-color var(--dur-base) var(--ease-out),
              color var(--dur-base) var(--ease-out);
}

.sem-icon b {
  font-size: var(--fs-body-lg);
  line-height: 1;
  font-weight: 700;
}

.sem-icon span {
  font-size: 11px;
  letter-spacing: 0.05em;
  color: var(--fg-muted);
}

.sem-icon:hover {
  transform: translateX(4px);
  background: #ffffff;
  border-color: var(--hmte-navy-light);
}

.sem-icon.active {
  transform: translateX(4px);
  background: var(--hmte-navy);
  color: #ffffff;
  border-color: var(--hmte-navy);
}

.sem-icon.active span {
  color: var(--hmte-gold);
}

.os-window {
  align-self: stretch;
  border: 1px solid var(--line);
  background: #ffffff;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: var(--radius-md);
  box-shadow: 0 8px 32px rgba(1, 31, 75, 0.03);
}

.window-top {
  min-height: 50px;
  border-bottom: 1px solid var(--line);
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 16px;
  padding: 0 20px;
  background: #fbfbfa;
}

.window-controls {
  display: flex;
  gap: 7px;
}

.window-controls span {
  width: 10px;
  height: 10px;
  border: 1px solid rgba(1, 31, 75, 0.15);
  border-radius: 50%;
}

.window-controls span:nth-child(1) { background: #ff5f56; border-color: #e0443e; }
.window-controls span:nth-child(2) { background: #ffbd2e; border-color: #dea123; }
.window-controls span:nth-child(3) { background: #27c93f; border-color: #1aab29; }

.window-title, .window-chip {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
}

.window-chip {
  color: var(--hmte-navy);
  background: rgba(1, 31, 75, 0.05);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

.window-body {
  flex: 1 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 280px;
  gap: 1px;
  background: var(--line);
}

.window-main, .window-side {
  background: #ffffff;
}

.window-main {
  padding: 48px;
}

.window-eyebrow {
  margin: 0 0 12px;
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  letter-spacing: var(--tracking-eyebrow);
  text-transform: uppercase;
  color: var(--hmte-gold-deep);
  font-weight: 700;
}

.window-main h3 {
  margin: 0 0 16px;
  font-family: var(--font-display);
  font-size: clamp(32px, 4vw, 56px);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.05;
  color: var(--hmte-navy);
}

.window-main > p:not(.window-eyebrow) {
  margin: 0 0 36px;
  max-width: 58ch;
  color: var(--fg-muted);
  font-size: var(--fs-body);
  line-height: 1.6;
}

.course-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.course-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 14px 18px;
  border: 1px solid var(--line);
  background: var(--tre-off-white);
  border-radius: var(--radius-sm);
}

.course-item span {
  color: var(--fg);
  font-size: var(--fs-sm);
  font-weight: 500;
}

.course-item b {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  color: var(--hmte-navy);
  white-space: nowrap;
}

.window-side {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  border-left: 1px solid var(--line);
}

.side-card {
  border: 1px solid var(--line);
  padding: 20px;
  background: var(--tre-off-white);
  border-radius: var(--radius-sm);
}

.side-card span {
  display: block;
  margin-bottom: 8px;
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--fg-muted);
  font-weight: 600;
}

.side-card strong {
  font-family: var(--font-mono);
  font-size: 48px;
  font-weight: 600;
  line-height: 1;
  color: var(--hmte-navy);
}

.side-card p {
  margin: 0;
  color: var(--fg-muted);
  font-size: var(--fs-xs);
  line-height: 1.5;
}

.side-card.split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  padding: 0;
  background: var(--line);
  overflow: hidden;
}

.side-card.split div {
  background: var(--tre-off-white);
  padding: 16px;
}

/* ============================================================
   KEPENGURUSAN WINDOW — Constrained OS dengan padding
   ============================================================ */
.curr-os-wrap {
  max-width: var(--content-max);
  margin-inline: auto;
  padding: 0 var(--gutter);
}

.os-desktop--kep {
  min-height: 560px;
  grid-template-columns: 220px 1fr;
  gap: 0;
