  background: 
    radial-gradient(circle at 80% 20%, rgba(245, 184, 46, 0.04), transparent 40%),
    linear-gradient(135deg, #fbfbfa, #f4f3ef);
}

/* Dock Kepengurusan: vertikal list tombol bidang */
.os-dock--kep {
  flex-direction: column;
  align-items: stretch;
  padding: 16px 0;
  gap: 2px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background: rgba(255, 255, 255, 0.6);
}

.kep-dock-btn {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 12px 20px;
  border: none;
  background: none;
  cursor: pointer;
  text-align: left;
  transition: background var(--dur-base) var(--ease-out);
  position: relative;
}

.kep-dock-btn:hover {
  background: rgba(1, 31, 75, 0.04);
}

.kep-dock-btn.active {
  background: rgba(245, 184, 46, 0.14);
}

.kep-dock-btn.active .kep-dock-abbr {
  font-weight: 800;
}

.kep-dock-abbr {
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--hmte-navy);
}

.kep-dock-btn:not(.active) .kep-dock-abbr {
  color: var(--fg-muted);
}

.kep-dock-name {
  font-size: 11px;
  line-height: 1.3;
  color: var(--fg-muted);
  max-width: 160px;
}

/* OS Window Kepengurusan */
.os-window--kep {
  border-radius: 0;
  box-shadow: none;
  border: none;
  border-left: 1px solid var(--line);
}

/* Grid kartu anggota: 4 kolom × 2 baris = 8 orang */
.kep-members-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  padding: 24px;
  background: #ffffff;
  transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-base) var(--ease-out);
}

.kep-members-grid.fade-content-out {
  opacity: 0;
  transform: translateY(8px);
}

.member-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 24px 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--tre-off-white);
  text-align: center;
  transition: border-color var(--dur-base) var(--ease-out),
              box-shadow var(--dur-base) var(--ease-out),
              transform var(--dur-base) var(--ease-out),
              background var(--dur-base) var(--ease-out);
}

.member-card:hover {
  border-color: rgba(245, 184, 46, 0.4);
  background: #ffffff;
  transform: translateY(-3px);
  box-shadow:
    0 12px 28px rgba(1, 31, 75, 0.04),
    0 2px 8px rgba(245, 184, 46, 0.02);
}

.member-avatar {
  width: 76px;
  height: 76px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(1, 31, 75, 0.04), rgba(245, 184, 46, 0.06));
  border: 2px solid var(--line);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
  transition: transform var(--dur-base) var(--ease-out), border-color var(--dur-base) var(--ease-out);
}

.member-avatar::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  padding: 2px;
  background: linear-gradient(135deg, var(--hmte-navy), var(--hmte-gold));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-out);
}

.member-card:hover .member-avatar {
  transform: scale(1.04);
  border-color: transparent;
}

.member-card:hover .member-avatar::before {
  opacity: 1;
  transform: rotate(180deg);
}

.member-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.member-avatar svg {
  color: rgba(1, 31, 75, 0.2);
}

.member-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 100%;
}

.member-name {
  font-family: var(--font-display);
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--hmte-navy);
  margin: 0;
  line-height: 1.3;
}

.member-role-badge {
  padding: 4px 10px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: var(--radius-pill);
  display: inline-block;
  line-height: 1;
}

/* Badge Peran Varian Warna */
.role-leader {
  color: #854d0e;
  background: #fef9c3;
  border: 1px solid #fde047;
  box-shadow: 0 1px 4px rgba(234, 179, 8, 0.1);
}

.role-co-leader {
  color: #854d0e;
  background: #fef9c3;
  border: 1px solid #fde047;
  opacity: 0.9;
}

.role-officer {
  color: #1e3a8a;
  background: #dbeafe;
  border: 1px solid #bfdbfe;
}

.role-expert {
  color: #115e59;
  background: #ccfbf1;
  border: 1px solid #99f6e4;
}

.role-staff {
  color: var(--fg-muted);
  background: rgba(1, 31, 75, 0.04);
  border: 1px solid var(--line);
}

/* Pencarian & View Actions */
.window-title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.window-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.search-box {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--line);
  background: #ffffff;
  border-radius: var(--radius-pill);
  padding: 5px 12px;
  width: 180px;
  transition: border-color var(--dur-base) var(--ease-out), box-shadow var(--dur-base) var(--ease-out);
}

.search-box:focus-within {
  border-color: var(--hmte-gold);
  box-shadow: 0 0 0 3px rgba(245, 184, 46, 0.15);
}

.search-box input {
  border: none;
  background: none;
  padding: 0;
  font-family: var(--font-body);
  font-size: var(--fs-xs);
  color: var(--fg);
  width: 100%;
  outline: none;
}

.search-box input::placeholder {
  color: var(--fg-faint);
}

.search-icon {
  flex-shrink: 0;
  opacity: 0.6;
  color: var(--fg-muted);
}

.view-toggle {
  display: flex;
  border: 1px solid var(--line);
  background: #ffffff;
  border-radius: var(--radius-sm);
  padding: 2px;
}

.toggle-btn {
  border: none;
  background: none;
  color: var(--fg-muted);
  padding: 5px;
  border-radius: 4px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--dur-base) var(--ease-out), color var(--dur-base) var(--ease-out);
}

.toggle-btn:hover {
  color: var(--hmte-navy);
  background: rgba(1, 31, 75, 0.04);
}

.toggle-btn.active {
  color: #ffffff;
  background: var(--hmte-navy);
}

/* Empty Search State */
.empty-search-state {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 64px 24px;
  color: var(--fg-muted);
  text-align: center;
}

.empty-icon {
  color: var(--fg-faint);
  animation: pulse 2s infinite ease-in-out;
}

@keyframes pulse {
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 0.3; transform: scale(0.95); }
}

/* List View Layout */
.kep-members-grid.list-view {
  grid-template-columns: 1fr !important;
  gap: 12px;
}

.kep-members-grid.list-view .member-card {
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  text-align: left;
  padding: 14px 24px;
  gap: 20px;
}

.kep-members-grid.list-view .member-avatar {
  width: 46px;
  height: 46px;
}

.kep-members-grid.list-view .member-avatar::before {
  padding: 1px;
}

.kep-members-grid.list-view .member-info {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  text-align: left;
  gap: 16px;
  flex: 1 1;
}

.kep-members-grid.list-view .member-name {
  margin-bottom: 0;
}

.kep-members-grid.list-view .member-role-badge {
  margin-top: 0;
}

/* ============================================================
   PARTNERS SECTION (LIGHT)
   ============================================================ */

.tre-partners {
  position: relative;
  padding: 118px 0 126px;
  background:
    linear-gradient(90deg, rgba(1, 31, 75, 0.035) 1px, transparent 1px),
    linear-gradient(180deg, rgba(1, 31, 75, 0.026) 1px, transparent 1px),
    var(--tre-off-white);
  background-size: 72px 72px;
  border-top: 1px solid var(--line);
  overflow: hidden;
}

.tre-partners::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(248, 247, 244, 0.94), rgba(248, 247, 244, 0.72) 42%, rgba(248, 247, 244, 0.96)),
    linear-gradient(90deg, rgba(245, 184, 46, 0.18), transparent 24%, transparent 76%, rgba(1, 31, 75, 0.08));
}

.partners-shell {
  position: relative;
  z-index: 1;
  max-width: var(--content-max);
  margin-inline: auto;
  padding: 0 var(--gutter);
}

.partners-head {
  display: grid;
  grid-template-columns: minmax(320px, 0.95fr) minmax(360px, 1.05fr);
  gap: 40px;
  align-items: center;
  margin-bottom: 38px;
}

.partners-h2 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(44px, 5vw, 68px);
  line-height: 1.02;
  letter-spacing: -0.025em;
  margin: 0;
  color: var(--hmte-navy);
}

.partners-h2 .muted {
  color: var(--fg-muted);
}

.partners-h2 .acc {
  color: var(--hmte-gold);
}

.partners-lead {
  font-size: var(--fs-body-lg);
  line-height: 1.6;
  color: var(--fg-muted);
  margin: 0;
  max-width: 50ch;
  padding: 18px 22px;
  border-radius: var(--radius-md);
  background: rgba(245, 184, 46, 0.08);
}

.partners-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  width: min(720px, 100%);
  margin: 0 0 22px auto;
  overflow: hidden;
  border: 1px solid rgba(1, 31, 75, 0.12);
  border-radius: var(--radius-md);
  background: rgba(1, 31, 75, 0.12);
  box-shadow: 0 18px 42px -34px rgba(1, 31, 75, 0.48);
}

.partners-metrics div {
  padding: 16px 18px;
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.partners-metrics span {
  display: block;
  font-family: var(--font-display);
  font-size: 28px;
  line-height: 1;
  font-weight: 700;
  color: var(--hmte-navy);
}

.partners-metrics em {
  display: block;
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-style: normal;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--fg-muted);
}

.partner-logo-wall {
  position: relative;
  overflow: visible;
  padding: 10px;
  border: 1px solid rgba(1, 31, 75, 0.12);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.92), rgba(248, 247, 244, 0.82)),
    var(--bg-elevated);
  border-radius: var(--radius-md);
  box-shadow:
    0 26px 70px -54px rgba(1, 31, 75, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.logo-set {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.logo-tile {
  position: relative;
  min-height: 156px;
  padding: 20px;
  background: #ffffff;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 18px;
  border: 1px solid rgba(1, 31, 75, 0.1);
  border-radius: var(--radius-sm);
  box-shadow: inset 0 -3px 0 rgba(1, 31, 75, 0.04);
  transition:
    transform var(--dur-base) var(--ease-out),
    border-color var(--dur-base) var(--ease-out),
    box-shadow var(--dur-base) var(--ease-out),
    background var(--dur-base) var(--ease-out);
}

.logo-tile::before {
  content: "";
  position: absolute;
  top: 22px;
  right: 20px;
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: var(--hmte-gold);
  box-shadow: 0 0 0 5px rgba(245, 184, 46, 0.12);
}

.logo-tile strong {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  /* Opasitas lama (.42 di atas putih) cuma ~2.6:1, di bawah ambang WCAG AA
     4.5:1 untuk teks kecil. --fg-muted sudah diverifikasi lolos di atas
     off-white maupun putih. */
  color: var(--fg-muted);
}

.logo-tile span {
  font-family: var(--font-display);
  font-size: clamp(22px, 2vw, 30px);
  line-height: 1.08;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--hmte-navy);
}

.logo-tile em {
  width: fit-content;
  max-width: 100%;
  padding: 6px 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--hmte-navy);
  font-style: normal;
  font-weight: 700;
  background: rgba(245, 184, 46, 0.16);
  border: 1px solid rgba(245, 184, 46, 0.32);
  border-radius: var(--radius-xs);
}

.logo-tile:hover {
  transform: translateY(-4px);
  border-color: rgba(1, 31, 75, 0.28);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 24px 42px -32px rgba(1, 31, 75, 0.62);
}

.logo-tile.is-confirmed {
  background: linear-gradient(180deg, rgba(245, 184, 46, 0.16), #ffffff 58%);
}

.logo-tile.is-confirmed::before {
  background: var(--hmte-success);
  box-shadow: 0 0 0 5px rgba(47, 125, 89, 0.13);
}

.logo-tile.is-indicated::before {
  background: var(--hmte-cyan);
  box-shadow: 0 0 0 5px rgba(34, 199, 215, 0.12);
}

/* ============================================================
   CALL TO ACTION SECTION (DARK)
   ============================================================ */
.tre-cta {
  background: var(--tre-black);
  color: var(--tre-paper);
  padding: 130px 0;
  position: relative;
  overflow: hidden;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.tre-cta::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--hmte-gold);
}

.cta-shell {
  max-width: var(--content-max);
  margin-inline: auto;
  padding: 0 var(--gutter);
  display: grid;
  grid-template-columns: 1.25fr 1fr;
  gap: 80px;
  align-items: end;
}

.cta-h2 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(56px, 8vw, 110px);
  line-height: 0.95;
  letter-spacing: -0.04em;
  margin: 0;
}

.cta-h2 .muted {
  color: rgba(255, 255, 255, 0.35);
  font-weight: 500;
}

.cta-h2 .acc {
  color: var(--hmte-gold);
}

.cta-p {
  font-size: var(--fs-body-lg);
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.7);
  margin: 0 0 32px;
  max-width: 42ch;
}

.cta-deadline {
  padding: 20px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 36px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.dl-label {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  letter-spacing: 0.1em;
  /* .45 di atas navy cuma ~4.2:1, di bawah ambang AA 4.5:1. */
  color: rgba(255, 255, 255, 0.6);
}

.dl-date {
  font-family: var(--font-mono);
  font-size: 20px;
  color: var(--hmte-gold);
  letter-spacing: 0.04em;
  font-weight: 600;
}

.cta-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

/* ============================================================
   FOOTER (DARK)
   ============================================================ */
.tre-footer {
  position: relative;
  background: var(--tre-black-deep);
  color: var(--tre-paper);
  padding: 0 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.tre-footer .container {
  max-width: var(--content-max);
  margin-inline: auto;
  padding-inline: var(--gutter);
}

/* Masthead: HMTE identity on the left, cabinet identity beside it. */
.ftr-masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  flex-wrap: wrap;
  padding: 44px 0 40px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}

.ftr-lockup {
  display: flex;
  align-items: center;
  gap: 20px;
  min-width: 0;
}

.ftr-logo {
  width: 132px;
  height: auto;
  display: block;
  flex-shrink: 0;
}

.ftr-lockup-rule {
  width: 1px;
  height: 44px;
  flex-shrink: 0;
  background: linear-gradient(
    180deg,
    transparent,
    rgba(255, 255, 255, 0.28) 22%,
    rgba(255, 255, 255, 0.28) 78%,
    transparent
  );
}

.ftr-cabinet-logo {
  width: 52px;
  height: 52px;
  object-fit: contain;
  flex-shrink: 0;
}

.ftr-cabinet-name {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.ftr-cabinet-name small {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--hmte-gold);
}

.ftr-cabinet-name strong {
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.05;
  color: #fff;
}

.ftr-masthead-note {
  display: grid;
  gap: 4px;
  margin: 0;
  text-align: right;
  font-size: 12px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.6);
}

.ftr-masthead-note span {
  /* .36 di atas navy cuma ~3.2:1, di bawah ambang AA 4.5:1 untuk teks 12px. */
  color: rgba(255, 255, 255, 0.58);
}

.tre-footer .top {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr 1fr;
  gap: 48px;
  padding: 52px 0 56px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.tre-footer .col h4 {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  /* .4 di atas navy cuma ~3.6:1, di bawah ambang AA 4.5:1 untuk teks 13px. */
  color: rgba(255, 255, 255, 0.6);
  margin: 0 0 20px;
}

.tre-footer .col a, 
.tre-footer .col p {
  font-size: var(--fs-sm);
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.7);
  margin: 0;
  display: block;
}

.tre-footer .col a {
  margin-bottom: 8px;
}

.tre-footer .col a:hover {
  color: var(--hmte-gold);
  opacity: 1;
}


.tre-footer .addr {
  font-size: 13px;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.5);
}

.tre-footer .col .addr + .addr {
  margin-top: 16px;
}

.tre-footer .bottom {
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  /* .35 di atas navy cuma ~3.1:1, di bawah ambang AA 4.5:1 untuk teks 13px. */
  color: rgba(255, 255, 255, 0.6);
  letter-spacing: 0.04em;
}

/* Focus and Outline States */
*:focus {
  outline: none;
}

*:focus-visible {
  outline: 2px solid var(--hmte-gold);
  outline-offset: 3px;
  border-radius: 2px;
}

/* ============================================================
   RESPONSIVE MEDIA QUERIES
   ============================================================ */
@media (max-width: 1180px) {
  .pillars-head {
    padding-bottom: 48px;
    margin-bottom: 48px;
  }

  .pillars-head-row {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .pillars-lead {
    max-width: none;
  }

  .pillars-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  
  .pillars-grid::before {
    display: none;
  }
  
  .pillar-card.offset,
  .pillar-card.offset:hover {
    transform: none;
  }
  
  .pillar-card:hover {
    transform: translateY(-4px);
  }
  
  .pillar-card:nth-child(3) {
    grid-column: 1 / -1;
    min-height: auto;
  }
  
  .pillars-output {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  
  .pillars-output a {
    justify-self: start;
  }
}

@media (max-width: 1100px) {
  .curr-head,
  .partners-head {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .partners-metrics {
    margin-left: 0;
  }

  .logo-set {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  
  .curr-h2, 
  .curr-lead {
    grid-row: auto;
