/* ============================================================
   FITUR 1: PROPERTIES DETAIL MODAL (OS-STYLE)
   ============================================================ */
.os-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(1, 7, 18, 0.5);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 300ms ease;
}

.os-modal-backdrop.active {
  opacity: 1;
  pointer-events: auto;
}

.os-modal-window {
  width: calc(100% - 32px);
  max-width: 650px;
  background: var(--bg-elevated);
  border: 1px solid var(--hmte-gold);
  border-radius: var(--radius-lg);
  box-shadow: 
    0 24px 64px -16px rgba(1, 15, 36, 0.6),
    0 0 0 1px rgba(245, 184, 46, 0.15);
  overflow: hidden;
  transform: translate3d(0, 16px, 0) scale(0.96);
  opacity: 0;
  transition: 
    transform 400ms cubic-bezier(0.16, 1, 0.3, 1),
    opacity 400ms ease;
}

.os-modal-backdrop.active .os-modal-window {
  transform: translate3d(0, 0, 0) scale(1);
  opacity: 1;
}

.os-modal-header {
  height: 46px;
  background: rgba(1, 31, 75, 0.03);
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  padding: 0 16px;
  justify-content: space-between;
  -webkit-user-select: none;
          user-select: none;
}

.os-modal-title {
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--fg-muted);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.os-modal-close-btn {
  background: none;
  border: none;
  color: var(--fg-muted);
  font-size: 24px;
  font-weight: 300;
  cursor: pointer;
  padding: 4px;
  line-height: 1;
  transition: color var(--dur-fast) var(--ease-out);
}

.os-modal-close-btn:hover {
  color: #ef4444;
}

.os-modal-body {
  padding: 32px;
}

.member-detail-layout {
  display: flex;
  gap: 32px;
  align-items: flex-start;
}

.detail-left {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  width: 160px;
  flex-shrink: 0;
}

.detail-avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  overflow: hidden;
  background: rgba(1, 31, 75, 0.04);
  border: 2px solid var(--hmte-gold);
  box-shadow: 0 8px 20px rgba(1, 31, 75, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--hmte-gold);
  transition: transform var(--dur-base) var(--ease-out);
}

.detail-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.detail-avatar svg {
  width: 48px;
  height: 48px;
}

.detail-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
  text-align: center;
  width: 100%;
}

.detail-right {
  flex: 1 1;
}

.detail-name {
  font-family: var(--font-display);
  font-size: var(--fs-h3);
  font-weight: 700;
  color: var(--hmte-navy);
  margin: 0 0 16px;
  letter-spacing: var(--tracking-tight);
}

.detail-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 16px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  margin-bottom: 20px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.meta-label {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--fg-muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.meta-val {
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--fg);
}

.detail-bio h4,
.detail-socials h4 {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--fg-muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin: 0 0 8px;
}

.detail-bio {
  margin-bottom: 24px;
}

.detail-bio p {
  margin: 0;
  font-size: var(--fs-sm);
  line-height: 1.6;
  color: var(--fg-muted);
}

.social-links {
  display: flex;
  gap: 12px;
}

.social-links a {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--fg-muted);
  transition: 
    border-color var(--dur-fast) var(--ease-out),
    color var(--dur-fast) var(--ease-out),
    background var(--dur-fast) var(--ease-out);
}

.social-links a:hover {
  border-color: var(--hmte-gold);
  color: var(--hmte-navy-deep);
  background: var(--hmte-gold-glow);
}

.social-empty {
  margin: 0;
  color: var(--fg-muted);
  font-size: var(--fs-sm);
  line-height: 1.5;
}

/* ============================================================
   FITUR 2: OS WINDOW FOLDER TABS & PROKER CARDS
   ============================================================ */
.window-tabs {
  display: flex;
  background: rgba(1, 31, 75, 0.02);
  border-bottom: 1px solid var(--line);
  padding: 0 20px;
  gap: 6px;
  -webkit-user-select: none;
          user-select: none;
}

.win-tab {
  background: none;
  border: 1px solid transparent;
  border-bottom: none;
  padding: 10px 18px;
  font-family: var(--font-body);
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--fg-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: -1px;
  border-top-left-radius: var(--radius-sm);
  border-top-right-radius: var(--radius-sm);
  position: relative;
  transition: 
    color var(--dur-fast) var(--ease-out),
    background var(--dur-fast) var(--ease-out);
}

.win-tab svg {
  stroke: currentColor;
  opacity: 0.7;
}

.win-tab:hover {
  color: var(--hmte-navy);
  background: rgba(1, 31, 75, 0.03);
}

.win-tab.win-tab.active {
  color: var(--hmte-navy);
  background: var(--bg-elevated);
  border-color: var(--line);
  border-bottom-color: var(--bg-elevated);
  z-index: 2;
}

.win-tab.win-tab.active::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--hmte-gold);
  border-top-left-radius: var(--radius-sm);
  border-top-right-radius: var(--radius-sm);
}

