.publication-feature:hover,
.publication-row:hover {
  border-color: rgba(245, 184, 46, 0.28);
}

.publication-feature-image,
.publication-row-image {
  overflow: hidden;
  background: var(--tre-paper);
  border-radius: var(--radius-sm);
}

.publication-feature-image img,
.publication-row-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.publication-feature-image {
  aspect-ratio: 16 / 10;
}

.publication-row {
  grid-template-columns: 116px minmax(0, 1fr) auto;
  text-align: left;
}

.publication-row-image {
  aspect-ratio: 4 / 3;
}

.publication-row p {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.schedule-row {
  grid-template-columns: 86px minmax(0, 1fr) minmax(180px, 0.24fr);
}

.schedule-row > span:not(.public-status) {
  line-height: 1.5;
  text-align: right;
  white-space: normal;
}

.schedule-date {
  display: grid;
  place-items: center;
  min-height: 72px;
  border-radius: var(--radius-sm);
  background: rgba(1, 31, 75, 0.06);
  color: var(--hmte-navy);
}

.schedule-date span {
  color: var(--hmte-gold-deep);
  font-family: var(--font-mono);
  font-size: var(--fs-eyebrow);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.schedule-date strong {
  font-family: var(--font-display);
  font-size: 20px;
  line-height: 1;
}

.announcement-row {
  grid-template-columns: minmax(0, 1fr) auto;
}

.public-form {
  display: grid;
  max-width: 820px;
  gap: 18px;
  padding: clamp(22px, 4vw, 32px);
  border: 1px solid rgba(1, 31, 75, 0.1);
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.76);
  box-shadow: var(--shadow-menu);
}

.public-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.public-form label {
  display: grid;
  gap: 8px;
  color: var(--hmte-navy);
  font-family: var(--font-mono);
  font-size: var(--fs-eyebrow);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.public-form input,
.public-form select,
.public-form textarea {
  width: 100%;
  min-height: 48px;
  padding: 0 14px;
  border: 1px solid rgba(1, 31, 75, 0.18);
  border-radius: var(--radius-sm);
  background: var(--tre-paper-deep);
  color: var(--fg);
  font: inherit;
  letter-spacing: 0;
  text-transform: none;
}

.public-form textarea {
  padding: 14px;
  resize: vertical;
}

.public-check-row {
  display: flex !important;
  grid-template-columns: none !important;
  gap: 10px !important;
  align-items: center;
}

.public-check-row input {
  width: 18px;
  min-height: 18px;
  accent-color: var(--hmte-gold);
}

@media (max-width: 920px) {
  .program-roadmap-overview,
  .program-roadmap-grid {
    grid-template-columns: 1fr;
  }

  .program-roadmap-current {
    margin: 0;
    border-radius: 0;
  }

  .program-roadmap-index {
    position: static;
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .program-roadmap-card {
    scroll-margin-top: 120px;
  }

  .program-board,
  .publication-layout,
  .publication-feature,
  .public-feature-panel,
  .public-group-heading {
    grid-template-columns: 1fr;
  }

  .program-board-nav,
  .program-board-summary,
  .publication-side {
    position: static;
  }

  .program-board-main {
    order: 1;
  }

  .program-board-nav {
    order: 2;
  }

  .program-board-summary {
    order: 3;
  }

  .program-board-nav {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .program-board-nav > .public-label,
  .program-board-note {
    grid-column: 1 / -1;
  }

  .public-row,
  .publication-row,
  .schedule-row,
  .announcement-row {
    grid-template-columns: 1fr;
  }

  .publication-row-image {
    width: min(220px, 100%);
  }

  .public-grid,
  .public-grid.two {
    grid-template-columns: 1fr;
  }

  .public-hero {
    padding-top: 124px;
  }

  .public-form-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .program-roadmap-intro,
  .program-roadmap-current,
  .program-roadmap-card {
    padding: 20px;
  }

  .program-roadmap-stats,
  .program-roadmap-index {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .program-roadmap-feature,
  .program-roadmap-items li {
    grid-template-columns: 1fr;
  }

  .program-roadmap-items em {
    white-space: normal;
  }

  .program-board-nav {
    display: flex;
    overflow-x: auto;
    padding-bottom: 4px;
    scroll-snap-type: x mandatory;
  }

  .program-board-nav > .public-label,
  .program-board-note {
    display: none;
  }

  .program-board-nav-item {
    min-width: 168px;
    scroll-snap-align: start;
  }

  .public-segments {
    width: 100%;
  }

  .public-segments a {
    flex: 1 1 140px;
  }

  .public-section {
    padding-inline: var(--gutter-sm);
  }
}

/* ============================================================
   ADMIN AUTH
   ============================================================ */
.admin-auth-page,
.admin-dashboard {
