}

.admin-form-success {
  margin: 0 0 16px;
  padding: 12px 14px;
  border: 1px solid rgba(47, 125, 89, 0.22);
  border-radius: var(--radius-sm);
  background: rgba(47, 125, 89, 0.08);
  color: var(--hmte-success);
  line-height: 1.5;
}

.admin-login-note {
  margin: 0;
  color: var(--fg-muted);
}

.admin-status-panel {
  width: min(620px, 100%);
  padding: clamp(28px, 6vw, 52px);
}

.admin-status-panel h1 {
  font-size: clamp(34px, 5vw, 64px);
  line-height: 1;
  color: var(--hmte-navy);
}

.admin-dashboard {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
}

.admin-sidebar {
  min-height: 100vh;
