  background: rgba(255, 255, 255, 0.64);
  color: var(--hmte-navy);
  cursor: pointer;
  font-family: var(--font-body);
  font-size: var(--fs-eyebrow);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.admin-tabbar button[aria-selected='true'] {
