.admin-empty-state {
  margin-top: 16px;
  padding: 28px;
  background: rgba(255, 255, 255, 0.62);
}

.admin-empty-state h3 {
  color: var(--hmte-navy);
  font-size: clamp(28px, 4vw, 46px);
  line-height: 1;
}

.admin-empty-state p {
  max-width: 720px;
  margin: 14px 0 0;
