/* ============================================================
   REDUCED MOTION GUARD
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, 
  *::before, 
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  
  .logo-track {
    animation: none !important;
  }

  /* Marquee off: hold the activity wall centered instead of left-clipped. */
  .hero-grid-row {
    transform: translate3d(calc((100vw - 100%) / 2), 0, 0) !important;
  }
  
  .badge-hero .dot {
    animation: none !important;
  }
}

/* ============================================================
   INLINE FIELD VALIDATION ERRORS
   ============================================================ */
.field-error-inline {
  display: block;
  margin-top: 4px;
  color: #b91c1c;
  font-size: var(--fs-eyebrow);
  font-weight: 500;
  line-height: 1.4;
  animation: field-error-appear 200ms var(--ease-out);
}

@keyframes field-error-appear {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.admin-field input.field-has-error,
.admin-field select.field-has-error,
.admin-field textarea.field-has-error,
.public-form input.field-has-error,
.public-form select.field-has-error,
.public-form textarea.field-has-error {
  border-color: rgba(185, 28, 28, 0.6) !important;
  background-color: rgba(185, 28, 28, 0.02) !important;
}

.admin-field input.field-has-error:focus,
.admin-field select.field-has-error:focus,
.admin-field textarea.field-has-error:focus {
  border-color: #b91c1c !important;
  box-shadow: 0 0 0 1px #b91c1c !important;
}

/* ============================================================
   REACT REFACTOR ADJUSTMENTS
   Button-element resets for cards that became real <button>s during
   the de-legacy rebuild, plus the restored hero headline/tagline/CTA.
   ============================================================ */

/* Member card is now a real button; neutralize UA button defaults so it
   keeps the exact card layout while being keyboard-operable. */
.member-card {
  width: 100%;
  font: inherit;
  color: inherit;
  background: transparent;
  text-align: inherit;
  appearance: none;
  -webkit-appearance: none;
}

.member-card:focus-visible {
  outline: 2px solid var(--hmte-gold);
  outline-offset: 2px;
}

/* ============================================================
   GROUPED NAV DROPDOWNS
   "Organisasi" / "Kabar" groups: desktop opens on hover + keyboard
   focus, click toggles for touch; mobile shows children expanded.
   ============================================================ */
.nav-group {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.nav-group-trigger {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 0;
  font: inherit;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.72);
  background: none;
  border: 0;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
}

.nav-group-trigger svg {
  transition: transform var(--dur-base) var(--ease-out);
}

.nav-group-trigger:hover,
.nav-group-trigger.active,
.nav-group:focus-within .nav-group-trigger,
.nav-group.is-open .nav-group-trigger {
  color: var(--hmte-gold);
}

.nav-group:hover .nav-group-trigger svg,
.nav-group:focus-within .nav-group-trigger svg,
.nav-group.is-open .nav-group-trigger svg {
  transform: rotate(180deg);
}

.nav-group-trigger:focus-visible {
  outline: 2px solid var(--hmte-gold);
  outline-offset: 4px;
  border-radius: var(--radius-sm);
}

.nav-submenu {
  position: absolute;
  top: calc(100% + 12px);
  left: 50%;
  transform: translateX(-50%) translateY(-6px);
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 210px;
  padding: 8px;
  background: rgba(1, 31, 75, 0.97);
  border: 1px solid rgba(245, 184, 46, 0.22);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-menu);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity var(--dur-base) var(--ease-out),
              transform var(--dur-base) var(--ease-out),
              visibility var(--dur-base);
  z-index: var(--z-header);
}

/* Invisible hover bridge across the gap to the trigger. */
.nav-submenu::before {
  content: '';
  position: absolute;
  top: -12px;
  left: 0;
  right: 0;
  height: 12px;
}

.nav-group:hover .nav-submenu,
.nav-group:focus-within .nav-submenu,
.nav-group.is-open .nav-submenu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.nav-submenu a {
  padding: 9px 12px;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  color: rgba(255, 255, 255, 0.82);
}

.nav-submenu a:hover,
.nav-submenu a.active {
  background: rgba(245, 184, 46, 0.12);
  color: var(--hmte-gold);
}

.ftr-pending {
  display: block;
  color: var(--fg-faint);
  cursor: default;
}

@media (prefers-reduced-motion: reduce) {
  .nav-group-trigger svg,
  .nav-submenu {
    transition: none;
  }

  .nav-group:hover .nav-group-trigger svg,
  .nav-group:focus-within .nav-group-trigger svg,
  .nav-group.is-open .nav-group-trigger svg {
    transform: none;
  }
}

@media (max-width: 768px) {
  .nav-group {
    display: block;
    width: 100%;
  }

  .nav-group-trigger {
    width: 100%;
    justify-content: flex-start;
    padding: 11px 12px;
    cursor: default;
  }

  .nav-group-trigger svg {
    display: none;
  }

  .nav-submenu {
    position: static;
    transform: none;
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    min-width: 0;
    gap: 0;
    padding: 2px 0 6px 14px;
    background: transparent;
    border: 0;
    box-shadow: none;
  }

  .nav-submenu::before {
    display: none;
  }
}

/* ============================================================
   NAVBAR BRAND LOGO
   Real HMTE logo replaces the text wordmark; sits on the dark
   header so the logo's screen blend reads cleanly.
   ============================================================ */
.tre-header .brand {
  text-decoration: none;
  flex-shrink: 0;
}

.tre-header .brand-logo {
  height: 26px;
  width: auto;
  display: block;
}

.tre-header .brand:focus-visible {
