    height: 22px;
  }
}

/* ============================================================
   LANDING HERO SHOWCASE
   Logo-only brand stage with an automatic activity-photo carousel.
   ============================================================ */
.tre-hero.hero-showcase {
  position: relative;
  display: block;
  min-height: 100svh;
  padding: 12px;
  overflow: clip;
  background: var(--tre-black);
  color: var(--tre-paper);
  border: 0;
}

.hero-showcase-frame {
  position: relative;
  width: 100%;
  min-height: calc(100svh - 24px);
  overflow: clip;
  isolation: isolate;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 22px;
  background: var(--hmte-navy-deep);
}

.hero-showcase-slides,
.hero-showcase-slide,
.hero-showcase-wash,
.hero-showcase-grid {
  position: absolute;
  inset: 0;
}

.hero-showcase-slide {
  margin: 0;
  opacity: 0;
  transform: scale(1.07) translate3d(1.5%, 0, 0);
  transition:
    opacity 1.2s var(--ease-in-out),
    transform 7.4s linear;
  will-change: opacity, transform;
}

.hero-showcase-slide.is-active {
  opacity: 1;
  transform: scale(1.015) translate3d(0, 0, 0);
}

.hero-showcase-image {
  object-fit: cover;
  object-position: center;
  filter: saturate(0.78) contrast(1.04) brightness(0.78);
}

.hero-showcase-wash {
  z-index: 1;
  background:
    radial-gradient(circle at 50% 48%, rgba(245, 184, 46, 0.11), transparent 24%),
    linear-gradient(180deg, rgba(1, 19, 51, 0.32), rgba(1, 19, 51, 0.18) 38%, rgba(1, 19, 51, 0.88) 100%),
    linear-gradient(90deg, rgba(1, 19, 51, 0.62), rgba(1, 31, 75, 0.08) 48%, rgba(1, 19, 51, 0.5));
  pointer-events: none;
}

.hero-showcase-grid {
  z-index: 2;
  top: 42%;
  opacity: 0.32;
  background-image: radial-gradient(rgba(255, 255, 255, 0.42) 0.7px, transparent 0.7px);
  background-size: 18px 18px;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 32%, #000);
          mask-image: linear-gradient(to bottom, transparent, #000 32%, #000);
  pointer-events: none;
}

.hero-showcase-frame::before {
  position: absolute;
  z-index: 3;
  inset: 20px;
  content: '';
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 13px;
  pointer-events: none;
}

.hero-showcase-frame::after {
  position: absolute;
  z-index: 3;
  right: -12vw;
  bottom: -34vw;
  width: 70vw;
  aspect-ratio: 1;
  content: '';
  border: 1px solid rgba(245, 184, 46, 0.22);
  border-radius: 50%;
  box-shadow:
    0 0 0 7vw rgba(245, 184, 46, 0.025),
    0 0 0 15vw rgba(245, 184, 46, 0.018);
  pointer-events: none;
}

.hero-showcase-brand {
  position: absolute;
  z-index: 4;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: min(58vw, 700px);
  transform: translate(-50%, -47%);
  animation: hero-showcase-brand-in 1.1s var(--ease-out) both;
}

.hero-showcase-logo-aura {
  position: absolute;
  z-index: -1;
  width: 132%;
  aspect-ratio: 1.8;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(1, 19, 51, 0.9) 0%, rgba(1, 19, 51, 0.66) 38%, transparent 73%);
  filter: blur(18px);
}

.hero-showcase-logo {
  width: 100%;
  height: auto;
  object-fit: contain;
  filter:
    drop-shadow(0 2px 0 rgba(255, 255, 255, 0.08))
    drop-shadow(0 28px 44px rgba(0, 0, 0, 0.66));
}

.hero-showcase-pagination {
  position: absolute;
  z-index: 5;
  right: 42px;
  bottom: 38px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px;
}

.hero-showcase-pagination button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
}

.hero-showcase-pagination button span {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.48);
  transition:
    width var(--dur-base) var(--ease-out),
    background var(--dur-base) var(--ease-out),
    box-shadow var(--dur-base) var(--ease-out);
}

.hero-showcase-pagination button:hover span,
.hero-showcase-pagination button:focus-visible span {
  background: #fff;
}

.hero-showcase-pagination button:focus-visible {
  outline: 1px solid var(--hmte-gold);
