}

.hero-showcase-pagination button.is-active span {
  width: 24px;
  background: var(--hmte-gold);
  box-shadow: 0 0 16px rgba(245, 184, 46, 0.55);
}

@keyframes hero-showcase-brand-in {
  from {
    opacity: 0;
    transform: translate(-50%, -42%) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -47%) scale(1);
