/* ============================================================
   LANDING HERO SCROLL STORY
   Photos advance with scroll; the final phase reveals a wallpaper and logo.
   ============================================================ */
.tre-hero.hero-scroll-story {
  --hero-scroll-progress: 0;
  --hero-logo-progress: 0;
  --hero-wall-progress: 0;
  --hero-photo-opacity: 1;
  --hero-logo-offset: 39svh;
  --hero-logo-scale: 1;
  --hero-wall-opacity: 0;
  --hero-wall-scale: 0.88;
  --hero-wall-shift: 18px;
  --hero-grid-opacity: 0.12;
  --hero-aura-opacity: 0.18;
  --hero-gold-glow: 0.04;
  --hero-final-marker-width: 18px;
  --hero-final-marker-alpha: 0.3;
  position: relative;
  display: block;
  height: 720svh;
  min-height: 720svh;
  padding: 0;
  overflow: visible;
  border: 0;
  background: var(--tre-black);
}

.hero-scroll-stage {
  position: sticky;
  z-index: 1;
  top: 0;
  width: 100%;
  height: 100svh;
  overflow: clip;
  isolation: isolate;
  background: var(--hmte-navy-deep);
}

.hero-scroll-slides,
.hero-scroll-slide,
.hero-scroll-wall,
.hero-scroll-tone,
.hero-scroll-grid {
  position: absolute;
  inset: 0;
}

.hero-scroll-slide {
  margin: 0;
  opacity: 0;
  transform: scale(1.045) translate3d(0, 1.6%, 0);
  transition:
    opacity 640ms var(--ease-in-out),
    transform 1400ms cubic-bezier(0.16, 1, 0.3, 1);
}

.hero-scroll-slide.is-active {
  opacity: var(--hero-photo-opacity);
  transform: scale(1) translate3d(0, 0, 0);
  will-change: opacity, transform;
}

.hero-scroll-slide-image {
  object-fit: cover;
  object-position: center;
  filter: saturate(0.82) contrast(1.04) brightness(0.82);
}

.hero-scroll-wall {
  z-index: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(0, 1fr));
  gap: 7px;
  padding: 7px;
  transform: scale(var(--hero-wall-scale));
  filter: saturate(0.78);
  will-change: transform;
}

/*
 * Each tile resolves on its own slice of the wall progress, so the wallpaper
 * assembles piece by piece behind the logo instead of arriving as one block.
 */
.hero-scroll-wall-tile {
  --tile-start: calc(var(--wall-tile-index) * 0.06);
  --tile-progress: clamp(0, calc((var(--hero-wall-progress) - var(--tile-start)) / 0.6), 1);
  position: relative;
  min-width: 0;
  min-height: 0;
  margin: 0;
  overflow: hidden;
  opacity: var(--tile-progress);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 4px;
  transform:
    translateY(calc((1 - var(--tile-progress)) * 34px))
    scale(calc(0.955 + var(--tile-progress) * 0.045));
}

.hero-scroll-wall-image {
  object-fit: cover;
  filter: brightness(0.72) contrast(1.06);
}

.hero-scroll-tone {
  z-index: 2;
  background:
    radial-gradient(circle at 50% 52%, rgba(245, 184, 46, var(--hero-gold-glow)), transparent 25%),
    linear-gradient(180deg, rgba(1, 19, 51, 0.16), rgba(1, 19, 51, 0.18) 48%, rgba(1, 19, 51, 0.76) 100%),
    linear-gradient(90deg, rgba(1, 19, 51, 0.38), transparent 48%, rgba(1, 19, 51, 0.34));
  pointer-events: none;
}

.hero-scroll-grid {
  z-index: 3;
  top: 48%;
  opacity: var(--hero-grid-opacity);
  background-image: radial-gradient(rgba(255, 255, 255, 0.46) 0.7px, transparent 0.7px);
  background-size: 19px 19px;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 26%, #000);
          mask-image: linear-gradient(to bottom, transparent, #000 26%, #000);
  pointer-events: none;
}

.hero-scroll-logo-wrap {
  position: absolute;
  z-index: 5;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: clamp(132px, 15vw, 210px);
  transform:
    translate(-50%, calc(-50% + var(--hero-logo-offset)))
    scale(var(--hero-logo-scale));
  transform-origin: center;
  will-change: transform;
}

.hero-scroll-logo-aura {
  position: absolute;
  z-index: -1;
  width: 138%;
  aspect-ratio: 1.75;
  opacity: var(--hero-aura-opacity);
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(1, 19, 51, 0.94), rgba(1, 19, 51, 0.6) 42%, transparent 74%);
  filter: blur(12px);
}

.hero-scroll-logo {
  width: 100%;
  height: auto;
  object-fit: contain;
  filter:
    drop-shadow(0 2px 0 rgba(255, 255, 255, 0.08))
    drop-shadow(0 18px 32px rgba(0, 0, 0, 0.68));
}

.hero-scroll-markers {
  position: absolute;
  z-index: 6;
  right: 30px;
  bottom: 28px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.hero-scroll-markers span {
  display: block;
  width: 38px;
  height: 2px;
  background: rgba(255, 255, 255, 0.3);
  transform: scaleX(0.4737);
  transform-origin: left center;
  transition: transform 300ms var(--ease-out), background 300ms var(--ease-out);
}

.hero-scroll-markers span.is-active {
  transform: scaleX(1);
  background: var(--hmte-gold);
}

.hero-scroll-marker-final {
  /* Ukurannya sudah diset per-frame lewat scroll (bukan transition CSS), jadi
     transform skala dari aturan dasar di atas tidak relevan di sini dan harus
     dimatikan supaya lebarnya tidak terhitung dua kali. */
  width: var(--hero-final-marker-width) !important;
  background: rgba(245, 184, 46, var(--hero-final-marker-alpha)) !important;
  transform: none !important;
}

.landing-nav-stage--after-hero {
  margin: 0;
  background: transparent;
}

.landing-nav-stage--after-hero + main {
  margin-top: -88px;
  padding-top: 0;
  background: var(--tre-off-white);
}

@media (max-width: 760px) {
  .tre-hero.hero-scroll-story {
    height: 660svh;
    min-height: 660svh;
  }

  .hero-scroll-wall {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: repeat(3, minmax(0, 1fr));
    gap: 5px;
    padding: 5px;
  }

  .hero-scroll-logo-wrap {
    width: clamp(116px, 34vw, 150px);
    transform:
      translate(-50%, calc(-50% + var(--hero-logo-offset)))
      scale(var(--hero-logo-scale));
  }

  .hero-scroll-markers {
    right: 18px;
    bottom: 18px;
    gap: 6px;
  }

  .hero-scroll-markers span {
    width: 12px;
  }

  .hero-scroll-markers span.is-active {
    width: 26px;
  }

  .landing-nav-stage--after-hero + main {
    margin-top: -76px;
    padding-top: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tre-hero.hero-scroll-story {
    height: 100svh;
    min-height: 100svh;
  }

  .hero-scroll-stage {
    position: relative;
  }

  .hero-scroll-slide,
  .hero-scroll-wall,
  .hero-scroll-logo-wrap,
  .hero-scroll-markers span {
    transition: none;
  }
}

/* ============================================================
   ORGANIZATION EXPERIENCE — selector to neutral workspace
   ============================================================ */
.organization-experience {
  position: relative;
  overflow: clip;
  background:
    radial-gradient(circle at 88% 18%, rgba(245, 184, 46, 0.08), transparent 24rem),
    var(--tre-off-white);
}

.organization-selector.tre-pillars {
  padding-bottom: 56px;
  background: transparent;
}

.organization-selector .kabinet-card {
  isolation: isolate;
}

.organization-selector .kabinet-card.is-selected {
  border-color: var(--hmte-gold);
  box-shadow:
    0 0 0 3px rgba(245, 184, 46, 0.18),
    0 22px 42px rgba(1, 31, 75, 0.1);
  transform: translateY(-5px);
}

.organization-selector .kabinet-card.is-selected .kabinet-dot {
  transform: scale(1.8);
  box-shadow: 0 0 0 5px rgba(245, 184, 46, 0.14);
}

.organization-reveal {
  width: min(var(--content-max), calc(100% - (var(--gutter) * 2)));
  margin-inline: auto;
  padding-bottom: clamp(80px, 10vw, 150px);
}

.organization-reveal.is-idle {
  display: none;
}

.organization-confirmation {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
