  align-items: end;
  gap: clamp(28px, 5vw, 70px);
  padding-block: clamp(28px, 4.5vh, 46px);
}

.proker-console-heading h1 {
  font-family: var(--font-display);
  font-size: clamp(38px, 5.4vw, 68px);
  line-height: 0.96;
  letter-spacing: -0.04em;
  text-wrap: balance;
  color: #fff;
}

.proker-console-heading p {
  max-width: 58ch;
  margin-top: 16px;
  font-size: clamp(15px, 1.5vw, 18px);
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.8);
}

.proker-console-media {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.24);
  aspect-ratio: 3 / 2;
  background: rgba(255, 255, 255, 0.06);
}

.proker-console-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.proker-console-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.proker-console-strip > div {
  padding: 16px 18px 0 0;
}

.proker-console-strip > div + div {
  padding-left: 18px;
  border-left: 1px solid rgba(255, 255, 255, 0.18);
}

.proker-console-strip dt {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.62);
}

.proker-console-strip dd {
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #fff;
}

.proker-console-strip dd.status-selesai {
  color: #7fd7a6;
}

.proker-console-strip dd.status-sedang-berjalan {
  color: var(--hmte-gold);
}

.proker-console-strip dd.status-terencana {
  color: #e9c27f;
}

.proker-board-section {
  padding-block: clamp(36px, 6vh, 64px) clamp(70px, 10vh, 110px);
}

.proker-board {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.88fr);
  grid-template-areas:
    'desc focus'
    'timeline timeline'
    'docs related';
  gap: 1px;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.18);
  background: rgba(var(--hmte-navy-rgb), 0.18);
}

.proker-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: #fff;
}

.proker-panel-desc { grid-area: desc; }
.proker-panel-focus { grid-area: focus; }
.proker-panel-timeline { grid-area: timeline; }
.proker-panel-docs { grid-area: docs; }
.proker-panel-docs.is-wide { grid-column: 1 / -1; }
.proker-panel-related { grid-area: related; }

.proker-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  padding: 13px 20px;
  border-bottom: 1px solid rgba(var(--hmte-navy-rgb), 0.14);
}

.proker-panel-head h2 {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--hmte-navy);
}

.proker-panel-head span {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--hmte-gold-deep);
}

.proker-panel-body {
  padding: 20px;
}

.proker-lead {
  font-size: clamp(16px, 1.6vw, 19px);
  line-height: 1.6;
  color: var(--hmte-navy);
}

.proker-panel-body p + p {
  margin-top: 14px;
  max-width: 68ch;
  font-size: 14px;
  line-height: 1.7;
  color: var(--text-muted);
}

.proker-panel-link {
  display: inline-flex;
  margin-top: 20px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--hmte-gold-deep);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--hmte-navy);
}

.proker-focus-list {
  flex: 1 1;
  list-style: none;
  display: flex;
  flex-direction: column;
}

.proker-focus-list li {
  flex: 1 1;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  padding: 16px 20px;
}

.proker-focus-list li + li {
  border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
}

.proker-focus-list span {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--hmte-gold-deep);
}

.proker-focus-list p {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.45;
  color: var(--hmte-navy);
}

.proker-track-rail {
  height: 3px;
  background: rgba(var(--hmte-navy-rgb), 0.1);
}

.proker-track-rail span {
  display: block;
  height: 100%;
  background: var(--hmte-gold-deep);
}

.proker-track {
  display: grid;
  grid-template-columns: repeat(var(--track-count, 4), minmax(0, 1fr));
  border-bottom: 1px solid rgba(var(--hmte-navy-rgb), 0.14);
}

.proker-track-tab {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 7px;
  padding: 15px 18px 17px;
  border: 0;
  text-align: left;
  font: inherit;
  background: transparent;
  cursor: pointer;
  transition: background-color 0.18s ease-out;
}

.proker-track-tab + .proker-track-tab {
  border-left: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
}

.proker-track-tab:hover {
  background: rgba(var(--hmte-navy-rgb), 0.04);
}

.proker-track-tab[aria-selected='true'] {
  background: rgba(var(--hmte-gold-rgb), 0.12);
  box-shadow: inset 0 -2px 0 var(--hmte-gold-deep);
}

.proker-track-tab:focus-visible {
  outline: 2px solid var(--hmte-gold-deep);
  outline-offset: -2px;
}

.proker-track-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.proker-track-state i {
  width: 7px;
  height: 7px;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.35);
  border-radius: 50%;
}

.proker-track-tab.is-done .proker-track-state {
  color: var(--hmte-success);
}

.proker-track-tab.is-done .proker-track-state i {
  border-color: var(--hmte-success);
  background: var(--hmte-success);
}

.proker-track-tab.is-active .proker-track-state {
  color: var(--hmte-gold-deep);
}

.proker-track-tab.is-active .proker-track-state i {
  border-color: var(--hmte-gold-deep);
  background: var(--hmte-gold);
  animation: proker-pulse 2.2s ease-out infinite;
}

.proker-track-tab strong {
  font-family: var(--font-display);
  font-size: clamp(16px, 1.6vw, 20px);
  letter-spacing: -0.025em;
  color: var(--hmte-navy);
}

.proker-track-tab time {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--text-muted);
}

@keyframes proker-pulse {
  0% { box-shadow: 0 0 0 0 rgba(var(--hmte-gold-rgb), 0.5); }
  70% { box-shadow: 0 0 0 7px rgba(var(--hmte-gold-rgb), 0); }
  100% { box-shadow: 0 0 0 0 rgba(var(--hmte-gold-rgb), 0); }
}

.proker-track-detail {
  padding: 22px 20px 24px;
}

.proker-track-readout {
  animation: proker-readout 0.24s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes proker-readout {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.proker-track-readout-meta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.proker-track-readout-meta time {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.proker-track-badge {
  padding: 5px 9px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--hmte-navy);
  background: rgba(var(--hmte-navy-rgb), 0.07);
}

.proker-track-badge.is-done {
  color: var(--hmte-success);
  background: rgba(47, 125, 89, 0.1);
}

.proker-track-badge.is-active {
  color: var(--hmte-gold-deep);
  background: rgba(var(--hmte-gold-rgb), 0.16);
}

.proker-track-readout h3 {
  margin-top: 12px;
  font-family: var(--font-display);
  font-size: clamp(22px, 2.4vw, 30px);
  letter-spacing: -0.03em;
  color: var(--hmte-navy);
}

.proker-track-readout p {
  max-width: 68ch;
  margin-top: 8px;
  font-size: 14px;
  line-height: 1.65;
  color: var(--text-muted);
}

.proker-doc-list {
  list-style: none;
}

.proker-doc-list li {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px 20px;
}

.proker-doc-list li + li {
  border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
}

.proker-doc-format {
  justify-self: start;
  padding: 5px 7px;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.22);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: var(--hmte-navy);
}

.proker-doc-list p {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--hmte-navy);
}

.proker-doc-status {
  padding: 5px 9px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--hmte-warning);
  background: rgba(183, 121, 31, 0.1);
}

.proker-doc-status.is-ready {
  color: var(--hmte-success);
  background: rgba(47, 125, 89, 0.1);
}

.proker-doc-note {
  margin-top: auto;
  padding: 14px 20px;
  border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-muted);
}

.proker-related-list {
  flex: 1 1;
  list-style: none;
  display: flex;
  flex-direction: column;
}

.proker-related-list li {
  flex: 1 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  padding: 14px 20px;
}

.proker-related-list li + li {
  border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
}

.proker-related-list h3 {
  font-size: 14px;
  font-weight: 600;
  color: var(--hmte-navy);
}

.proker-related-list h3 + p {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
  margin-top: 4px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-muted);
}

.proker-related-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.proker-related-meta span,
.proker-related-meta time {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.proker-related-meta time {
  color: var(--text-muted);
}

.proker-related-meta .status-selesai { color: var(--hmte-success); }
.proker-related-meta .status-sedang-berjalan { color: var(--hmte-teal); }
.proker-related-meta .status-terencana { color: var(--hmte-warning); }

@media (max-width: 1000px) {

  .proker-board {
    grid-template-columns: 1fr;
    grid-template-areas:
      'desc'
      'focus'
      'timeline'
      'docs'
      'related';
  }

  .proker-console-main {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .proker-console-media {
    max-width: 420px;
  }

  .program-featured-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {

  .program-featured-heading,
  .program-catalog-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .program-catalog-search {
    width: 100%;
  }

  .program-catalog-item {
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 16px;
  }

  .program-catalog-side {
    grid-column: 2;
    justify-items: start;
  }

  .proker-console {
    padding-top: 108px;
  }

  .proker-console-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .proker-console-strip > div {
    padding-right: 0;
  }

  .proker-console-strip > div:nth-child(odd) {
    padding-left: 0;
    border-left: 0;
  }

  .proker-console-strip > div:nth-child(n + 3) {
    margin-top: 14px;
  }

  .proker-track {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .proker-track-tab:nth-child(odd) {
    border-left: 0;
  }

  .proker-track-tab:nth-child(n + 3) {
    border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
  }
}

@media (max-width: 520px) {
  .program-featured-grid {
    grid-template-columns: 1fr;
  }

  .program-featured-copy {
    min-height: 220px;
  }

  .proker-console-path {
    display: none;
  }

  .proker-track {
    grid-template-columns: 1fr;
  }

  .proker-track-tab {
    border-left: 0;
  }

  .proker-track-tab + .proker-track-tab {
    border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.1);
  }

  .proker-doc-list li {
    grid-template-columns: 46px minmax(0, 1fr);
  }

  .proker-doc-status {
    grid-column: 2;
    justify-self: start;
  }

  .proker-related-list li {
    grid-template-columns: 1fr;
  }

  .proker-related-meta {
    flex-direction: row;
    align-items: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  .program-featured-card,
  .program-featured-media img,
  .proker-track-tab {
    transition: none;
  }

  .proker-track-tab.is-active .proker-track-state i,
  .proker-track-readout {
    animation: none;
  }
}

/* Public information surfaces for announcements and contact. */
.announcement-shell, .contact-shell { width: min(1180px, calc(100vw - 64px)); margin-inline: auto; }
.announcement-hero { min-height: min(720px, 88svh); padding: 148px 0 46px; color: var(--tre-off-white); background: var(--hmte-navy-deep); }
.announcement-hero .announcement-shell { min-height: calc(min(720px, 88svh) - 194px); display: flex; flex-direction: column; }
.announcement-hero-topline, .announcement-kicker, .announcement-date, .announcement-board-heading > p, .contact-kicker, .contact-section-heading > span, .contact-detail-label { font-family: var(--font-mono); font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; }
.announcement-hero-topline { display: flex; justify-content: space-between; padding-bottom: 18px; color: rgba(255,255,255,.52); border-bottom: 1px solid rgba(255,255,255,.18); }
.announcement-hero-copy { max-width: 900px; margin: auto 0; }
.announcement-kicker, .contact-kicker { margin: 0 0 24px; color: var(--hmte-gold); }
.announcement-hero h1, .contact-hero h1 { max-width: 10ch; margin: 0; font-family: var(--font-display); font-size: clamp(62px, 9.4vw, 132px); font-weight: 500; line-height: .88; letter-spacing: -.06em; text-wrap: balance; }
.announcement-hero h1 em { color: var(--hmte-gold); font-style: normal; }
.announcement-hero-copy > p:last-child { max-width: 570px; margin: 32px 0 0; color: rgba(255,255,255,.7); font-size: 17px; line-height: 1.75; }
.announcement-scroll-cue { display: inline-flex; align-items: center; justify-content: space-between; width: min(100%,288px); color: rgba(255,255,255,.72); font-family: var(--font-mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; }
.announcement-scroll-cue span { color: var(--hmte-gold); font-size: 20px; }
.announcement-board { padding: 90px 0 110px; background: var(--tre-off-white); }
.announcement-board-heading, .contact-section-heading { display: flex; align-items: end; justify-content: space-between; gap: 32px; margin-bottom: 38px; }
.announcement-board-heading > div > span { color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; }
.announcement-board-heading h2, .contact-section-heading h2 { margin: 10px 0 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: clamp(36px,5vw,66px); font-weight: 500; line-height: .95; letter-spacing: -.04em; }
.announcement-board-heading > p { margin: 0 0 5px; color: var(--fg-muted); }
.announcement-feature { display: grid; grid-template-columns: 90px minmax(0,1fr) auto; gap: 28px; align-items: start; padding: 42px 0; border-top: 2px solid var(--hmte-navy); border-bottom: 1px solid rgba(1,31,75,.18); }
.announcement-feature-number, .announcement-row-index { color: var(--hmte-gold-deep); font-family: var(--font-display); font-size: 26px; line-height: 1; }
.announcement-date { display: block; color: var(--hmte-teal); }
.announcement-feature h3, .announcement-row h3 { margin: 12px 0 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: clamp(31px,4vw,52px); font-weight: 500; line-height: 1.02; letter-spacing: -.035em; }
.announcement-feature p { max-width: 720px; margin: 19px 0 0; color: var(--fg-muted); font-size: 17px; line-height: 1.75; }
.announcement-feature-status { display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; color: var(--hmte-success); font-family: var(--font-mono); font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.announcement-feature-status span { width: 8px; height: 8px; background: currentColor; border-radius: 50%; }
.announcement-row { display: grid; grid-template-columns: 90px minmax(220px,.7fr) minmax(280px,1fr); gap: 28px; padding: 30px 0; border-bottom: 1px solid rgba(1,31,75,.14); }
.announcement-row h3 { font-size: clamp(23px,2.6vw,33px); }
.announcement-row p { margin: 26px 0 0; color: var(--fg-muted); font-size: 14px; line-height: 1.7; }
.announcement-note { padding: 30px 0; color: var(--tre-off-white); background: var(--hmte-navy); }
.announcement-note-inner { display: flex; align-items: center; justify-content: space-between; gap: 28px; }
.announcement-note p { max-width: 620px; margin: 0; line-height: 1.65; }
.announcement-note a, .contact-detail--accent a { display: inline-flex; align-items: center; gap: 10px; color: var(--hmte-gold); font-family: var(--font-mono); font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; }
.announcement-note a span, .contact-detail--accent a span { font-size: 18px; transition: transform var(--dur-base) var(--ease-out); }
.announcement-note a:hover span, .contact-detail--accent a:hover span { transform: translateX(4px); }
