.contact-hero h1 { color: var(--hmte-navy); }
.contact-hero h1 span { color: var(--hmte-gold-deep); }
.contact-hero-copy > p:last-child { max-width: 500px; margin: 30px 0 0; color: var(--fg-muted); font-size: 17px; line-height: 1.75; }
.contact-hero-mark { position: relative; display: grid; gap: 4px; justify-items: end; padding: 32px 0 8px; color: var(--hmte-navy); font-family: var(--font-mono); font-size: 12px; font-weight: 600; letter-spacing: .12em; }
.contact-hero-mark::before { position: absolute; top: 0; right: -10%; width: min(330px,26vw); aspect-ratio: 1; content: ''; border: 1px solid rgba(1,31,75,.2); border-radius: 50%; box-shadow: 0 0 0 28px rgba(245,184,46,.15), 0 0 0 56px rgba(1,31,75,.05); }
.contact-hero-mark strong { position: relative; color: var(--hmte-gold-deep); font-family: var(--font-display); font-size: clamp(78px,11vw,144px); font-weight: 500; line-height: .72; letter-spacing: -.08em; }
.contact-hero-mark span { position: relative; }
.contact-channels, .contact-details { padding: 82px 0; }
.contact-section-heading { justify-content: flex-start; align-items: baseline; gap: 20px; }
.contact-section-heading > span { color: var(--hmte-gold-deep); }
.contact-section-heading h2 { margin: 0; font-size: clamp(34px,4vw,55px); }
.contact-primary-channel { display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: 28px; align-items: center; padding: 36px; color: var(--tre-off-white); background: var(--hmte-navy); border: 1px solid var(--hmte-navy); transition: background var(--dur-base) var(--ease-out), transform var(--dur-base) var(--ease-out); }
