.contact-details { background: #e8e4dc; }
.contact-details-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); border-top: 1px solid rgba(1,31,75,.22); }
.contact-detail { min-height: 290px; padding: 32px 36px 36px 0; border-bottom: 1px solid rgba(1,31,75,.22); }
