.contact-detail-label { color: var(--hmte-teal); }
.contact-detail h3 { max-width: 10ch; margin: 40px 0 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: clamp(32px,3.5vw,48px); font-weight: 500; line-height: .98; letter-spacing: -.04em; }
.contact-detail p { max-width: 430px; margin: 22px 0 0; color: var(--fg-muted); line-height: 1.7; }
