  .announcement-board, .contact-channels, .contact-details { padding: 58px 0 68px; }
  .announcement-board-heading { align-items: start; flex-direction: column; gap: 16px; }
  .announcement-board-heading > p { margin: 0; }
  .announcement-feature, .announcement-row { grid-template-columns: 42px minmax(0,1fr); gap: 18px; }
  .announcement-feature-status, .announcement-row p { grid-column: 2; }
  .announcement-row p { margin: 0; }
