/* Announcement dispatch and contact studio: two related, deliberately distinct public surfaces. */
.contact-studio-shell { width: min(1180px, calc(100% - 64px)); margin-inline: auto; }
.contact-studio-topline { display: flex; justify-content: space-between; gap: 24px; padding-bottom: 17px; color: rgba(255,255,255,.52); border-bottom: 1px solid rgba(255,255,255,.18); font-family: var(--font-mono); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.contact-studio-eyebrow { display: flex; align-items: center; gap: 10px; margin: 0; color: var(--hmte-gold); font-family: var(--font-mono); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.contact-studio-eyebrow i { display: inline-block; width: 7px; height: 7px; background: currentColor; border-radius: 50%; box-shadow: 0 0 0 4px rgba(var(--hmte-gold-rgb),.15); }
.contact-studio-hero h1 { max-width: 11ch; margin: 25px 0 0; font-family: var(--font-display); font-size: clamp(66px, 8.35vw, 122px); font-weight: 500; line-height: .88; letter-spacing: -.075em; text-wrap: balance; }
.contact-studio-hero h1 em { color: var(--hmte-gold); font-style: normal; }
.contact-studio-jump { display: inline-flex; align-items: center; gap: 18px; margin-top: 48px; color: var(--tre-off-white); font-family: var(--font-mono); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.contact-studio-jump span { display: grid; width: 30px; height: 30px; place-items: center; color: var(--hmte-navy); background: var(--hmte-gold); border-radius: 50%; font-size: 17px; transition: transform var(--dur-base) var(--ease-out); }
.contact-studio-jump:hover span { transform: translateY(4px); }
.contact-routes h2, .contact-manifesto h2 { margin: 16px 0 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: clamp(43px, 5.4vw, 76px); font-weight: 500; line-height: .92; letter-spacing: -.06em; }
.contact-routes h2 em, .contact-manifesto h2 em { color: var(--hmte-gold-deep); font-style: normal; }

.contact-studio-hero { padding: 138px 0 76px; overflow: hidden; background: var(--tre-paper); }.contact-studio-grid { display: grid; grid-template-columns: minmax(0,1.02fr) minmax(390px,.88fr); gap: clamp(50px, 9vw, 130px); align-items: center; padding-top: 56px; }.contact-studio-copy { padding-bottom: 16px; }.contact-studio-hero h1 { max-width: 10ch; margin-top: 24px; color: var(--hmte-navy); }.contact-studio-copy > p:last-of-type { max-width: 48ch; margin: 30px 0 0; color: var(--fg-muted); font-size: 16px; line-height: 1.75; }.contact-studio-jump { color: var(--hmte-navy); }.contact-studio-photo { position: relative; min-height: 486px; margin: 0; overflow: hidden; background: var(--hmte-navy); }.contact-studio-photo > img { object-fit: cover; filter: saturate(.78) contrast(1.04); }.contact-studio-photo::after { position: absolute; inset: 0; content: ''; background: linear-gradient(135deg, rgba(1,31,75,.18), rgba(1,31,75,.55)); }.contact-studio-photo figcaption { position: absolute; z-index: 1; bottom: 22px; left: 24px; right: 24px; display: flex; justify-content: space-between; color: rgba(255,255,255,.78); font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .1em; }.contact-studio-stamp { position: absolute; z-index: 2; top: 24px; right: 24px; display: flex; flex-direction: column; align-items: end; padding: 17px 18px 12px; color: var(--hmte-navy); background: var(--hmte-gold); font-family: var(--font-mono); font-size: 11px; font-weight: 800; letter-spacing: .1em; line-height: 1; }.contact-studio-stamp strong { margin: 3px -3px 1px 0; font-family: var(--font-display); font-size: 54px; font-weight: 600; letter-spacing: -.1em; }.contact-studio-stamp small { font: inherit; }
.contact-routes { padding: 116px 0 126px; background: #081b3d; }.contact-routes-heading { display: grid; grid-template-columns: 1fr minmax(270px,.48fr); gap: 34px 90px; align-items: end; margin-bottom: 58px; }.contact-routes-heading .contact-studio-eyebrow { grid-column: 1 / -1; }.contact-routes h2 { margin: 0; color: var(--tre-off-white); }.contact-routes-heading > p:last-child { max-width: 37ch; margin: 0 0 5px; color: rgba(255,255,255,.62); line-height: 1.74; }.contact-route-list { border-top: 1px solid rgba(255,255,255,.22); }.contact-route { position: relative; display: grid; grid-template-columns: 72px minmax(0,1fr) 46px; gap: 26px; align-items: start; padding: 34px 18px 36px 0; color: var(--tre-off-white); border-bottom: 1px solid rgba(255,255,255,.18); transition: transform var(--dur-base) var(--ease-out), background var(--dur-base) var(--ease-out), color var(--dur-base) var(--ease-out); }.contact-route[href]:hover { color: var(--hmte-navy); background: var(--hmte-gold); transform: translateX(18px); }.contact-route-number, .contact-route-label { font-family: var(--font-mono); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }.contact-route-number { color: var(--hmte-gold); }.contact-route[href]:hover .contact-route-number { color: var(--hmte-navy); }.contact-route-label { color: rgba(255,255,255,.56); }.contact-route[href]:hover .contact-route-label { color: rgba(1,31,75,.7); }.contact-route h3 { margin: 11px 0 0; font-family: var(--font-display); font-size: clamp(31px, 3.7vw, 51px); font-weight: 500; line-height: .95; letter-spacing: -.055em; }.contact-route h3 em { color: var(--hmte-gold); font-style: normal; }.contact-route[href]:hover h3 em { color: var(--hmte-navy); }.contact-route p { max-width: 55ch; margin: 14px 0 0; color: rgba(255,255,255,.62); line-height: 1.65; }.contact-route[href]:hover p { color: rgba(1,31,75,.76); }.contact-route > b { align-self: center; justify-self: end; color: var(--hmte-gold); font-size: 34px; font-weight: 400; transition: transform var(--dur-base) var(--ease-out); }.contact-route[href]:hover > b { color: var(--hmte-navy); transform: translate(4px,-4px); }.contact-route--location { color: var(--hmte-navy); background: var(--tre-off-white); padding-left: 18px; }.contact-route--location .contact-route-number, .contact-route--location h3 em { color: var(--hmte-gold-deep); }.contact-route--location .contact-route-label, .contact-route--location p { color: var(--fg-muted); }.contact-route-pin { display: grid; width: 38px; aspect-ratio: 1; place-items: center; align-self: center; justify-self: end; border: 1px solid rgba(var(--hmte-navy-rgb),.35); border-radius: 50%; }.contact-route-pin i { width: 8px; height: 8px; background: var(--hmte-gold-deep); border-radius: 50%; box-shadow: 0 0 0 5px rgba(var(--hmte-gold-rgb),.2); }
.contact-manifesto { padding: 92px 0; background: var(--hmte-gold); }.contact-manifesto-grid { display: grid; grid-template-columns: 110px minmax(0,1fr) minmax(250px,.48fr); gap: 48px; align-items: end; }.contact-manifesto-mark { align-self: start; margin: -7px 0 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: 62px; font-weight: 600; line-height: .8; letter-spacing: -.12em; }.contact-manifesto .contact-studio-eyebrow { color: var(--hmte-navy); }.contact-manifesto .contact-studio-eyebrow i { color: var(--hmte-navy); box-shadow: 0 0 0 4px rgba(var(--hmte-navy-rgb),.12); }.contact-manifesto h2 { margin-top: 18px; }.contact-manifesto h2 em { color: var(--tre-off-white); }.contact-manifesto-copy { margin: 0 0 4px; color: rgba(1,31,75,.78); line-height: 1.75; }.contact-signoff { padding: 26px 0; color: var(--tre-off-white); background: var(--hmte-navy-deep); }.contact-signoff .contact-studio-shell { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 20px; }.contact-signoff p, .contact-signoff span { margin: 0; font-family: var(--font-mono); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }.contact-signoff span { color: var(--hmte-gold); }.contact-signoff i { height: 1px; background: rgba(255,255,255,.3); }
@media (max-width: 760px) {
  .contact-studio-shell { width: min(100% - 40px, 1180px); }.contact-studio-hero { padding-top: 120px; }.contact-studio-grid { grid-template-columns: 1fr; min-height: 0; gap: 28px; }.contact-studio-hero h1 { font-size: clamp(58px, 16vw, 80px); }.contact-routes { padding: 70px 0 78px; }.contact-routes-heading { display: flex; flex-direction: column; align-items: start; gap: 22px; margin-bottom: 38px; }.contact-studio-grid { padding-top: 42px; }.contact-studio-photo { min-height: 360px; }.contact-route { grid-template-columns: 40px minmax(0,1fr) 28px; gap: 14px; padding: 28px 10px 30px 0; }.contact-route--location { padding-left: 10px; }.contact-manifesto { padding: 65px 0; }.contact-manifesto-grid { grid-template-columns: 1fr; gap: 27px; }.contact-manifesto-mark { display: none; }.contact-signoff .contact-studio-shell { grid-template-columns: 1fr; gap: 12px; }.contact-signoff i { width: 100%; }
}
@media (prefers-reduced-motion: reduce) { .contact-studio-jump span, .contact-route, .contact-route > b { transition: none; } }

/* ============================================================
   PUBLIC ROUTE REFINEMENT — agenda, gallery, article, aspiration
   Route-scoped so the completed landing page remains untouched.
   ============================================================ */

.gallery-index-kicker,
.aspiration-kicker {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--hmte-gold);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.gallery-index-kicker::before,
.aspiration-kicker::before {
  width: 34px;
  height: 1px;
  content: '';
  background: currentColor;
}

.agenda-schedule { padding: 94px var(--public-gutter) 118px; background: var(--tre-off-white); }
.agenda-schedule-heading {
  display: grid;
  grid-template-columns: minmax(0,1fr) minmax(260px,.42fr);
  gap: 40px 90px;
  align-items: end;
  margin-bottom: 50px;
}
.agenda-schedule-heading h2 {
  margin: 13px 0 0;
  color: var(--hmte-navy);
  font-family: var(--font-display);
  font-size: clamp(42px,5.5vw,72px);
  line-height: .95;
  letter-spacing: -.04em;
}
.agenda-schedule-heading > p { max-width: 35ch; margin: 0; color: var(--fg-muted); line-height: 1.7; }
.agenda-timeline { border-top: 1px solid rgba(var(--hmte-navy-rgb),.2); }
.agenda-timeline-item {
  display: grid;
  grid-template-columns: 48px 130px minmax(0,1fr) minmax(190px,.42fr);
  gap: 26px;
  align-items: start;
  padding: 36px 18px 38px 0;
  border-bottom: 1px solid rgba(var(--hmte-navy-rgb),.17);
  transition: background var(--dur-base) var(--ease-out), transform var(--dur-base) var(--ease-out);
}
.agenda-timeline-item:hover { background: rgba(var(--hmte-navy-rgb),.035); transform: translateX(8px); }
.agenda-timeline-number,
.agenda-timeline-item > time,
.agenda-timeline-location span {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.agenda-timeline-number { color: var(--hmte-gold-deep); }
.agenda-timeline-item > time { color: var(--hmte-navy); }
.agenda-timeline-copy h3 {
  margin: -7px 0 0;
  color: var(--hmte-navy);
  font-family: var(--font-display);
  font-size: clamp(25px,2.4vw,34px);
  line-height: 1.04;
  letter-spacing: -.025em;
}
.agenda-timeline-copy p { max-width: 60ch; margin: 14px 0 0; color: var(--fg-muted); line-height: 1.7; }
.agenda-timeline-location { padding-left: 24px; border-left: 1px solid rgba(var(--hmte-navy-rgb),.16); }
.agenda-timeline-location span { display: block; color: var(--fg-faint); }
.agenda-timeline-location strong { display: block; margin-top: 11px; color: var(--hmte-navy); font-size: 12px; line-height: 1.55; }

/* Gallery: image-led archive instead of a generic card grid. */
.gallery-index-hero { padding: 160px var(--public-gutter) 82px; }
.gallery-index-hero-grid {
  display: grid;
  grid-template-columns: minmax(0,1.2fr) minmax(300px,.48fr);
  gap: 48px 110px;
  align-items: end;
}
/* Inverted onto the shared navy backdrop — was a light #e9e5dc panel. */
.gallery-index-kicker { color: var(--hmte-gold); }
.gallery-index-hero h1 {
  max-width: 11ch;
  margin: 23px 0 0;
  color: var(--tre-off-white);
  font-family: var(--font-display);
  font-size: clamp(57px,7vw,94px);
  font-weight: 600;
  line-height: .91;
  letter-spacing: -.04em;
  text-wrap: balance;
}
.gallery-index-intro { padding-bottom: 5px; }
.gallery-index-intro p { max-width: 40ch; margin: 0; color: rgba(255,255,255,.68); line-height: 1.75; }
.gallery-index-intro > span {
  display: block;
  margin-top: 28px;
  padding-top: 16px;
  color: #fff;
  border-top: 1px solid rgba(255,255,255,.22);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
}
.gallery-archive { padding: 94px var(--public-gutter) 120px; background: var(--tre-off-white); }
.gallery-archive-heading {
  display: grid;
  grid-template-columns: 150px minmax(0,1fr) minmax(230px,.38fr);
  gap: 28px;
  align-items: end;
  margin-bottom: 42px;
}
.gallery-archive-heading > span { color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.gallery-archive-heading h2 { margin: 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: clamp(42px,5vw,68px); line-height: .95; letter-spacing: -.04em; }
.gallery-archive-heading p { margin: 0 0 3px; color: var(--fg-muted); line-height: 1.65; }
.gallery-mosaic { display: grid; grid-template-columns: repeat(12,minmax(0,1fr)); gap: 14px; }
.gallery-mosaic-item { grid-column: span 5; min-width: 0; color: var(--tre-off-white); }
.gallery-mosaic-item.is-lead { grid-column: span 7; grid-row: span 2; }
.gallery-mosaic-item:nth-child(4),
.gallery-mosaic-item:nth-child(5) { grid-column: span 6; }
.gallery-mosaic-item figure { position: relative; min-height: 330px; margin: 0; overflow: hidden; background: var(--hmte-navy); }
.gallery-mosaic-item.is-lead figure { min-height: 674px; }
.gallery-mosaic-item img { object-fit: cover; transition: transform 650ms var(--ease-out), filter 650ms var(--ease-out); }
.gallery-mosaic-item figure::after { position: absolute; inset: 0; content: ''; background: linear-gradient(180deg, transparent 28%, rgba(0,10,29,.9)); transition: opacity var(--dur-base) var(--ease-out); }
.gallery-mosaic-item:hover img { transform: scale(1.035); filter: saturate(.82); }
.gallery-mosaic-index { position: absolute; z-index: 2; top: 22px; left: 22px; display: grid; width: 34px; aspect-ratio: 1; place-items: center; color: var(--hmte-navy); background: var(--hmte-gold); font-family: var(--font-mono); font-size: 11px; font-weight: 900; }
.gallery-mosaic-item figcaption { position: absolute; z-index: 2; inset: auto 24px 24px; }
.gallery-mosaic-item figcaption > span { color: var(--hmte-gold); font-family: var(--font-mono); font-size: 11px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.gallery-mosaic-item h3 { max-width: 24ch; margin: 12px 0 0; color: var(--tre-off-white); font-family: var(--font-display); font-size: clamp(21px,2.2vw,31px); line-height: 1.05; letter-spacing: -.035em; }
.gallery-mosaic-item.is-lead h3 { max-width: 18ch; font-size: clamp(32px,4vw,54px); }
.gallery-mosaic-item figcaption > div { display: flex; justify-content: space-between; gap: 20px; align-items: center; margin-top: 22px; padding-top: 14px; border-top: 1px solid rgba(255,255,255,.26); }
.gallery-mosaic-item time,
.gallery-mosaic-item strong { font-family: var(--font-mono); font-size: 11px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.gallery-mosaic-item time { color: rgba(255,255,255,.58); }
.gallery-mosaic-item strong { color: var(--tre-off-white); }
.gallery-mosaic-item strong b { display: inline-block; margin-left: 5px; color: var(--hmte-gold); transition: transform var(--dur-base) var(--ease-out); }
.gallery-mosaic-item:hover strong b { transform: translate(3px,-3px); }
/* Keterangan foto dari panel. Kalimat biasa, jadi tidak ikut aturan mono
   huruf besar yang dipakai label di sekitarnya. */
.gallery-mosaic-item figcaption p { max-width: 46ch; margin: 12px 0 0; padding-top: 12px; border-top: 1px solid rgba(255,255,255,.26); color: rgba(255,255,255,.72); font-size: 14px; line-height: 1.5; }

/* Article detail: readable editorial hierarchy and clear wayfinding. */
.article-story { background: var(--tre-off-white); }
.article-story-hero { padding: 146px var(--public-gutter) 60px; background: var(--tre-off-white); }
.article-story-back {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--hmte-navy);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .09em;
  text-transform: uppercase;
}
.article-story-back span { color: var(--hmte-gold-deep); font-size: 17px; transition: transform var(--dur-base) var(--ease-out); }
.article-story-back:hover span { transform: translateX(-4px); }
