.admin-quick-links { display: grid; }
.admin-quick-links > a { min-height: 86px; display: grid; grid-template-columns: 35px minmax(0,1fr) 20px; align-items: center; gap: 13px; padding: 15px 20px; border-bottom: 1px solid var(--admin-line); color: var(--admin-ink); transition: background var(--dur-fast); }
