.admin-quick-links > a:hover { background: rgba(var(--hmte-gold-rgb), .07); }
.admin-quick-links b { color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 9px; }
.admin-quick-links > a > span { display: grid; gap: 5px; }
.admin-quick-links strong { color: var(--hmte-navy); font-size: 12px; }
.admin-quick-links small { color: var(--admin-muted); font-size: 10px; line-height: 1.5; }
.admin-quick-links i { color: var(--hmte-navy); font-style: normal; transition: transform var(--dur-fast); }
.admin-quick-links a:hover i { transform: translateX(3px); }

.admin-access-panel dl { margin: 0; padding: 8px 20px; }
.admin-access-panel dl > div { display: grid; grid-template-columns: 84px minmax(0,1fr); gap: 12px; padding: 13px 0; border-bottom: 1px solid var(--admin-line); }
.admin-access-panel dt { color: var(--admin-muted); font-family: var(--font-mono); font-size: 8px; text-transform: uppercase; }
.admin-access-panel dd { min-width: 0; margin: 0; overflow: hidden; color: var(--hmte-navy); font-size: 10px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.admin-access-panel > p { margin: 0; padding: 16px 20px 20px; color: var(--admin-muted); font-size: 10px; line-height: 1.6; }

.admin-content-overview {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}

.admin-content-counts {
  flex: 1 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(80px, 1fr));
  border: 1px solid var(--admin-line);
  background: rgba(255,254,250,.8);
}

.admin-content-counts > span {
  display: flex;
  align-items: baseline;
  gap: 9px;
  padding: 12px 15px;
  border-right: 1px solid var(--admin-line);
  color: var(--admin-muted);
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-content-counts > span:last-child { border-right: 0; }
