}

.admin-search-field {
  min-width: 260px;
  max-width: 440px;
  flex: 1 1;
  position: relative;
}

.admin-search-field svg { position: absolute; top: 50%; left: 12px; width: 17px; height: 17px; fill: none; stroke: var(--admin-muted); stroke-width: 1.7; transform: translateY(-50%); }
.admin-search-field input { width: 100%; min-height: 40px; padding: 0 13px 0 39px; border: 1px solid var(--admin-line); border-radius: 5px; background: white; color: var(--admin-ink); font: inherit; font-size: 11px; }
.admin-search-field input:focus { outline: 2px solid rgba(var(--hmte-gold-rgb), .3); border-color: var(--hmte-gold-deep); }

.admin-filter-tabs { display: flex; gap: 4px; }
.admin-filter-tabs button { min-height: 36px; padding: 0 11px; border: 1px solid transparent; border-radius: 5px; background: transparent; color: var(--admin-muted); cursor: pointer; font-family: var(--font-mono); font-size: 8px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.admin-filter-tabs button:hover { color: var(--hmte-navy); background: rgba(var(--hmte-navy-rgb), .04); }
.admin-filter-tabs button[aria-pressed='true'] { color: var(--hmte-navy-deep); border-color: rgba(var(--hmte-gold-rgb), .5); background: rgba(var(--hmte-gold-rgb), .2); }

.admin-table-wrap { overflow-x: auto; border: 1px solid var(--admin-line); border-radius: 0; background: var(--admin-surface); box-shadow: 0 18px 46px rgba(var(--hmte-navy-rgb), .06); }
.admin-table { width: 100%; min-width: 850px; border-collapse: collapse; }
.admin-table th { padding: 12px 16px; border-bottom: 1px solid var(--admin-line-strong); color: var(--admin-muted); background: var(--admin-surface-soft); font-family: var(--font-mono); font-size: 8px; font-weight: 700; letter-spacing: .11em; text-align: left; text-transform: uppercase; }
.admin-table td { padding: 17px 16px; border-bottom: 1px solid var(--admin-line); color: var(--admin-muted); font-size: 10px; vertical-align: middle; }
.admin-table tbody tr:last-child td { border-bottom: 0; }
.admin-table tbody tr:hover { background: rgba(var(--hmte-gold-rgb), .045); }
.admin-content-cell { width: 48%; }
.admin-content-cell small { display: block; margin: 0 0 6px; color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 8px; }
.admin-content-cell strong { display: block; color: var(--hmte-navy); font-size: 12px; line-height: 1.4; }
.admin-content-cell p { max-width: 650px; margin: 5px 0 0; overflow: hidden; color: var(--admin-muted); font-size: 10px; line-height: 1.5; text-overflow: ellipsis; white-space: nowrap; }

.admin-status-badge { width: fit-content; display: inline-flex !important; align-items: center; gap: 6px; margin: 0 !important; padding: 5px 9px; border: 1px solid; border-radius: 999px; font-family: var(--font-mono); font-size: 7px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; }
.admin-status-badge::before { content: ''; width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.admin-status-badge.draft { color: var(--hmte-warning); border-color: rgba(183,121,31,.22); background: rgba(183,121,31,.08); }
.admin-status-badge.published { color: var(--hmte-success); border-color: rgba(47,125,89,.22); background: rgba(47,125,89,.08); }
.admin-status-badge.archived { color: var(--admin-muted); border-color: var(--admin-line); background: rgba(var(--hmte-navy-rgb),.04); }

.admin-table-actions { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
.admin-table-actions a,
.admin-table-actions button { min-height: 30px; display: inline-flex; align-items: center; padding: 0 8px; border: 1px solid var(--admin-line); border-radius: 4px; background: white; color: var(--hmte-navy); cursor: pointer; font-family: var(--font-mono); font-size: 7px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
.admin-table-actions a:hover,
.admin-table-actions button:hover { border-color: var(--hmte-gold-deep); background: rgba(var(--hmte-gold-rgb), .08); }
.admin-table-actions .is-danger { color: var(--admin-danger); }
.admin-table-actions button:disabled { cursor: wait; opacity: .55; }
.admin-readonly-label { font-family: var(--font-mono); font-size: 8px; text-transform: uppercase; }

.admin-editor-form { display: grid; gap: 14px; }
.admin-editor-layout { display: grid; grid-template-columns: minmax(0, 1fr) 290px; gap: 18px; align-items: start; }
.admin-editor-canvas { min-width: 0; display: grid; gap: 16px; }
.admin-form-section { display: grid; gap: 20px; padding: clamp(20px, 3vw, 30px); border: 1px solid var(--admin-line); background: rgba(255,254,250,.94); box-shadow: 0 14px 38px rgba(var(--hmte-navy-rgb), .045); }
.admin-form-section-heading { display: grid; grid-template-columns: 28px minmax(0,1fr); gap: 12px; padding-bottom: 16px; border-bottom: 1px solid var(--admin-line); }
.admin-form-section-heading > span { color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 9px; font-weight: 700; }
.admin-form-section-heading h2 { margin: 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: 22px; letter-spacing: -.025em; }
.admin-form-section-heading p { margin: 5px 0 0; color: var(--admin-muted); font-size: 10px; line-height: 1.55; }

.admin-dashboard .admin-field,
.admin-auth-page .admin-field { display: grid; gap: 8px; }
.admin-dashboard .admin-field label,
.admin-auth-page .admin-field label { color: var(--hmte-navy); font-family: var(--font-mono); font-size: 8px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.admin-dashboard .admin-field input,
.admin-dashboard .admin-field select,
.admin-dashboard .admin-field textarea,
.admin-auth-page .admin-field input { width: 100%; min-height: 44px; padding: 0 12px; border: 1px solid var(--admin-line-strong); border-radius: 5px; background: white; color: var(--admin-ink); font: inherit; font-size: 11px; }
.admin-dashboard .admin-field textarea { min-height: 100px; padding: 12px; line-height: 1.6; resize: vertical; }
.admin-dashboard .admin-field-hint { margin: 0; color: var(--admin-muted); font-size: 10px; line-height: 1.5; }
.admin-dashboard .admin-field input:focus,
.admin-dashboard .admin-field select:focus,
.admin-dashboard .admin-field textarea:focus,
.admin-auth-page .admin-field input:focus { outline: 2px solid rgba(var(--hmte-gold-rgb), .3); outline-offset: 1px; border-color: var(--hmte-gold-deep); }
.admin-dashboard .admin-field > small { justify-self: end; color: var(--admin-muted); font-family: var(--font-mono); font-size: 7px; }
.admin-title-field input { min-height: 54px !important; font-family: var(--font-display) !important; font-size: 18px !important; font-weight: 600 !important; letter-spacing: -.02em; }
.admin-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 15px; }

/*
 * Pemilih bulan dan pratinjau jadwal program.
 *
 * Menggantikan isian teks "3, 6, 9, 12" yang dulu meminta pengurus mengetik
 * indeks kolom peta agenda dari kepala sendiri. Dua belas kotak menghapus
 * seluruh kelas kesalahan itu: angka di luar 1-12 tidak punya jalan masuk.
 *
 * Sudutnya membulat mengikuti --sr-* dari css/ui-soft.css, bukan sudut siku
 * yang dipakai panel lama. Ini bagian baru, dan tidak ada gunanya menambah
 * permukaan tajam ke sistem yang sedang ditinggalkan.
 */
.admin-month-picker { display: grid; gap: 10px; margin: 0; padding: 16px; border: 1px solid var(--admin-line); border-radius: var(--sr-md, 18px); background: var(--admin-surface-soft); }
.admin-month-picker legend { padding: 0; color: var(--hmte-navy); font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.admin-month-grid { display: grid; grid-template-columns: repeat(6, minmax(0,1fr)); gap: 8px; }
.admin-month-box {
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--admin-line-strong);
  border-radius: var(--sr-sm, 12px);
  background: white;
  color: var(--admin-muted);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .04em;
  transition: background var(--dur-fast), color var(--dur-fast), border-color var(--dur-fast);
}
.admin-month-box:hover { color: var(--hmte-navy); border-color: var(--hmte-gold-deep); }
.admin-month-box[aria-pressed='true'] { color: var(--hmte-navy-deep); border-color: var(--hmte-gold-deep); background: var(--hmte-gold); }
.admin-month-box:focus-visible { outline: 2px solid rgba(var(--hmte-gold-rgb), .45); outline-offset: 2px; }

.admin-schedule-preview { display: grid; gap: 6px; padding: 16px 18px; border-radius: var(--sr-md, 18px); background: rgba(var(--hmte-navy-rgb), .05); }
.admin-schedule-preview-kicker { color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.admin-schedule-preview strong { color: var(--hmte-navy); font-family: var(--font-display); font-size: 19px; letter-spacing: -.02em; }
.admin-schedule-preview p { margin: 0; color: var(--admin-muted); font-size: 11px; line-height: 1.55; }

/* ---- Isi halaman rincian program ----
   Ringkasan, poin fokus, tahapan, berkas, dan penanggung jawab. Dikurung satu
   fieldset supaya bagian yang panjang ini terbaca sebagai satu blok dan tidak
   menenggelamkan isian jadwal di atasnya. */

.admin-detail-group { display: grid; gap: 16px; margin: 0; padding: 18px; border: 1px solid var(--admin-line); border-radius: var(--sr-md, 18px); background: var(--admin-surface-soft); }
.admin-detail-group legend { padding: 0; color: var(--hmte-navy); font-family: var(--font-mono); font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }

.admin-repeat { display: grid; gap: 12px; }
.admin-repeat-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.admin-repeat-head > span { color: var(--hmte-navy); font-family: var(--font-mono); font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.admin-repeat-head button { min-height: 34px; padding: 0 14px; border: 1px solid var(--admin-line-strong); border-radius: var(--sr-pill, 999px); background: white; color: var(--hmte-navy); cursor: pointer; font: 600 11px var(--font-body); }
.admin-repeat-head button:hover:not(:disabled) { border-color: var(--hmte-gold-deep); }
.admin-repeat-head button:disabled { color: var(--admin-muted); cursor: not-allowed; }
.admin-repeat-head button:focus-visible { outline: 2px solid rgba(var(--hmte-gold-rgb), .45); outline-offset: 2px; }

.admin-repeat-row { display: grid; gap: 12px; padding: 14px; border-radius: var(--sr-sm, 12px); background: white; box-shadow: inset 0 0 0 1px var(--admin-line); }

/* Tombol hapus menyebut nomor barisnya, jadi pembaca layar tidak menemukan
   selusin tombol bernama "Hapus" yang tidak bisa dibedakan satu sama lain. */
.admin-repeat-remove { justify-self: start; min-height: 32px; padding: 0 12px; border: 0; border-radius: var(--sr-pill, 999px); background: rgba(169, 54, 54, .09); color: var(--admin-danger); cursor: pointer; font: 600 11px var(--font-body); }
.admin-repeat-remove:hover { background: rgba(169, 54, 54, .16); }
.admin-repeat-remove:focus-visible { outline: 2px solid var(--admin-danger); outline-offset: 2px; }

.admin-chip-picker { display: flex; flex-wrap: wrap; gap: 8px; }
.admin-chip-picker button { display: grid; gap: 2px; padding: 9px 14px; border: 1px solid var(--admin-line-strong); border-radius: var(--sr-sm, 12px); background: white; color: var(--admin-muted); cursor: pointer; text-align: left; transition: background var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast); }
.admin-chip-picker button b { color: var(--admin-ink); font: 600 12px var(--font-body); }
.admin-chip-picker button small { font-size: 10px; }
.admin-chip-picker button:hover { border-color: var(--hmte-gold-deep); }
.admin-chip-picker button[aria-pressed='true'] { border-color: var(--hmte-gold-deep); background: var(--hmte-gold); color: var(--hmte-navy-deep); }
.admin-chip-picker button[aria-pressed='true'] b { color: var(--hmte-navy-deep); }
.admin-chip-picker button:focus-visible { outline: 2px solid rgba(var(--hmte-gold-rgb), .45); outline-offset: 2px; }

.admin-chip-orphans { display: grid; gap: 8px; padding: 12px; border-radius: var(--sr-sm, 12px); background: rgba(169, 54, 54, .06); }

@media (prefers-reduced-motion: reduce) {
  .admin-chip-picker button { transition: none; }
}

/* Formulir pembuatan akun pengurus. */
.admin-account-form { display: grid; gap: 16px; padding: 22px 24px; border-radius: var(--sr-lg, 22px); background: var(--admin-surface-soft); }
.admin-account-form h2 { margin: 0; color: var(--hmte-navy); font-family: var(--font-display); font-size: 20px; letter-spacing: -.02em; }
.admin-account-form-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 14px; }
.admin-account-form label { display: grid; gap: 6px; min-width: 0; }
.admin-account-form label > span { color: var(--admin-muted); font-size: 12px; font-weight: 600; }
.admin-account-form input, .admin-account-form select { width: 100%; padding: 10px 12px; border: 1px solid var(--admin-line); border-radius: var(--sr-sm, 12px); background: var(--admin-surface); color: var(--hmte-navy); font: inherit; font-size: 14px; }
.admin-account-form input:focus-visible, .admin-account-form select:focus-visible { outline: 2px solid rgba(var(--hmte-gold-rgb), .45); outline-offset: 1px; }
.admin-account-form select:disabled { color: var(--admin-muted); background: var(--admin-surface-soft); }
.admin-account-form .admin-primary-button { justify-self: start; }

/* Tautan setel sandi. Dibuat mudah disalin utuh, karena tautannya panjang dan
   terpotong sedikit saja sudah tidak bisa dipakai. */
.admin-invite-link { width: 100%; margin-top: 8px; padding: 10px 12px; border: 1px solid var(--admin-line); border-radius: var(--sr-sm, 12px); background: var(--admin-surface); color: var(--hmte-navy); font-family: var(--font-mono); font-size: 11px; line-height: 1.5; resize: vertical; word-break: break-all; }

/* Isian gambar dengan unggah langsung ke ImageKit. */
.admin-visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.admin-image-field-row { display: grid; grid-template-columns: 96px minmax(0,1fr); gap: 14px; align-items: start; }
.admin-image-field-preview { width: 96px; height: 96px; object-fit: cover; border: 1px solid var(--admin-line); border-radius: var(--sr-sm, 12px); background: var(--admin-surface-soft); }
.admin-image-field-preview.is-empty { display: grid; place-items: center; color: var(--admin-muted); font-family: var(--font-mono); font-size: 11px; }
.admin-image-field-controls { display: grid; gap: 9px; }
.admin-image-field-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.admin-image-field .admin-form-error { margin: 0; }

.admin-dashboard .admin-form-warning { display: grid; gap: 7px; margin: 0 0 14px; padding: 12px 14px 12px 30px; border-radius: var(--sr-sm, 12px); background: rgba(var(--hmte-gold-rgb), .16); color: var(--hmte-navy); font-size: 11px; line-height: 1.55; }

.admin-input-prefix { display: grid; grid-template-columns: auto minmax(0,1fr); align-items: center; border: 1px solid var(--admin-line-strong); border-radius: 5px; background: var(--admin-surface-soft); overflow: hidden; }
.admin-input-prefix > span { padding: 0 0 0 11px; color: var(--admin-muted); font-family: var(--font-mono); font-size: 9px; }
.admin-input-prefix input { border: 0 !important; background: transparent !important; }
.admin-input-prefix:focus-within { outline: 2px solid rgba(var(--hmte-gold-rgb), .3); border-color: var(--hmte-gold-deep); }
.admin-input-prefix:focus-within input { outline: 0 !important; }

.admin-cover-preview { position: relative; min-height: 280px; overflow: hidden; border: 1px solid var(--admin-line); background: var(--admin-surface-soft); }
.admin-cover-preview img { object-fit: cover; }

.admin-publish-panel { position: sticky; top: 22px; display: grid; gap: 14px; }
.admin-publish-card,
.admin-editor-tips { border: 1px solid var(--admin-line); background: rgba(255,254,250,.96); box-shadow: 0 14px 38px rgba(var(--hmte-navy-rgb), .05); }
.admin-publish-card { display: grid; gap: 16px; padding: 20px; }
.admin-publish-label,
.admin-editor-tips > span { color: var(--hmte-gold-deep); font-family: var(--font-mono); font-size: 8px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.admin-publish-card > p { margin: 0; color: var(--admin-muted); font-size: 10px; line-height: 1.6; }
.admin-public-url { display: grid; gap: 7px; padding: 12px; border: 1px solid var(--admin-line); background: var(--admin-surface-soft); }
.admin-public-url span { color: var(--admin-muted); font-family: var(--font-mono); font-size: 7px; text-transform: uppercase; }
.admin-public-url code { overflow: hidden; color: var(--hmte-navy); font-family: var(--font-mono); font-size: 8px; text-overflow: ellipsis; white-space: nowrap; }
.admin-preview-link { min-height: 38px; display: flex; align-items: center; justify-content: center; border: 1px solid var(--admin-line-strong); color: var(--hmte-navy); font-size: 9px; font-weight: 700; }
.admin-editor-tips { padding: 18px 20px; }
.admin-editor-tips ul { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
.admin-editor-tips li { position: relative; padding-left: 16px; color: var(--admin-muted); font-size: 9px; line-height: 1.5; }
.admin-editor-tips li::before { content: ''; position: absolute; top: .5em; left: 0; width: 6px; height: 6px; border: 1px solid var(--hmte-gold-deep); border-radius: 50%; }

.admin-rich-editor { overflow: hidden; border: 1px solid var(--admin-line-strong); background: white; }
.admin-rich-editor:focus-within { border-color: var(--hmte-gold-deep); box-shadow: 0 0 0 2px rgba(var(--hmte-gold-rgb),.18); }
.admin-rich-editor.is-loading { min-height: 300px; display: grid; place-items: center; color: var(--admin-muted); font-family: var(--font-mono); font-size: 9px; }
/*
 * Menempel di atas saat digulir. Artikel yang sungguhan panjangnya ribuan kata,
 * dan toolbar yang ikut hilang ke atas memaksa penulis menggulung balik ke awal
 * halaman setiap kali ingin memberi satu heading.
 */
.admin-editor-toolbar { position: sticky; top: 0; z-index: 5; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; padding: 9px; border-bottom: 1px solid var(--admin-line); background: rgba(255,254,250,.94); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px); }
.admin-editor-toolbar > div { display: flex; gap: 3px; padding-right: 5px; border-right: 1px solid var(--admin-line); }
.admin-editor-toolbar > div:last-child { border-right: 0; }
.admin-editor-toolbar button { min-width: 36px; min-height: 34px; padding: 0 11px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--admin-muted); cursor: pointer; font-family: var(--font-mono); font-size: 10px; font-weight: 700; letter-spacing: .02em; transition: background .16s ease, color .16s ease, border-color .16s ease; }
.admin-editor-toolbar button:hover { color: var(--hmte-navy); border-color: var(--admin-line); background: white; }
.admin-editor-toolbar button.is-active,
.admin-editor-toolbar button[aria-pressed='true'] { color: var(--hmte-navy-deep); border-color: rgba(var(--hmte-gold-rgb),.42); background: rgba(var(--hmte-gold-rgb),.2); }
.admin-editor-toolbar button:disabled { cursor: not-allowed; opacity: .35; }
.admin-editor-history { margin-left: auto; }
.admin-rich-editor .tiptap { min-height: 440px; padding: clamp(22px, 4vw, 42px); color: var(--admin-ink); font-size: 14px; line-height: 1.8; }
.admin-rich-editor .tiptap:focus { outline: 0; }
.admin-rich-editor .tiptap p { margin: 0 0 1.15em; }
.admin-rich-editor .tiptap h2,
.admin-rich-editor .tiptap h3 { margin: 1.5em 0 .6em; color: var(--hmte-navy); font-family: var(--font-display); line-height: 1.18; }
.admin-rich-editor .tiptap h2 { font-size: 27px; }
.admin-rich-editor .tiptap h3 { font-size: 21px; }
.admin-rich-editor .tiptap ul,
.admin-rich-editor .tiptap ol { margin: 0 0 1.25em; padding-left: 1.5em; }
.admin-rich-editor .tiptap blockquote { margin: 1.5em 0; padding: 14px 18px; border-top: 2px solid var(--hmte-gold); background: rgba(var(--hmte-gold-rgb),.08); color: var(--hmte-navy); }
.admin-rich-editor .tiptap a { color: var(--hmte-teal); text-decoration: underline; text-underline-offset: 3px; }
.admin-rich-editor .tiptap img { max-width: 100%; height: auto; display: block; margin: 24px auto; }
/* Cermin aturan ukuran di halaman publik, supaya "sedang" di sini berarti sedang di sana juga. */
.admin-rich-editor .tiptap img[data-size='medium'] { width: min(100%, 62%); }
.admin-rich-editor .tiptap img[data-size='small'] { width: min(100%, 38%); }
.admin-rich-editor .tiptap img[data-size='medium'][data-align='left'],
.admin-rich-editor .tiptap img[data-size='small'][data-align='left'] { float: left; margin: 4px 24px 18px 0; }
.admin-rich-editor .tiptap img[data-size='medium'][data-align='right'],
.admin-rich-editor .tiptap img[data-size='small'][data-align='right'] { float: right; margin: 4px 0 18px 24px; }
.admin-rich-editor .tiptap h2,
.admin-rich-editor .tiptap h3,
.admin-rich-editor .tiptap hr { clear: both; }
.admin-rich-editor .tiptap p.is-editor-empty:first-child::before { content: attr(data-placeholder); float: left; height: 0; color: #9aa4ad; pointer-events: none; }
.admin-editor-footer { display: flex; gap: 18px; padding: 9px 13px; border-top: 1px solid var(--admin-line); color: var(--admin-muted); background: var(--admin-surface-soft); font-family: var(--font-mono); font-size: 8px; letter-spacing: .04em; text-transform: uppercase; }
.admin-editor-inline-error { margin: 0; padding: 9px 12px; border-top: 1px solid rgba(169,54,54,.2); color: var(--admin-danger); background: rgba(169,54,54,.05); font-size: 9px; }

/*
 * Peringatan terbit. Nadanya sengaja berbeda dari .admin-editor-inline-error:
 * ini bukan kesalahan yang menghalangi menyimpan, melainkan pemberitahuan
 * bahwa ada bagian isi yang tidak akan ikut tampil di halaman publik.
 */
.admin-editor-publish-warning { padding: 10px 13px; border-top: 1px solid rgba(var(--hmte-gold-rgb),.4); background: rgba(var(--hmte-gold-rgb),.11); }
.admin-editor-publish-warning p { margin: 0; color: var(--hmte-navy); font-size: 9.5px; line-height: 1.6; }
.admin-editor-publish-warning p + p { margin-top: 6px; }

/* Kontrol yang hanya berlaku untuk satu objek terpilih (gambar, sisipan). */
.admin-editor-contextbar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 7px 10px; border-bottom: 1px solid var(--admin-line); background: rgba(var(--hmte-navy-rgb),.045); }
.admin-editor-contextbar > span { color: var(--admin-muted); font-family: var(--font-mono); font-size: 8px; letter-spacing: .05em; text-transform: uppercase; }
.admin-editor-contextbar > div { display: flex; gap: 3px; padding-right: 8px; border-right: 1px solid var(--admin-line); }
.admin-editor-contextbar button { min-height: 28px; padding: 0 10px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--admin-muted); cursor: pointer; font-family: var(--font-mono); font-size: 9px; font-weight: 700; }
.admin-editor-contextbar button:hover:not(:disabled) { color: var(--hmte-navy); background: white; }
.admin-editor-contextbar button[aria-pressed='true'] { color: var(--hmte-navy-deep); border-color: rgba(var(--hmte-gold-rgb),.42); background: rgba(var(--hmte-gold-rgb),.24); }
.admin-editor-contextbar button:disabled { cursor: not-allowed; opacity: .3; }

.admin-embed-verdict { margin: 0; font-size: 10px; font-weight: 600; }
.admin-embed-verdict.is-ok { color: var(--hmte-teal); }
.admin-embed-verdict.is-unknown { color: var(--admin-danger); }
.admin-embed-support { display: grid; gap: 4px; margin: 0; padding: 0; list-style: none; }
.admin-embed-support li { position: relative; padding-left: 14px; color: var(--admin-muted); font-size: 9px; line-height: 1.55; }
.admin-embed-support li::before { content: ''; position: absolute; top: .55em; left: 0; width: 5px; height: 5px; border: 1px solid var(--hmte-gold-deep); border-radius: 50%; }

/*
 * Sisipan di dalam editor. Iframe-nya dibiarkan hidup supaya penulis melihat
 * video yang benar, tapi pointer-events dimatikan: tanpa itu, klik selalu jatuh
 * ke dalam iframe dan node-nya tidak pernah bisa dipilih apalagi dihapus.
 */
.admin-rich-editor .tiptap .article-embed { position: relative; margin: 1.8em 0; }
.admin-rich-editor .tiptap .article-embed iframe { pointer-events: none; }
.admin-rich-editor .tiptap .article-embed::after { content: attr(data-provider); position: absolute; top: 8px; left: 8px; padding: 3px 8px; border-radius: 5px; background: rgba(var(--hmte-navy-rgb),.8); color: white; font-family: var(--font-mono); font-size: 8px; letter-spacing: .04em; text-transform: uppercase; }
.admin-rich-editor .tiptap .article-embed.ProseMirror-selectednode { outline: 2px solid var(--hmte-gold-deep); outline-offset: 3px; }
.admin-rich-editor .tiptap img.ProseMirror-selectednode { outline: 2px solid var(--hmte-gold-deep); outline-offset: 3px; }

/*
 * Pratinjau. Isi dirender memakai kelas .article-rich-content yang sama dengan
 * halaman publik, jadi yang dilihat penulis tata letak sebenarnya. Pilihan
 * lebar ponsel ada karena mayoritas pembaca berita HMTE datang dari ponsel,
 * dan gambar "kecil" yang rapi di layar lebar sering jadi terlalu sempit di sana.
 */
.admin-editor-preview { border-top: 1px solid var(--admin-line); background: var(--tre-off-white); }
.admin-editor-preview-bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 8px 12px; border-bottom: 1px solid var(--admin-line); background: var(--admin-surface-soft); }
.admin-editor-preview-bar > span { color: var(--admin-muted); font-family: var(--font-mono); font-size: 8px; letter-spacing: .05em; text-transform: uppercase; }
.admin-editor-preview-bar > div { display: flex; gap: 3px; }
.admin-editor-preview-bar button { min-height: 28px; padding: 0 11px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--admin-muted); cursor: pointer; font-family: var(--font-mono); font-size: 9px; font-weight: 700; }
.admin-editor-preview-bar button[aria-pressed='true'] { color: var(--hmte-navy-deep); border-color: rgba(var(--hmte-gold-rgb),.42); background: rgba(var(--hmte-gold-rgb),.24); }
.admin-editor-preview-stage { padding: clamp(22px, 4vw, 46px); }
.admin-editor-preview-stage .article-rich-content { width: min(100%, 720px); margin: 0 auto; }
.admin-editor-preview[data-device='phone'] .admin-editor-preview-stage { padding: 26px; }
.admin-editor-preview[data-device='phone'] .article-rich-content { width: min(100%, 390px); padding: 24px 20px; border: 1px solid var(--admin-line-strong); border-radius: 22px; background: white; font-size: 15px; }
.admin-editor-preview:empty { display: none; }

/* Panel tautan dan gambar. Menggantikan window.prompt yang berantai tiga. */
.admin-editor-panel { display: grid; gap: 11px; padding: 15px; border-bottom: 1px solid var(--admin-line); background: var(--admin-surface-soft); }
.admin-editor-panel label { display: grid; gap: 5px; }
.admin-editor-panel label > span { color: var(--admin-muted); font-family: var(--font-mono); font-size: 8px; letter-spacing: .04em; text-transform: uppercase; }
.admin-editor-panel input { width: 100%; padding: 10px 12px; border: 1px solid var(--admin-line-strong); border-radius: 8px; background: white; color: var(--admin-ink); font-size: 13px; }
.admin-editor-panel input:focus { outline: 0; border-color: var(--hmte-gold-deep); box-shadow: 0 0 0 2px rgba(var(--hmte-gold-rgb),.18); }
.admin-editor-panel-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.admin-editor-panel .admin-field-hint { margin: 0; }

/* Menu apung di atas teks yang disorot. */
.admin-editor-bubble { display: flex; gap: 3px; padding: 5px; border-radius: 10px; background: var(--hmte-navy-deep); box-shadow: 0 14px 38px rgba(var(--hmte-navy-rgb),.34); }
.admin-editor-bubble button { min-width: 34px; min-height: 30px; padding: 0 10px; border: 1px solid transparent; border-radius: 6px; background: transparent; color: rgba(255,255,255,.74); cursor: pointer; font-family: var(--font-mono); font-size: 10px; font-weight: 700; }
.admin-editor-bubble button:hover { color: #fff; background: rgba(255,255,255,.12); }
.admin-editor-bubble button[aria-pressed='true'] { color: var(--hmte-navy-deep); background: var(--hmte-gold); }

/*
 * Mode fokus. Editor mengambil alih layar, dan kolom teksnya dibatasi lebarnya
 * supaya barisnya tetap terbaca. Bukan sekadar kenyamanan: formulir berita
 * punya belasan isian lain, dan menulis naskah panjang di celah setinggi 440px
 * di antaranya adalah alasan orang menulis di aplikasi lain lalu menempel ke sini.
 */
.admin-rich-editor[data-focus-mode='on'] { position: fixed; z-index: 60; inset: 0; display: flex; flex-direction: column; border-radius: 0; overflow-y: auto; }
.admin-rich-editor[data-focus-mode='on'] .tiptap { flex: 1 1; width: min(100%, 74ch); margin: 0 auto; }

.admin-rich-editor .tiptap hr { margin: 2em 0; border: 0; border-top: 1px solid var(--admin-line-strong); }
.admin-rich-editor .tiptap pre { margin: 1.5em 0; padding: 15px 17px; border-radius: 10px; background: var(--hmte-navy-deep); color: #e8eefb; font-family: var(--font-mono); font-size: 12px; line-height: 1.62; overflow-x: auto; }
.admin-rich-editor .tiptap pre code { background: none; color: inherit; }

.admin-editor-actions { position: sticky; bottom: 12px; z-index: 10; display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 12px 14px; border: 1px solid var(--admin-line-strong); background: rgba(255,254,250,.94); box-shadow: 0 14px 45px rgba(var(--hmte-navy-rgb), .13); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); }
.admin-editor-actions > div { display: flex; align-items: center; gap: 9px; }
.admin-editor-actions > div:first-child { display: grid; gap: 3px; }
.admin-editor-actions span { color: var(--admin-muted); font-family: var(--font-mono); font-size: 7px; text-transform: uppercase; }
.admin-editor-actions a { color: var(--hmte-navy); font-size: 9px; font-weight: 700; }

.admin-dashboard .admin-form-error,
.admin-dashboard .admin-form-success { margin: 0 0 14px; padding: 11px 13px; border-radius: 0; font-size: 10px; }
.admin-editor-form > .admin-form-error,
.admin-editor-form > .admin-form-success { margin: 0; }

.admin-dashboard .admin-empty-state { margin-top: 0; padding: clamp(28px, 5vw, 58px); border: 1px solid var(--admin-line); border-radius: 0; background: rgba(255,254,250,.82); box-shadow: none; }
.admin-dashboard .admin-empty-state h3 { max-width: 720px; color: var(--hmte-navy); font-size: clamp(27px, 4vw, 46px); letter-spacing: -.04em; }
.admin-dashboard .admin-empty-state p { color: var(--admin-muted); font-size: 11px; }

.admin-dashboard .admin-toolbar,
.admin-dashboard .admin-content-form,
.admin-dashboard .admin-aspiration-item,
.admin-dashboard .admin-gallery-item { border-radius: 0; border-color: var(--admin-line); background: rgba(255,254,250,.92); box-shadow: 0 14px 38px rgba(var(--hmte-navy-rgb),.045); }
.admin-dashboard .admin-content-form { padding: clamp(20px, 3vw, 30px); }
.admin-dashboard .admin-tabbar button { border-radius: 4px; font-size: 8px; }
.admin-dashboard .admin-tabbar button[aria-selected='true'] { color: var(--hmte-navy-deep); border-color: var(--hmte-gold); background: var(--hmte-gold); }

.admin-auth-page {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
  padding: clamp(18px, 4vw, 48px);
  background:
    radial-gradient(circle at 80% 10%, rgba(var(--hmte-gold-rgb),.17), transparent 25%),
    linear-gradient(145deg, var(--hmte-navy-deep), var(--hmte-navy) 66%, #062f61);
}
.admin-auth-page::before { content: ''; position: absolute; inset: 0; opacity: .14; background-image: linear-gradient(rgba(255,255,255,.12) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.12) 1px, transparent 1px); background-size: 40px 40px; -webkit-mask-image: linear-gradient(135deg, black, transparent 74%); mask-image: linear-gradient(135deg, black, transparent 74%); }
.admin-login-shell,
.admin-status-panel { position: relative; z-index: 1; }
.admin-login-shell { width: min(1120px, 100%); min-height: min(650px, calc(100dvh - 70px)); grid-template-columns: minmax(0, 1.12fr) minmax(350px, .68fr); gap: 0; border: 1px solid rgba(255,255,255,.16); box-shadow: 0 40px 100px rgba(0,0,0,.28); }
.admin-login-intro { min-height: 100%; padding: clamp(34px, 6vw, 72px); border: 0; border-radius: 0; background: transparent; box-shadow: none; }
.admin-login-intro h1 { max-width: 680px; font-size: clamp(42px, 6vw, 78px); letter-spacing: -.055em; }
.admin-login-intro p { max-width: 600px; color: rgba(255,255,255,.62); font-size: 12px; }
.admin-login-panel { border: 0; border-radius: 0; background: var(--tre-off-white); box-shadow: none; }
.admin-login-form { gap: 16px; }
.admin-login-form .admin-primary-button { width: 100%; margin-top: 6px; }
.admin-login-form .admin-secondary-link { width: 100%; }
.admin-status-panel { border-radius: 0; background: var(--tre-off-white); }

.article-rich-content { color: var(--fg); font-size: clamp(16px, 1.8vw, 19px); line-height: 1.85; }
.article-rich-content > *:first-child { margin-top: 0; }
.article-rich-content p { margin: 0 0 1.35em; }
.article-rich-content h2,
.article-rich-content h3 { margin: 1.7em 0 .65em; color: var(--hmte-navy); font-family: var(--font-display); letter-spacing: -.03em; line-height: 1.12; }
.article-rich-content h2 { font-size: clamp(28px, 3.8vw, 44px); }
.article-rich-content h3 { font-size: clamp(22px, 3vw, 31px); }
.article-rich-content ul,
.article-rich-content ol { margin: 0 0 1.4em; padding-left: 1.35em; }
.article-rich-content li { margin-bottom: .45em; }
.article-rich-content blockquote { margin: 1.8em 0; padding: 22px clamp(20px, 4vw, 34px); border-block: 2px solid var(--hmte-gold); background: rgba(var(--hmte-gold-rgb), .09); color: var(--hmte-navy); font-family: var(--font-display); font-size: 1.12em; }
.article-rich-content a { color: var(--hmte-teal); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 4px; }
/*
 * Ukuran gambar di dalam berita.
 *
 * Tiga peran, bukan lebar bebas. Nilai data-size di luar daftar ini sudah
 * dinormalkan jadi "full" oleh sanitizeArticleContent, jadi aturan di bawah
 * selalu punya pasangan.
 */
.article-rich-content img { width: 100%; height: auto; display: block; margin: 2em 0; }
.article-rich-content img[data-size='medium'] { width: min(100%, 62%); }
.article-rich-content img[data-size='small'] { width: min(100%, 38%); }
.article-rich-content img[data-align='center'] { margin-inline: auto; }
.article-rich-content img[data-size='medium'][data-align='left'],
.article-rich-content img[data-size='small'][data-align='left'] { float: left; margin: .4em 1.8em 1.4em 0; }
.article-rich-content img[data-size='medium'][data-align='right'],
.article-rich-content img[data-size='small'][data-align='right'] { float: right; margin: .4em 0 1.4em 1.8em; }
/* Heading tidak boleh naik ke samping gambar mengambang; itu terbaca sebagai tata letak rusak. */
.article-rich-content h2,
.article-rich-content h3,
.article-rich-content hr,
.article-rich-content .article-embed { clear: both; }

/*
 * Sisipan pihak ketiga. Tinggi diatur lewat aspect-ratio, bukan tinggi tetap,
 * supaya video tetap proporsional di layar ponsel -- iframe dengan height tetap
 * adalah penyebab paling umum kotak hitam bergaris di bawah video.
 */
.article-rich-content .article-embed { margin: 2.4em 0; }
.article-rich-content .article-embed iframe { width: 100%; display: block; border: 0; border-radius: 4px; background: rgba(var(--hmte-navy-rgb), .06); }
.article-rich-content .article-embed[data-aspect='video'] iframe { aspect-ratio: 16 / 9; }
.article-rich-content .article-embed[data-aspect='document'] iframe,
.article-rich-content .article-embed[data-aspect='map'] iframe { aspect-ratio: 4 / 3; }
.article-rich-content .article-embed[data-aspect='audio'] iframe { aspect-ratio: auto; height: 152px; }
.article-rich-content .article-embed figcaption,
.article-rich-content .article-figure figcaption { margin-top: .7em; color: rgba(var(--hmte-navy-rgb), .66); font-size: .78em; line-height: 1.5; }
.article-rich-content .article-figure { margin: 2.2em 0; }
.article-rich-content .article-figure img { margin-block: 0; }

@media (max-width: 640px) {
  /* Gambar mengambang di kolom selebar ponsel menyisakan lajur teks 4-5 kata. */
  .article-rich-content img[data-size='medium'],
  .article-rich-content img[data-size='small'] { float: none; width: 100%; margin: 2em 0; }
  .article-rich-content .article-embed[data-aspect='document'] iframe,
  .article-rich-content .article-embed[data-aspect='map'] iframe { aspect-ratio: 3 / 4; }
}
.article-rich-content hr { margin: 2.5em 0; border: 0; border-top: 1px solid rgba(var(--hmte-navy-rgb), .18); }
.article-rich-content pre { overflow-x: auto; padding: 18px; background: var(--hmte-navy-deep); color: var(--tre-off-white); font-family: var(--font-mono); font-size: .8em; }

