.admin-media-mode button { display: flex; align-items: center; gap: 9px; padding: 12px 16px; border: 0; border-radius: 0; background: transparent; color: var(--admin-muted); cursor: pointer; font-family: var(--font-mono); font-size: 8px; letter-spacing: .08em; text-transform: uppercase; }
