.admin-media-layout { min-height: 620px; display: grid; grid-template-columns: minmax(0,1fr) minmax(300px,.42fr); gap: 0; border: 1px solid var(--admin-line); background: rgba(255,254,250,.9); }
.admin-media-grid { align-content: start; display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 1px; padding: 1px; background: var(--admin-line); }
