.admin-settings-section > header h2 { margin: 6px 0 4px; color: var(--hmte-navy); font-size: clamp(25px,3vw,38px); letter-spacing: -.045em; }
.admin-settings-section > header p { max-width: 650px; margin: 0; color: var(--admin-muted); font-size: 10px; line-height: 1.6; }
.admin-settings-grid { display: grid; gap: 14px; }
