.admin-settings-preview small,
.admin-serp-preview small { color: var(--admin-muted); font-family: var(--font-mono); font-size: 7px; letter-spacing: .12em; text-transform: uppercase; }
.admin-settings-preview strong { color: var(--hmte-navy); font-size: 15px; }
.admin-settings-preview p,
.admin-serp-preview p { margin: 0; color: var(--admin-muted); font-size: 9px; line-height: 1.55; }
.admin-serp-preview strong { color: #1a0dab; font: 18px/1.3 Arial,sans-serif; }
