.admin-row-actions { display: flex; align-items: center; gap: 3px; }
.admin-row-actions button,
.admin-text-danger,
.admin-inline-add { min-height: 30px; border: 1px solid var(--admin-line); background: white; color: var(--admin-muted); cursor: pointer; font: 700 7px var(--font-mono); text-transform: uppercase; }
