.admin-footer-link-row { display: grid; grid-template-columns: 26px minmax(120px,.8fr) 110px minmax(150px,1fr) auto auto auto; align-items: center; gap: 7px; padding: 8px 10px; border-bottom: 1px solid var(--admin-line); background: white; }
.admin-text-danger { padding: 0 9px; }

.admin-settings-actions { position: sticky; bottom: 0; z-index: 3; display: grid; grid-template-columns: minmax(180px,1fr) auto auto; align-items: center; gap: 9px; padding: 14px clamp(22px,3vw,38px); border-top: 1px solid var(--admin-line-strong); background: rgba(248,247,242,.96); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px); }
.admin-settings-actions > div { display: grid; gap: 2px; }
.admin-settings-actions strong { color: var(--hmte-navy); font-size: 10px; }
.admin-settings-actions span { color: var(--admin-muted); font-size: 8px; }
.admin-settings-actions .admin-primary-button,
.admin-settings-actions .admin-secondary-button,
.admin-settings-section > .admin-secondary-button { min-height: 40px; padding: 0 14px; border-radius: 4px; cursor: pointer; font: 700 8px var(--font-mono); letter-spacing: .06em; text-transform: uppercase; }
.admin-settings-actions .admin-primary-button { border: 1px solid var(--hmte-gold); background: var(--hmte-gold); color: var(--hmte-navy-deep); }
.admin-settings-actions .admin-secondary-button,
.admin-settings-section > .admin-secondary-button { border: 1px solid var(--admin-line-strong); background: white; color: var(--hmte-navy); }
.admin-settings-actions button:disabled { opacity: .4; cursor: not-allowed; }

@media (max-width: 1100px) {
  .admin-settings-layout { grid-template-columns: 150px minmax(0,1fr); }
  .admin-footer-link-row { grid-template-columns: 24px minmax(120px,1fr) 100px minmax(140px,1fr); }
  .admin-footer-link-row .admin-visibility-toggle,
  .admin-footer-link-row .admin-text-danger { justify-self: start; }
}

@media (max-width: 760px) {
  .admin-settings-status { align-items: flex-start; }
  .admin-settings-status dl { display: grid; gap: 8px; }
  .admin-settings-layout { grid-template-columns: 1fr; }
  .admin-settings-tabs { position: sticky; top: 0; z-index: 4; display: flex; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--admin-line); }
  .admin-settings-tabs button { min-width: 132px; border-right: 1px solid var(--admin-line); border-bottom: 0; }
  .admin-settings-tabs button.is-active { box-shadow: inset 0 -4px var(--hmte-gold); }
  .admin-settings-grid.two-column { grid-template-columns: 1fr; }
  .admin-structure-row,
  .admin-structure-row.footer-column-row { grid-template-columns: 26px minmax(0,1fr); }
  .admin-structure-row > :not(.admin-structure-index):not(.admin-structure-branch) { grid-column: 2; }
  .admin-footer-link-row { grid-template-columns: 24px minmax(0,1fr); }
  .admin-footer-link-row > :not(.admin-structure-branch) { grid-column: 2; }
  .admin-settings-actions { position: static; grid-template-columns: 1fr 1fr; }
  .admin-settings-actions > div { grid-column: 1 / -1; }
}

@media (max-width: 480px) {
  .admin-settings-status { display: grid; }
  .admin-settings-status dl { grid-template-columns: 1fr 1fr; }
  .admin-settings-section { padding: 19px 14px; }
  .admin-settings-actions { grid-template-columns: 1fr; padding: 12px 14px; }
  .admin-settings-actions > div { grid-column: auto; }
}

