  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--hmte-navy);
}

.landing-news-categories {
  display: flex;
  gap: 8px;
  margin-top: clamp(54px, 8vw, 100px);
  padding-bottom: 8px;
  overflow-x: auto;
  scrollbar-width: none;
}

.landing-news-categories::-webkit-scrollbar {
  display: none;
}

.landing-news-categories button {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 0 15px;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.14);
  border-radius: 999px;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 700;
  color: var(--hmte-navy);
  background: transparent;
  cursor: pointer;
  transition: color 180ms ease, border-color 180ms ease, background-color 180ms ease;
}

.landing-news-categories button > span {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--hmte-gold-deep);
}

.landing-news-categories button:hover,
.landing-news-categories button.is-active {
  border-color: var(--hmte-navy);
  color: #fff;
  background: var(--hmte-navy);
}

.landing-news-categories button.is-active > span {
  color: var(--hmte-gold);
}

.landing-news-stage {
  margin-top: 28px;
}

.landing-news-stage-top {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-bottom: 22px;
}

.landing-news-stage-meta {
  display: grid;
  grid-template-columns: 30px minmax(120px, 260px) 30px;
  gap: 12px;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.landing-news-stage-meta > div {
  height: 2px;
  overflow: hidden;
  background: rgba(var(--hmte-navy-rgb), 0.13);
}

.landing-news-stage-meta i {
  display: block;
  height: 100%;
  background: var(--hmte-gold-deep);
  transform-origin: left center;
  transition: transform 260ms var(--ease-out);
}

.landing-news-drag-note {
  margin: 0 0 0 auto;
  font-size: 12px;
  color: var(--text-muted);
}

.landing-news-arrows {
  display: flex;
  gap: 8px;
}

.landing-news-arrows button {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.2);
  border-radius: 50%;
  font-size: 17px;
  color: var(--hmte-navy);
  background: transparent;
  cursor: pointer;
  transition: color 180ms ease, background-color 180ms ease, border-color 180ms ease, transform 180ms var(--ease-out);
}

.landing-news-arrows button:hover:not(:disabled) {
  border-color: var(--hmte-navy);
  color: #fff;
  background: var(--hmte-navy);
  transform: translateY(-2px);
}

.landing-news-arrows button:disabled {
  opacity: 0.3;
  cursor: default;
}

.landing-news-viewport {
  position: relative;
}

/* Soft edge fades: the cut-off card plus the fade both say "there is more". */
.landing-news-viewport::before,
.landing-news-viewport::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 48px;
  z-index: 2;
  width: clamp(24px, 4vw, 72px);
  pointer-events: none;
}

.landing-news-viewport::before {
  left: calc(clamp(20px, 4vw, 64px) * -1);
  background: linear-gradient(90deg, var(--tre-off-white), transparent);
}

.landing-news-viewport::after {
  right: calc(clamp(20px, 4vw, 64px) * -1);
  background: linear-gradient(270deg, var(--tre-off-white), transparent);
}

.landing-news-badge {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 9px 14px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--hmte-navy-deep);
  background: var(--hmte-gold);
  box-shadow: 0 10px 24px -10px rgba(1, 15, 36, 0.5);
  pointer-events: none;
  opacity: 0;
  transition: opacity 200ms ease;
  will-change: transform;
}

.landing-news-badge > span {
  font-size: 12px;
}

.landing-news-badge[data-state='visible'] {
  opacity: 1;
}

.landing-news-track {
  display: flex;
  align-items: flex-start;
  gap: clamp(16px, 2.2vw, 34px);
  width: 100vw;
  margin-left: calc((100vw - min(1440px, calc(100vw - clamp(40px, 8vw, 128px)))) / -2);
  padding: 0 max(clamp(20px, 4vw, 64px), calc((100vw - 1440px) / 2)) 48px;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  cursor: grab;
  touch-action: pan-y;
  -webkit-user-select: none;
          user-select: none;
}

.landing-news-track::-webkit-scrollbar {
  display: none;
}

.landing-news-track.is-dragging {
  cursor: grabbing;
  scroll-snap-type: none;
}

.landing-news-card {
  flex: 0 0 min(34vw, 430px);
  min-width: 330px;
  overflow: hidden;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.13);
  border-radius: 22px;
  scroll-snap-align: start;
  background: #fff;
  opacity: 0;
  transform: translateY(34px);
  transition: border-color 220ms ease, box-shadow 220ms ease, transform 220ms var(--ease-out);
}

/* Cards rise in only once the section is actually on screen. */
.landing-news.is-inview .landing-news-card {
  animation: landing-news-card-in 640ms var(--ease-out) var(--card-delay, 0ms) both;
}

@keyframes landing-news-card-in {
  from { opacity: 0; transform: translateY(34px); }
  to { opacity: 1; transform: translateY(0); }
}

.landing-news-card:nth-child(even) {
  margin-top: 48px;
}

.landing-news-card.is-featured {
  flex-basis: min(62vw, 860px);
}

.landing-news.is-inview .landing-news-card:hover {
  border-color: var(--hmte-gold);
  box-shadow: 0 24px 56px rgba(var(--hmte-navy-rgb), 0.12);
  transform: translateY(-5px);
}

.landing-news-track.is-dragging .landing-news-card {
  transform: scale(0.988);
}

.landing-news-card > a {
  display: block;
  color: inherit;
}

.landing-news-image {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--hmte-navy);
}

.landing-news-card.is-featured .landing-news-image {
  aspect-ratio: 16 / 8.8;
}

.landing-news-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 52%, rgba(0, 19, 51, 0.72));
}

.landing-news-image img {
  object-fit: cover;
  /* --peek is written per-card while the track scrolls: a counter-drift
     parallax. The base scale leaves it room to move without exposing edges. */
  transform: translate3d(var(--peek, 0px), 0, 0) scale(1.08);
  transition: transform 620ms var(--ease-out);
}

.landing-news-card:hover .landing-news-image img {
  transform: translate3d(var(--peek, 0px), 0, 0) scale(1.12);
}

.landing-news-image > span {
  position: absolute;
  z-index: 1;
  left: 18px;
  bottom: 16px;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #fff;
  background: rgba(0, 19, 51, 0.46);
  -webkit-backdrop-filter: blur(8px);
          backdrop-filter: blur(8px);
}

.landing-news-card-copy {
  display: flex;
  flex-direction: column;
  min-height: 330px;
  padding: 24px;
}

.landing-news-card.is-featured .landing-news-card-copy {
  min-height: 310px;
  padding: clamp(24px, 3vw, 40px);
}

.landing-news-publisher {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 11px;
  color: var(--text-muted);
}

.landing-news-publisher > span {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  color: #fff;
  background: var(--hmte-navy);
}

.landing-news-publisher strong {
  font-weight: 700;
  color: var(--hmte-navy);
}

.landing-news-publisher time {
  margin-left: auto;
}

.landing-news-card h3 {
  margin-top: 20px;
  font-family: var(--font-display);
  font-size: clamp(24px, 2.4vw, 36px);
  line-height: 1.08;
  letter-spacing: -0.04em;
  color: var(--hmte-navy);
}

.landing-news-card.is-featured h3 {
  max-width: 760px;
  font-size: clamp(34px, 4.2vw, 62px);
  line-height: 0.98;
}

.landing-news-card-copy > p {
  display: -webkit-box;
  margin-top: 16px;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-height: 1.62;
  color: var(--text-muted);
}

.landing-news-card-copy > div:last-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: auto;
  padding-top: 28px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.landing-news-card-copy > div:last-child span {
  color: var(--text-muted);
}

.landing-news-card-copy > div:last-child strong {
  color: var(--hmte-navy);
}

@media (max-width: 900px) {
  .landing-news-head {
    grid-template-columns: 1fr;
  }

  .landing-news-card,
  .landing-news-card.is-featured {
    flex-basis: min(78vw, 620px);
    min-width: min(78vw, 620px);
  }

  .landing-news-card:nth-child(even) {
    margin-top: 28px;
  }
}

@media (max-width: 620px) {
  .landing-news-shell {
    width: calc(100% - 32px);
  }

  .landing-news-head h2 {
    font-size: clamp(50px, 16vw, 72px);
  }

  .landing-news-categories {
    margin-top: 52px;
  }

  .landing-news-stage-top {
    flex-wrap: wrap;
    gap: 14px;
  }

  .landing-news-stage-meta {
    grid-template-columns: 24px minmax(100px, 1fr) 24px;
    flex: 1 1 100%;
  }

  .landing-news-drag-note {
    display: none;
  }

  .landing-news-arrows {
    margin-left: auto;
  }

  .landing-news-viewport::before,
  .landing-news-viewport::after {
    display: none;
  }

  .landing-news-track {
    margin-left: -16px;
    padding-inline: 16px;
  }

  .landing-news-card,
  .landing-news-card.is-featured {
    flex-basis: 86vw;
    min-width: 86vw;
  }

  .landing-news-card:nth-child(even) {
    margin-top: 0;
  }

  .landing-news-card.is-featured .landing-news-image {
    aspect-ratio: 4 / 3;
  }

  .landing-news-card-copy,
  .landing-news-card.is-featured .landing-news-card-copy {
    min-height: 330px;
    padding: 22px;
  }

  .landing-news-card.is-featured h3 {
    font-size: 34px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .landing-news-card {
    opacity: 1;
    transform: none;
    animation: none;
    transition: none;
  }

  .landing-news.is-inview .landing-news-card {
    animation: none;
  }

  .landing-news-stage-meta i,
  .landing-news-image img,
  .landing-news-arrows button {
    transition: none;
  }

  .landing-news-image img {
    transform: none;
  }

  .landing-news-badge {
    display: none;
  }

  .landing-news-track {
    scroll-behavior: auto;
  }
}

/* Bidang & divisi: one integrated organism — the rail selects, the panel answers.
   Replaces the old kabinet grid + separate "etalase" (two selectors, one job). */
.org-x {
  padding-block: clamp(100px, 13vw, 180px);
  color: var(--hmte-navy);
  background: var(--tre-off-white);
}

.org-x-shell {
  width: min(1440px, calc(100% - clamp(40px, 8vw, 128px)));
  margin-inline: auto;
}

.org-x-head {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(300px, 0.8fr);
  gap: clamp(32px, 6vw, 110px);
  align-items: end;
}

.org-x-lead {
  max-width: 560px;
  font-size: clamp(15px, 1.5vw, 18px);
  line-height: 1.7;
  color: var(--text-muted);
}

.org-x-body {
  display: grid;
  grid-template-columns: minmax(300px, 0.58fr) minmax(0, 1.42fr);
  gap: clamp(28px, 4vw, 64px);
  align-items: start;
  margin-top: clamp(48px, 6vw, 92px);
  scroll-margin-top: 96px;
}

.org-rail {
  position: sticky;
  top: 96px;
  display: grid;
  border-top: 1px solid rgba(var(--hmte-navy-rgb), 0.18);
}

.org-rail-item {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-height: 76px;
  padding: 14px 18px 14px 12px;
  border: 0;
  border-bottom: 1px solid rgba(var(--hmte-navy-rgb), 0.18);
  text-align: left;
  color: var(--hmte-navy);
  background: transparent;
  cursor: pointer;
  transition: background-color 220ms var(--ease-out), color 220ms var(--ease-out);
}

.org-rail-num {
  justify-self: center;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--hmte-gold-deep);
}

.org-rail-copy {
  min-width: 0;
}

.org-rail-copy strong {
  display: block;
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.org-rail-copy small {
  display: block;
  overflow: hidden;
  margin-top: 3px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.org-rail-arrow {
  opacity: 0;
  transform: translateX(-8px);
  transition: opacity 220ms var(--ease-out), transform 220ms var(--ease-out);
  font-size: 14px;
}

.org-rail-item:hover {
  background: rgba(var(--hmte-navy-rgb), 0.055);
}

.org-rail-item.is-active {
  background: var(--hmte-navy);
  color: #fff;
}

.org-rail-item.is-active .org-rail-num {
  color: var(--hmte-gold);
}

.org-rail-item.is-active .org-rail-copy small {
  color: rgba(255, 255, 255, 0.72);
}

.org-rail-item:hover .org-rail-arrow,
.org-rail-item.is-active .org-rail-arrow {
  opacity: 1;
  transform: translateX(0);
}

.org-rail-item:focus-visible {
  outline: 2px solid var(--hmte-gold-deep);
  outline-offset: -2px;
}

.org-panel {
  overflow: hidden;
  border: 1px solid rgba(var(--hmte-navy-rgb), 0.14);
  border-radius: 24px;
  background: #fff;
  box-shadow: 0 34px 80px -46px rgba(var(--hmte-navy-rgb), 0.4);
