.newsroom::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  z-index: 0;
  height: 240px;
  background: linear-gradient(180deg, rgba(var(--hmte-navy-rgb), 0.09), rgba(var(--hmte-navy-rgb), 0));
  pointer-events: none;
