}

.newsroom-story-media img {
  object-fit: cover;
  transition: transform 700ms var(--sr-ease);
}

.newsroom-story:hover .newsroom-story-media img {
  transform: scale(1.025);
}

/* Sampul cadangan diredam sampai jadi bidang bernada, bukan lukisan. Yang
   dilihat pengunjung pertama kali harus judul beritanya, bukan bola navy
   selebar 780px yang kebetulan digambar mesin. */
.newsroom-story-media[data-placeholder] {
  background: var(--sr-card-quiet);
}

/* Diredam lewat opacity saja. `saturate()` menariknya ke abu-abu, dan abu-abu
   di atas kertas hangat terbaca seperti gambar yang gagal dimuat. */
.newsroom-story-media[data-placeholder] .article-cover-art {
  opacity: 0.14;
}

/* Bidangnya dibesarkan sampai tepinya keluar bingkai. Selama bentuknya masih
   punya tepi, mata membacanya sebagai OBJEK — dan objek terbesar di seksi ini
   tidak boleh berupa gambar yang belum ada. Diperbesar, ia tinggal gradasi. */
.newsroom-story-media[data-placeholder] .article-cover-art .hero-backdrop-figure {
  transform: scale(1.75);
}

.newsroom-story-media[data-placeholder]::after {
  content: 'Dokumentasi menyusul';
  position: absolute;
  inset: auto 0 0;
  z-index: 1;
  padding: 0 18px 22px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--sr-ink-soft);
}

.newsroom-story-tag {
  position: absolute;
  z-index: 2;
  bottom: 16px;
  left: 16px;
  padding: 7px 13px;
  border-radius: var(--sr-pill);
  font-size: 11px;
  font-weight: 750;
  color: var(--hmte-navy-deep);
  background: var(--hmte-gold);
  box-shadow: 0 3px 12px rgba(0, 10, 28, 0.26);
}

.newsroom-story-copy {
  padding: clamp(20px, 2.4vw, 30px) clamp(20px, 2.6vw, 34px) clamp(22px, 2.8vw, 32px);
}

.newsroom-story-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 12px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--sr-ink-soft);
}

.newsroom-story-meta span::before {
  content: '·';
  margin-right: 10px;
}

.newsroom-story-copy h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(23px, 2.3vw, 33px);
  font-weight: 600;
  line-height: 1.14;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.newsroom-story-copy h3 a {
  color: var(--hmte-navy);
  background-image: linear-gradient(var(--hmte-gold), var(--hmte-gold));
  background-repeat: no-repeat;
  background-position: 0 100%;
  background-size: 0 2px;
  transition: background-size 260ms var(--sr-ease);
}

.newsroom-story-copy h3 a:hover {
  background-size: 100% 2px;
}

.newsroom-story-excerpt {
  display: -webkit-box;
  max-width: 60ch;
  margin: 14px 0 0;
  overflow: hidden;
  font-size: 15px;
  line-height: 1.68;
  color: var(--sr-ink-soft);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.newsroom-story-byline {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 22px 0 0;
  font-size: 12px;
}

.newsroom-story-byline > span {
  font-weight: 700;
  color: var(--hmte-navy);
}

.newsroom-story-read {
  margin-left: auto;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--hmte-gold);
  font-size: 12px;
  font-weight: 750;
  color: var(--hmte-navy);
}

.newsroom-story-read:hover {
  border-bottom-color: var(--hmte-navy);
}

/* ---------- Daftar cerita pendamping ---------- */
.newsroom-more {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.newsroom-more-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin: 0 0 2px;
  padding: 6px 14px 0;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--sr-ink-soft);
}

.newsroom-more-head span:last-child {
  font-weight: 600;
  color: var(--hmte-navy);
}

.newsroom-more-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.newsroom-more-list button {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 3px 10px;
  width: 100%;
  padding: 13px 14px;
  border: 0;
  border-radius: var(--sr-md);
  text-align: left;
  background: transparent;
  cursor: pointer;
  transition: background 180ms var(--sr-ease), box-shadow 180ms var(--sr-ease);
}

.newsroom-more-list button:hover {
  background: rgba(var(--hmte-navy-rgb), 0.05);
}

/* Baris terpilih ditandai oleh PERMUKAAN, bukan garis: ia terangkat jadi kartu
   putih, sama seperti berita utama di sebelahnya. */
.newsroom-more-list button.is-active {
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
}

.newsroom-more-list i {
  font-family: var(--font-mono);
  font-size: 11px;
  font-style: normal;
  font-weight: 600;
  line-height: 1.7;
  color: var(--sr-ink-faint);
}

.newsroom-more-list button.is-active i {
  color: var(--hmte-gold-deep);
}

.newsroom-more-list strong {
  display: -webkit-box;
  overflow: hidden;
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.36;
  letter-spacing: -0.01em;
  color: var(--sr-ink);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.newsroom-more-list button.is-active strong {
  color: var(--hmte-navy);
}

.newsroom-more-list small {
  grid-column: 2;
  font-size: 11px;
  color: var(--sr-ink-soft);
}

/* ---------- Keadaan kosong ---------- */
.newsroom-empty {
  max-width: 720px;
  margin-top: clamp(28px, 4vw, 44px);
  padding: clamp(24px, 3.4vw, 38px);
  border-radius: var(--sr-lg);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
}

.newsroom-empty p {
  max-width: 58ch;
  margin: 0;
  font-size: 15px;
  line-height: 1.7;
  color: var(--sr-ink-soft);
}

.newsroom-empty div {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 12px;
  margin-top: 22px;
}

.newsroom-empty a {
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  padding: 0 18px;
  border-radius: var(--sr-pill);
  font-size: 12px;
  font-weight: 700;
  color: var(--hmte-navy);
  background: var(--sr-sunken);
  transition: background 180ms var(--sr-ease);
}

.newsroom-empty a:first-child {
  color: #fff;
  background: var(--hmte-navy);
}

.newsroom-empty a:hover {
  background: rgba(var(--hmte-navy-rgb), 0.14);
}

.newsroom-empty a:first-child:hover {
  background: var(--hmte-navy-light);
}

/* ---------- Responsif ---------- */
@media (max-width: 980px) {
  .newsroom-body {
    grid-template-columns: minmax(0, 1fr);
  }

  .newsroom-more {
    margin-top: 6px;
  }
}

@media (max-width: 700px) {
  .newsroom-masthead {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
  }

  .newsroom-masthead h2 {
    max-width: none;
  }

  .newsroom-index-link {
    justify-self: start;
  }

  .newsroom-story-media {
    aspect-ratio: 4 / 3;
  }

  .newsroom-story-byline {
    flex-wrap: wrap;
    gap: 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .newsroom-story {
    animation: none;
  }

  .newsroom-story:hover .newsroom-story-media img {
    transform: none;
  }
}

/* ------------------------------------------------------------
   ORGANIZATION SWITCHBOARD

   Kanvasnya disamakan dengan .newsroom: 1120px, bukan 1440px. Dua seksi
   berurutan dengan kanvas berbeda membuat beranda terbaca seperti dua
   halaman yang ditempel, dan yang 1440px selalu jadi yang salah — panelnya
   berhenti beberapa puluh piksel dari tepi layar, jadi ia tidak terbaca
   sebagai full-bleed maupun sebagai kartu.

   Judulnya juga diturunkan dari 96px. Di seksi ini kata "Pengurus Harian"
   muncul DUA KALI dalam satu layar: sekali sebagai judul seksi, sekali lagi
   sebagai judul unsur terpilih di dalam panel. Dua-duanya di atas 80px
   membuat layar itu tidak punya satu pun titik masuk yang jelas.
   ------------------------------------------------------------ */
.org-switchboard {
  padding: clamp(72px, 8vw, 120px) 0 clamp(84px, 10vw, 140px);
  color: var(--hmte-navy);
  background: #f4f4f1;
}

.org-switchboard-shell {
  width: min(1120px, calc(100% - clamp(32px, 6vw, 96px)));
  margin-inline: auto;
}

.org-switchboard-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 18px clamp(24px, 4vw, 60px);
}

.org-switchboard-kicker {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--sr-ink-soft);
}

.org-switchboard-kicker::before {
  content: '';
  width: 22px;
  height: 2px;
  border-radius: 2px;
  background: var(--hmte-gold-deep);
}

.org-switchboard-head h2 {
  max-width: 17ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(30px, 3.3vw, 46px);
  font-weight: 600;
  line-height: 1.04;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

.org-switchboard-head h2 span {
  color: #68758a;
}

.org-switchboard-standfirst {
  max-width: 58ch;
  margin: 14px 0 0;
  font-size: 15px;
  line-height: 1.68;
  color: var(--sr-ink-soft);
  text-wrap: pretty;
}

.org-switchboard-index-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 42px;
  padding: 0 20px;
  border-radius: var(--sr-pill);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  color: #fff;
  background: var(--hmte-navy);
  box-shadow: var(--sr-shadow-1);
  transition: background 200ms var(--sr-ease);
}

.org-switchboard-index-link::after {
  content: '';
  width: 14px;
  height: 8px;
  background: currentColor;
  transition: transform 220ms var(--sr-ease);
  clip-path: polygon(0 40%, 62% 40%, 62% 0, 100% 50%, 62% 100%, 62% 60%, 0 60%);
}

.org-switchboard-index-link:hover {
  background: var(--hmte-navy-light);
}

.org-switchboard-index-link:hover::after {
  transform: translateX(3px);
}

/* Emas di dalam panel navy, navy di atas kertas. Satu warna fokus untuk dua
   latar yang berlawanan selalu gagal di salah satunya. */
.org-switchboard-body :is(a, button):focus-visible {
  outline: 2px solid var(--hmte-gold);
  outline-offset: 3px;
}

.org-switchboard-head a:focus-visible {
  outline: 2px solid var(--hmte-navy);
  outline-offset: 3px;
}

.org-switchboard-body {
  margin-top: clamp(28px, 3.6vw, 46px);
  overflow: hidden;
  border-radius: var(--sr-lg, 24px);
  color: #fff;
  background: #001637;
  box-shadow: var(--sr-shadow-2);
}

/* `grid-auto-rows: 1fr` bukan hiasan. Delapan unsur ini setara, jadi kotaknya
   harus sama besar; tanpa ini, baris yang memuat nama dua baris tumbuh sendiri
   dan baris satunya menyusut — ukuran jadi terbaca sebagai peringkat. */
.org-switches {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: 1fr;
  gap: 10px;
  padding: clamp(18px, 2.4vw, 26px);
}

.org-switches button {
  min-width: 0;
  min-height: 86px;
  padding: 16px 14px;
  border: 0;
  border-radius: var(--sr-md, 18px);
  text-align: left;
  color: rgba(255, 255, 255, 0.64);
  background: rgba(255, 255, 255, 0.05);
  cursor: pointer;
  transition:
    color 220ms var(--ease-out),
    background-color 260ms var(--ease-out);
}

.org-switches button:hover,
.org-switches button.is-active {
  color: var(--hmte-navy-deep);
  background: var(--hmte-gold);
}

.org-switches span,
.org-switches small {
  display: block;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.org-switches strong {
  display: block;
  margin-top: 12px;
  font-family: var(--font-display);
  font-size: 15px;
}

/* Dua baris, bukan satu baris terpotong. Di kanvas 1120px tombolnya 260px dan
   "Pengembangan Hubungan Antar Lembaga" berhenti di "LEM…" — nama bidang yang
   terpenggal justru lebih membingungkan daripada nama yang mengambil dua
   baris. */
.org-switches small {
  display: -webkit-box;
  overflow: hidden;
  margin-top: 5px;
  line-height: 1.45;
  color: currentColor;
  opacity: 0.64;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.org-signal {
  animation: org-signal-cut 520ms var(--ease-out) both;
}

@keyframes org-signal-cut {
  from { opacity: 0.35; clip-path: inset(0 0 14% 0); }
  to { opacity: 1; clip-path: inset(0); }
}

.org-signal-head {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(240px, 0.55fr);
  align-items: end;
  gap: clamp(20px, 3vw, 48px);
  padding: clamp(28px, 3.6vw, 46px) clamp(28px, 3.6vw, 46px) clamp(24px, 3vw, 38px);
}

.org-signal-head span {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--hmte-gold);
}

/* Judul unsur terpilih sengaja lebih kecil daripada judul seksi. Ia berubah
   tiap kali tombol ditekan, jadi ia keterangan panel — bukan judul kedua yang
   bersaing dengan judul seksi di atasnya. */
.org-signal-head h3 {
  max-width: 20ch;
  margin: 10px 0 0;
  font-family: var(--font-display);
  font-size: clamp(26px, 2.7vw, 38px);
  font-weight: 600;
  line-height: 1.04;
  letter-spacing: -0.03em;
  text-wrap: balance;
}

.org-signal-head > p {
  margin: 0;
  font-size: 15px;
  line-height: 1.68;
  color: rgba(255, 255, 255, 0.68);
}

/* `align-items: start` supaya kartu program berhenti setelah isinya habis.
   Dengan stretch, tiga program di sebelah lima pengurus meninggalkan setengah
   bidang biru kosong yang terbaca seperti konten yang gagal dimuat. */
.org-signal-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(260px, 0.5fr);
  align-items: start;
  gap: clamp(14px, 1.6vw, 20px);
  padding: 0 clamp(18px, 2.4vw, 26px) clamp(18px, 2.4vw, 26px);
}

.org-signal-people,
.org-signal-programs {
  padding: clamp(22px, 2.6vw, 32px);
}

.org-signal-programs {
  border-radius: var(--sr-lg, 24px);
  background: #071f49;
}

.org-signal-label {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
  font-size: 11px;
}

.org-signal-label span {
  color: rgba(255, 255, 255, 0.48);
}

.org-people-runway {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.org-person {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border-radius: var(--sr-md, 18px);
  color: #fff;
  background: rgba(255, 255, 255, 0.05);
}

.org-person-photo {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 4 / 4.5;
  overflow: hidden;
  background: #dfe3e8;
}

.org-person-photo img:not(.org-person-logo) {
  object-fit: cover;
  filter: saturate(0.76);
  transition: transform 500ms var(--ease-out), filter 240ms ease;
}

.org-person:hover .org-person-photo img:not(.org-person-logo) {
  transform: scale(1.045);
  filter: saturate(1);
}

.org-person-logo {
  width: 70px;
  height: auto;
  opacity: 0.68;
}

.org-person > div:last-child {
  padding: 14px 14px 16px;
}

.org-person h4 {
  overflow: hidden;
  margin: 0;
  font-family: var(--font-display);
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.org-person p {
  overflow: hidden;
  margin: 6px 0 0;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.62);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.org-signal-program-list > div {
  display: grid;
  grid-template-columns: 25px minmax(0, 1fr);
  padding: 19px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.org-signal-program-list > div:last-child {
  border-bottom: 0;
}

.org-signal-program-list span {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--hmte-gold);
}

.org-signal-program-list h4 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 15px;
  line-height: 1.25;
}

.org-signal-program-list p {
  grid-column: 2;
  margin: 6px 0 0;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.58);
}

.org-signal-programs > a {
  display: inline-flex;
  margin-top: 26px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--hmte-gold);
  font-size: 11px;
  font-weight: 750;
  color: var(--hmte-gold);
}

.org-signal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  padding: 20px clamp(28px, 3.6vw, 46px);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.org-signal-foot p {
  margin: 0;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.52);
}

.org-signal-foot > div {
  display: flex;
  gap: 9px;
}

.org-signal-foot a {
  display: inline-flex;
  align-items: center;
  min-height: 42px;
  padding: 0 16px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 750;
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
}

.org-signal-foot a:last-child {
  color: var(--hmte-navy-deep);
  background: var(--hmte-gold);
}

/* ------------------------------------------------------------
   MEMORY WALL REFINEMENT
   ------------------------------------------------------------ */
.moment-wall {
  background:
    radial-gradient(circle at 86% 16%, rgba(32, 91, 157, 0.24), transparent 38%),
    #00122e;
}

.moment-wall::before {
  content: 'MEMORI 2026/2027';
  position: absolute;
  top: 42px;
  right: -0.04em;
  font-family: var(--font-display);
  font-size: clamp(74px, 15vw, 210px);
  font-weight: 700;
  line-height: 0.8;
  letter-spacing: -0.04em;
  color: rgba(255, 255, 255, 0.025);
  pointer-events: none;
}

.moment-wall-head h2 {
  max-width: 860px;
  font-size: clamp(48px, 6.5vw, 92px);
  letter-spacing: -0.04em;
}

.moment-wall-grid {
  align-items: start;
}

.moment-tile {
  opacity: 1;
}

.moment-tile:nth-child(2) {
  margin-top: clamp(60px, 8vw, 120px);
}

.moment-tile:nth-child(3) {
  margin-top: clamp(18px, 3vw, 46px);
}

.moment-tile:nth-child(5) {
  margin-top: clamp(-46px, -3vw, -20px);
}

.moment-tile-photo {
  outline: 1px solid rgba(255, 255, 255, 0.14);
  outline-offset: 7px;
}

@media (max-width: 1100px) {
  /* Tombol unsur dan panel program sudah jadi kartu membulat berjarak, jadi
     garis pemisah peninggalan versi lama tinggal garis nyasar. Dihapus, bukan
     ditimpa. */
  .org-signal-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  .about-field-stage {
    position: relative;
    top: auto;
    height: 54svh;
    min-height: 390px;
  }

  .about-field-identity {
    width: calc(100% - 40px);
    left: 20px;
    bottom: 28px;
  }

  .about-field-logo {
    width: min(210px, 60vw);
  }

  .about-field-story {
    width: 100%;
    margin: 0;
    padding: 0 20px;
    background: linear-gradient(180deg, rgba(0, 20, 51, 0.9), #001433 22%);
  }

  .about-field-intro,
  .about-field-chapter {
    min-height: 72svh;
  }

  .org-switchboard-head,
  .org-signal-head {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .org-switchboard-head h2 {
    max-width: none;
  }

  .org-switchboard-index-link {
    justify-self: start;
