/*
 * Setiap unsur dapat plat yang identik. Irama datang dari pergantian tinta dan
 * kertas, tidak pernah dari ukuran, supaya tidak ada bidang yang terbaca lebih
 * tinggi dari yang lain.
 *
 * Papan ini dulu memakai gap 1px di atas latar navy supaya sambungan antar plat
 * terbaca sebagai garis rambut. Delapan plat berbagi satu kerangka, jadi
 * batasnya berlipat dan layar penuh garis. Sekarang tiap plat berdiri sendiri:
 * jarak dan bayangan yang memisahkan.
 */
.division-board {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.division-plate {
  --plate-surface: var(--tre-paper, #fff);
  --plate-ink: var(--hmte-navy);
  --plate-dim: var(--fg-muted);
  --plate-stroke: rgba(var(--hmte-navy-rgb), 0.2);
  --plate-texture: 0;
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  min-height: 296px;
  min-width: 0;
  overflow: hidden;
  border-radius: var(--sr-lg, 24px);
  color: var(--plate-ink);
  background: var(--plate-surface);
  box-shadow: var(--sr-shadow-1);
  text-decoration: none;
  isolation: isolate;
  transition:
    color 320ms var(--ease-out),
    background-color 420ms var(--ease-out),
    box-shadow 320ms var(--ease-out),
    transform 320ms var(--ease-out);
}

/* Checker across two rows of four: ink at 1, 3, 6, 8. */
.division-plate:nth-child(8n + 1),
.division-plate:nth-child(8n + 3),
.division-plate:nth-child(8n + 6),
.division-plate:nth-child(8n + 8) {
  --plate-surface: var(--hmte-navy-deep);
  --plate-ink: #fff;
  --plate-dim: #a9bad2;
  --plate-stroke: rgba(255, 255, 255, 0.24);
  --plate-texture: 0.16;
}

.division-plate-texture {
  z-index: -1;
  object-fit: cover;
  opacity: var(--plate-texture);
  filter: grayscale(1) contrast(1.1);
  mix-blend-mode: luminosity;
  transition: opacity 520ms var(--ease-out), transform 720ms var(--ease-out);
}

/*
 * Spine label: centred in the rail with justify-self (resolved in the grid's
 * own horizontal writing mode) while the text itself runs bottom-to-top.
 */
.division-plate-spine {
  justify-self: center;
  align-self: stretch;
  padding: 18px 0;
  color: var(--plate-dim);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-align: center;
  text-transform: uppercase;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  transition: color 320ms var(--ease-out);
}

.division-plate-index {
  position: absolute;
  top: 10px;
  right: 16px;
  color: transparent;
  font-family: var(--font-mono);
  font-size: 54px;
  font-weight: 800;
  line-height: 1;
  -webkit-text-stroke: 1px var(--plate-stroke);
  transition: -webkit-text-stroke-color 320ms var(--ease-out);
  pointer-events: none;
  -webkit-user-select: none;
          user-select: none;
}

.division-plate-body {
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  gap: 12px;
  padding: 72px 22px 22px;
  min-width: 0;
}

.division-plate-body h3 {
  max-width: 15ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(20px, 1.7vw, 25px);
  font-weight: 600;
  line-height: 1.06;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.division-plate-body > p {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: var(--plate-dim);
  font-size: 12px;
  line-height: 1.6;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.division-plate-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  grid-row: 4;
  padding-top: 16px;
  color: var(--plate-dim);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: color 320ms var(--ease-out);
}

.division-plate-meta b {
  margin-left: auto;
  color: var(--hmte-gold);
  font-size: 17px;
  transition: transform 320ms var(--ease-out);
}

/* Specificity kept above the checker rules so hover wins at every breakpoint. */
.division-board .division-plate:hover {
  --plate-surface: var(--hmte-navy-deep);
  --plate-ink: #fff;
  --plate-dim: #cbd8e8;
  --plate-stroke: var(--hmte-gold);
  --plate-texture: 0.34;
  transform: translateY(-3px);
  box-shadow: var(--sr-shadow-2);
}

.division-plate:hover .division-plate-texture {
  transform: scale(1.05);
}

.division-plate:hover .division-plate-meta b {
  transform: translate(4px, -4px);
}

.division-plate:focus-visible {
  outline: 3px solid var(--hmte-gold);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .division-board .division-plate:hover {
    transform: none;
  }
}

