.hero-backdrop {
  position: absolute;
  z-index: 0;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(
      circle at var(--backdrop-light-x, 82%) var(--backdrop-light-y, 12%),
      rgba(var(--hmte-gold-rgb), var(--backdrop-light-strength, 0.17)),
      transparent 26%
    ),
    linear-gradient(135deg, var(--hmte-navy-deep), var(--hmte-navy) 62%, #062c5c);
}

.hero-backdrop-figure {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

/*
 * The field's gold light is placed to agree with where each SVG form is lit,
 * otherwise the page glow and the surface shading fight each other and the
 * volume flattens out again.
 */
.hero-backdrop[data-variant='arc'] {
  --backdrop-light-x: 82%;
  --backdrop-light-y: 12%;
}

.hero-backdrop[data-variant='orbit'] {
  --backdrop-light-x: 33%;
  --backdrop-light-y: 25%;
  --backdrop-light-strength: 0.15;
}

.hero-backdrop[data-variant='dome'] {
  --backdrop-light-x: 41%;
  --backdrop-light-y: 56%;
  --backdrop-light-strength: 0.15;
}

.hero-backdrop[data-variant='crest'] {
  --backdrop-light-x: 79%;
  --backdrop-light-y: 21%;
  --backdrop-light-strength: 0.18;
