  /* 4.92:1 di atas latar input yang sudah dikomposit (#E1E1DF). Placeholder abu
     terang adalah kegagalan kontras paling umum dan paling mudah lolos tanpa
     ketahuan, jadi nadanya ditarik sampai selevel teks sekunder. */
  color: var(--sr-ink-soft);
}

.soft-search input:focus {
  outline: 2px solid var(--hmte-navy);
  outline-offset: 2px;
  background: var(--sr-card);
}

/* ---- Badge tanggal ----
   Model waktu yang menggantikan rail dua belas bulan. Tanggal pasti tampil
   sebagai angka besar yang benar-benar terbaca; program yang baru punya bulan
   rencana menampilkan bulannya saja, dengan nada lebih redup supaya perbedaan
   kepastiannya terlihat tanpa perlu keterangan. */

.date-badge {
  display: grid;
  place-content: center;
  gap: 1px;
  width: 58px;
  min-height: 58px;
  padding: 8px 4px;
  border-radius: var(--sr-md);
  background: var(--div-tint);
  text-align: center;
}

.date-badge b {
  display: block;
  color: var(--div);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
}

.date-badge span {
  display: block;
  color: var(--div);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Belum bertanggal: hanya bulan, tanpa angka hari, dan lebih tenang. */
.date-badge[data-precision='planned'] {
  background: rgba(var(--hmte-navy-rgb), 0.05);
}

.date-badge[data-precision='planned'] b,
.date-badge[data-precision='planned'] span {
  color: var(--sr-ink-soft);
}

.date-badge[data-precision='planned'] span {
  font-size: 11px;
}

.date-badge[data-precision='unscheduled'] {
  background: rgba(var(--hmte-navy-rgb), 0.04);
}

/* "Belum" itu teks, bukan hiasan, jadi harus lolos 4.5:1. --sr-ink-faint cuma
   2.86:1 di atas nada badge ini dan tidak boleh dipakai untuk teks. */
.date-badge[data-precision='unscheduled'] span {
  color: var(--sr-ink-soft);
  font-size: 10px;
}

/* Jumlah bulan tambahan pada program yang jatuh di beberapa bulan. */
.date-badge-more {
  color: var(--sr-ink-soft);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0;
}

.date-badge[data-precision='planned'] b.date-badge-more {
  font-size: 10px;
}

/* ---- Label kecil ---- */

/* justify-self penting: tag ini sering jadi anak grid, dan tanpa ini ia
   meregang selebar kartu. */
.soft-tag {
  display: inline-flex;
  justify-self: start;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--sr-pill);
  background: var(--div-tint);
  color: var(--div);
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.soft-tag-quiet {
  background: rgba(var(--hmte-navy-rgb), 0.055);
  color: var(--sr-ink-soft);
}

/* ---- Keadaan kosong ---- */

.soft-empty {
  display: grid;
  place-items: center;
  gap: 6px;
  padding: clamp(48px, 8vw, 88px) 24px;
  border-radius: var(--sr-lg);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
  text-align: center;
}

.soft-empty strong {
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
}

.soft-empty p {
  max-width: 40ch;
  margin: 0;
  color: var(--sr-ink-soft);
  font-size: 13.5px;
  line-height: 1.6;
}

.soft-empty button {
  min-height: 42px;
  margin-top: 10px;
  padding: 0 20px;
  border: 0;
  border-radius: var(--sr-pill);
  color: #fff;
  background: var(--hmte-navy);
  font: 600 13px var(--font-body);
  cursor: pointer;
  transition: background-color 200ms var(--sr-ease);
}

.soft-empty button:hover {
  background: var(--hmte-navy-deep);
}

@media (prefers-reduced-motion: reduce) {
  .soft-pills button,
  .soft-pills button i,
  .soft-search input,
  .soft-empty button {
    transition: none;
  }
}

/* ============================================================
   /kepengurusan : direktori berkelompok
   ============================================================ */

.ppl-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: clamp(24px, 3vw, 36px);
}

.ppl-toolbar-side {
  display: flex;
  align-items: center;
  gap: 16px;
}

.ppl-count {
  margin: 0;
  color: var(--sr-ink-soft);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

/*
 * Multi-kolom, bukan grid. Tiap bidang punya jumlah anggota berbeda (5 sampai
 * 11), jadi kartunya tingginya berbeda-beda. Grid akan meregangkan semuanya ke
 * baris tertinggi dan meninggalkan lubang; kolom membiarkan kartu mengalir
 * rapat mengikuti tingginya masing-masing.
 */
.ppl-columns {
  columns: 2;
  column-gap: 20px;
}

.ppl-group {
  display: block;
  margin: 0 0 20px;
  padding: 18px 18px 8px;
  page-break-inside: avoid;
  break-inside: avoid;
}

.ppl-group-head {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 0 4px 14px;
}

.ppl-group-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: var(--sr-sm);
  color: #fff;
  background: var(--div);
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.ppl-group-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ppl-group-copy h2 {
  margin: 0;
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.015em;
}

.ppl-group-copy small {
  color: var(--sr-ink-soft);
  font-size: 12px;
  font-weight: 500;
}

.ppl-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.ppl-row {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 12px;
  gap: 12px;
  align-items: center;
  padding: 9px 4px;
  border-radius: var(--sr-sm);
  color: var(--sr-ink);
  text-decoration: none;
  transition: background-color 180ms var(--sr-ease);
}

.ppl-row:hover {
  background: var(--div-tint);
}

.ppl-row:focus-visible {
  outline: 2px solid var(--div);
  outline-offset: -2px;
}

/*
 * Pemisah baris adalah satu-satunya garis yang diizinkan sistem ini, dan hanya
 * di dalam kartu. Inset dari tepi supaya kartunya tetap terbaca sebagai satu
 * permukaan utuh, bukan sebagai tabel.
 */
.ppl-list li + li .ppl-row {
  box-shadow: inset 0 1px 0 rgba(var(--hmte-navy-rgb), 0.07);
}

.ppl-avatar {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: var(--div);
  background: var(--div-tint);
  font-family: var(--font-display);
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

/* Jabatan inti: avatar pejal. Hierarki tanpa mengubah ukuran atau menambah garis. */
.ppl-avatar[data-core='true'] {
  color: #fff;
  background: var(--div);
}

.ppl-copy {
  display: grid;
  gap: 1px;
  min-width: 0;
}

.ppl-copy strong {
  overflow: hidden;
  font-family: var(--font-body);
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ppl-copy small {
  overflow: hidden;
  color: var(--sr-ink-soft);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ppl-chev {
  color: var(--sr-ink-faint);
  font-size: 17px;
  line-height: 1;
  transition: transform 180ms var(--sr-ease), color 180ms var(--sr-ease);
}

.ppl-row:hover .ppl-chev {
  color: var(--div);
  transform: translateX(2px);
}

@media (max-width: 900px) {
  .ppl-columns {
    columns: 1;
  }

  .ppl-toolbar-side {
    width: 100%;
  }

  .soft-search {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ppl-row,
  .ppl-chev {
    transition: none;
  }
}

/* ---- Hero /kepengurusan ---- */

.ppl-hero {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(20px, 4vw, 60px);
  flex-wrap: wrap;
  margin-bottom: clamp(28px, 4vw, 44px);
  padding: clamp(28px, 4vw, 52px);
  overflow: hidden;
  border-radius: var(--sr-lg);
  color: #fff;
  background: var(--hmte-navy-deep);
  isolation: isolate;
}

.ppl-hero-copy {
  position: relative;
  z-index: 1;
  max-width: 56ch;
}

.ppl-hero-copy > p:first-child {
  margin: 0 0 14px;
  color: var(--hmte-gold);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.ppl-hero-copy h1 {
  margin: 0;
  font-family: var(--font-display);
  /* Plafon clamp dijaga jauh di bawah 96px: ini halaman direktori, bukan hero
     kampanye, dan judul yang berteriak justru menambah kelelahan visual. */
  font-size: clamp(28px, 4vw, 52px);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: -0.035em;
  text-wrap: balance;
}

.ppl-hero-copy h1 span {
  color: var(--hmte-gold);
}

.ppl-hero-lead {
  max-width: 52ch;
  margin: 16px 0 0;
  color: #C6D3E2;
  /* Teks terang di atas gelap terbaca lebih tipis, jadi line-height ditambah. */
  font-size: 14.5px;
  line-height: 1.72;
  text-wrap: pretty;
}

.ppl-hero-mark {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
}

.ppl-hero-mark img {
  display: block;
  width: clamp(88px, 11vw, 150px);
  height: auto;
}

/*
 * Ringkasan angka di hero. Ditambahkan saat /divisi dilebur ke sini: angkanya
 * dulu ada di hero /divisi, dan menghapus halaman itu tanpa memindahkan
 * ringkasannya akan menghilangkan satu-satunya tempat pengunjung bisa tahu
 * berapa besar kepengurusan ini tanpa menghitung sendiri.
 */
.ppl-hero-stats {
  display: flex;
  gap: clamp(20px, 3vw, 40px);
  flex-wrap: wrap;
  margin: clamp(20px, 3vw, 30px) 0 0;
}

.ppl-hero-stats > div {
  display: grid;
  gap: 4px;
}

.ppl-hero-stats dt {
  color: rgba(255, 255, 255, 0.62);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ppl-hero-stats dd {
  margin: 0;
  color: var(--hmte-gold);
  font-family: var(--font-display);
  font-size: clamp(26px, 3vw, 36px);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.03em;
}

/*
 * Papan bidang dulu berupa section selebar layar dengan latarnya sendiri di
 * /divisi. Di sini ia satu balok di dalam .soft-shell, jadi padding dan latar
 * seksinya dilepas; jaraknya diurus alirannya sendiri.
 */
.soft-shell > .division-index-board {
  padding: 0;
  margin-bottom: clamp(34px, 5vw, 56px);
  background: none;
}

/* ============================================================
   /program-kerja : masthead, beban tahun, sorotan, register
   ============================================================ */

/*
 * Halaman ini punya dua wilayah, bukan satu bidang beige seragam.
 *
 * Versi sebelumnya menyebut dirinya bento, padahal isinya satu panel navy plus
 * tiga tegel angka yang cuma mengulang kalimat di sebelahnya, lalu tiga kartu
 * berfoto, lalu tiga puluh tujuh kartu putih yang identik. Empat blok, satu
 * bahasa visual, dan tidak ada satu pun yang memberi tahu sesuatu yang belum
 * tertulis. Itulah yang terbaca membosankan: bukan warnanya, melainkan tidak
 * adanya perbedaan di antara benda-bendanya.
 *
 * Sekarang empat blok itu berbicara dengan empat cara berbeda. Masthead adalah
 * bidang navy penuh dengan grafik beban tahun (satu-satunya keterangan yang
 * tidak bisa dibaca dari daftar). Sorotan adalah tegel berwarna pejal milik
 * bidangnya. Katalog adalah register padat berpalang warna. Ketiganya duduk di
 * atas permukaan yang berbeda, jadi menggulir halaman terasa berpindah tempat.
 */

.pk-masthead {
  position: relative;
  padding: clamp(52px, 7vw, 96px) 0 clamp(38px, 5vw, 62px);
  overflow: hidden;
  color: #fff;
  background: var(--hmte-navy-deep);
  isolation: isolate;
}

.pk-masthead-inner {
  position: relative;
  z-index: 1;
  display: grid;
  gap: clamp(30px, 4.5vw, 56px);
}

.pk-masthead-kicker {
  margin: 0 0 16px;
  color: var(--hmte-gold);
  font-size: 12.5px;
  font-weight: 600;
}

.pk-masthead-copy h1 {
  max-width: 17ch;
  margin: 0;
  font-family: var(--font-display);
  /* Plafon jauh di bawah 96px. Ini halaman katalog, bukan halaman kampanye. */
  font-size: clamp(32px, 5vw, 68px);
  font-weight: 600;
  line-height: 1.04;
  letter-spacing: -0.038em;
  text-wrap: balance;
}

.pk-masthead-copy h1 span {
  color: var(--hmte-gold);
}

.pk-masthead-lead {
  max-width: 58ch;
  margin: 20px 0 0;
  color: #C6D3E2;
  /* Teks terang di atas gelap terbaca lebih tipis, jadi line-height ditambah. */
  font-size: 14.5px;
  line-height: 1.72;
  text-wrap: pretty;
}

/* ---- Beban tahun ----
   Dua belas batang setinggi jumlah program yang jatuh di bulan itu. Ini
   satu-satunya bagian halaman yang menjawab "kapan sibuknya", dan jawabannya
   tidak ada di mana pun lagi di situs kecuali kalau pengunjung menghitung
   sendiri tiga puluh tujuh baris. */

.pk-load {
  display: grid;
  gap: 14px;
  margin: 0;
}

.pk-load figcaption {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.pk-load figcaption > span {
  color: #C6D3E2;
  font-size: 12.5px;
  font-weight: 600;
}

.pk-load figcaption a {
  color: var(--hmte-gold);
  font-size: 12.5px;
  font-weight: 600;
  text-decoration: none;
}

.pk-load figcaption a:hover {
  text-decoration: underline;
}

.pk-load figcaption a b {
  transition: transform 240ms var(--sr-ease);
  display: inline-block;
}

.pk-load figcaption a:hover b {
  transform: translateX(3px);
}

.pk-load-bars {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: clamp(4px, 0.9vw, 11px);
  margin: 0;
  padding: 0;
  list-style: none;
}

.pk-load-bars li {
  display: grid;
  align-content: end;
  justify-items: center;
  gap: 7px;
}

/* Palung selalu terlihat, isinya yang berubah. Bulan tanpa program karena itu
   terbaca sebagai bulan kosong, bukan sebagai batang yang hilang. */
.pk-load-bars i {
  position: relative;
  display: block;
  width: 100%;
  height: clamp(44px, 6.5vw, 88px);
  overflow: hidden;
  border-radius: var(--sr-xs);
  background: rgba(255, 255, 255, 0.09);
}

/*
 * Lantai 5px supaya bulan berisi satu program tetap terlihat sebagai batang,
 * bukan sebagai garis tipis yang terbaca seperti cacat render. Bulan yang
 * benar-benar kosong menyembunyikan isiannya sama sekali, jadi lantai itu tidak
 * pernah berbohong tentang nol.
 */
.pk-load-bars i::after {
  content: '';
  position: absolute;
  inset: auto 0 0 0;
  height: max(5px, calc(var(--load, 0) * 100%));
  border-radius: inherit;
  background: var(--hmte-gold);
}

.pk-load-bars li[data-empty='true'] i::after {
  display: none;
}

.pk-load-bars b {
  color: #fff;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
}

.pk-load-bars span {
  color: #C6D3E2;
  font-size: 11px;
  font-weight: 500;
}

.pk-load-bars li[data-current='true'] i {
  box-shadow: inset 0 0 0 1.5px var(--hmte-gold);
}

.pk-load-bars li[data-current='true'] span {
  color: var(--hmte-gold);
  font-weight: 700;
}

.pk-load > p {
  margin: 0;
  color: #C6D3E2;
  font-size: 12.5px;
  line-height: 1.6;
}

/* ---- Sorotan ----
   Tegel berwarna pejal, bukan kartu putih berfoto. Fotonya dulu diambil dari
   dokumentasi kegiatan lain dan tidak satu pun benar-benar memotret program
   yang dijanjikan judulnya. Warna bidangnya sendiri lebih jujur sekaligus lebih
   kuat, dan sekaligus menjadikan halaman ini punya sesuatu yang pejal.

   Tegelnya sama besar. Ketiganya sesama sorotan, dan mengecilkan dua di
   antaranya akan mengarang urutan kepentingan yang tidak ada di datanya. */

.pk-spot {
  margin-bottom: clamp(44px, 6vw, 80px);
}

.pk-spot-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(258px, 1fr));
  gap: 16px;
}

.pk-spot-card {
  display: grid;
  /* Baris ketiga yang melar, bukan align-content: start. Dengan yang kedua,
     sisa ruang menumpuk di bawah kartu dan kaki tiap tegel berhenti di tinggi
     yang berbeda-beda mengikuti panjang ringkasannya. */
  grid-template-rows: auto auto 1fr auto;
  gap: 12px;
  min-height: 226px;
  padding: clamp(22px, 2.6vw, 30px);
  border-radius: var(--sr-lg);
  color: #fff;
  background: var(--div);
  text-decoration: none;
  transition:
    transform 320ms var(--sr-ease),
    box-shadow 320ms var(--sr-ease);
}

.pk-spot-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--sr-shadow-2);
}

.pk-spot-card:focus-visible {
  outline: 2px solid var(--hmte-navy-deep);
  outline-offset: 3px;
}

/*
 * Semua teks di tegel ini putih penuh, tanpa satu pun yang diredupkan dengan
 * alpha. Delapan warna bidang berkisar 5.04:1 sampai 9.83:1 terhadap putih;
 * menurunkan putihnya ke 75% pada rona yang paling terang menjatuhkannya ke
 * sekitar 3:1 dan teksnya berhenti lolos ambang. Hierarki di sini dibawa ukuran
 * dan bobot, dan latar pil yang MENGGELAP, bukan tinta yang memudar.
 */
.pk-spot-div {
  justify-self: start;
  padding: 5px 12px;
  border-radius: var(--sr-pill);
  background: rgba(0, 0, 0, 0.18);
  font-size: 11.5px;
  font-weight: 600;
}

.pk-spot-card h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(21px, 2.4vw, 27px);
  font-weight: 600;
  line-height: 1.16;
  letter-spacing: -0.028em;
  text-wrap: balance;
}

.pk-spot-card > p {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  font-size: 13.5px;
  line-height: 1.62;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.pk-spot-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 6px;
  padding-top: 14px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24);
}

.pk-spot-foot time {
  font-size: 12.5px;
  font-weight: 600;
}

.pk-spot-foot b {
  font-size: 17px;
  transition: transform 280ms var(--sr-ease);
}

.pk-spot-card:hover .pk-spot-foot b {
  transform: translateX(3px);
}

/* ---- Katalog ---- */

.pk-subhead {
  max-width: 52ch;
  margin: 10px 0 0;
  color: var(--sr-ink-soft);
  font-size: 14px;
  line-height: 1.65;
  text-wrap: pretty;
}

.pk-filters {
  display: grid;
  gap: 12px;
  margin-bottom: clamp(20px, 3vw, 30px);
}

.pk-filters-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

/* ---- Register ----
   Tiga puluh tujuh program adalah daftar, bukan galeri. Yang dibutuhkan
   pembacanya adalah membandingkan dan menemukan, dan untuk itu baris padat
   selalu mengalahkan kartu: satu layar memuat sepuluh baris terbaca melawan
   empat kartu yang isinya sama. Kartu dipakai versi sebelumnya bukan karena
   cocok, melainkan karena kartu adalah jawaban yang paling mudah.

   Ritmenya datang dari palang bidang. Menggulir katalog berarti melewati
   delapan pita warna, dan warna itu sama persis dengan warna bidang yang sama
   di seluruh situs, jadi ia sekaligus penunjuk arah. */

.pk-register {
  display: grid;
  gap: clamp(16px, 2.4vw, 26px);
}

.pk-group {
  overflow: hidden;
  border-radius: var(--sr-lg);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
}

.pk-group-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px clamp(16px, 2vw, 22px);
  color: #fff;
  background: var(--div);
}

/* Latar pil menggelapkan, bukan meredupkan tintanya, dengan alasan yang sama
   seperti .pk-spot-div di atas. */
.pk-group-mark {
  flex: 0 0 auto;
  padding: 6px 12px;
  border-radius: var(--sr-pill);
  background: rgba(0, 0, 0, 0.2);
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.pk-group-head h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(15px, 1.7vw, 18px);
  font-weight: 600;
  line-height: 1.24;
  letter-spacing: -0.02em;
}

.pk-group-head p {
  margin: 3px 0 0;
  font-size: 12.5px;
  font-weight: 500;
}

.pk-rows {
  margin: 0;
  padding: 7px 8px 9px;
  list-style: none;
}

.pk-group-flat .pk-rows {
  padding: 9px 8px;
}

.pk-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto 14px;
  gap: clamp(12px, 1.6vw, 20px);
  align-items: center;
  padding: 10px 12px;
  border-radius: var(--sr-md);
  color: var(--sr-ink);
  text-decoration: none;
  transition: background-color 180ms var(--sr-ease);
}

.pk-row:hover {
  background: var(--div-tint);
}

.pk-row:focus-visible {
  outline: 2px solid var(--div);
  outline-offset: -2px;
}

/*
 * Pemisah baris adalah satu-satunya garis yang diizinkan sistem ini, dan hanya
 * di dalam kartu. Inset dari tepi supaya kelompoknya tetap terbaca sebagai satu
 * permukaan utuh, bukan sebagai tabel.
 */
.pk-rows li + li .pk-row {
  box-shadow: inset 0 1px 0 rgba(var(--hmte-navy-rgb), 0.07);
}

.pk-row-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.pk-row-copy strong {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  line-height: 1.28;
  letter-spacing: -0.018em;
}

.pk-row-copy small {
  display: -webkit-box;
  /* Di layar 1440 sel ini melebar sampai sekitar 90ch, jauh di atas batas
     nyaman satu baris teks. Kolom meta tetap menempel kanan karena ia sel
     tersendiri; yang dibatasi cuma lebar tulisannya. */
  max-width: 76ch;
  overflow: hidden;
  color: var(--sr-ink-soft);
  font-size: 12.5px;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.pk-row-meta {
  display: flex;
  align-items: center;
  justify-content: end;
  gap: 9px;
  flex-wrap: wrap;
}

.pk-row-meta time {
  color: var(--div);
  font-size: 12.5px;
  font-weight: 600;
  white-space: nowrap;
}

.pk-row-chev {
  color: var(--sr-ink-faint);
  font-size: 18px;
  line-height: 1;
  transition: transform 180ms var(--sr-ease), color 180ms var(--sr-ease);
}

.pk-row:hover .pk-row-chev {
  color: var(--div);
  transform: translateX(2px);
}

/*
 * Di layar sempit, pola dan tanggal turun ke bawah judul, bukan disembunyikan:
 * keduanya justru alasan utama orang membuka katalog ini.
 *
 * Keempat anaknya ditempatkan eksplisit. Dengan penempatan otomatis, satu anak
 * yang diberi grid-column membuat sisanya mengalir ke sel sisa yang tidak
 * terduga, dan chevron mendarat di baris kedua.
 */
@media (max-width: 900px) {
  .pk-row {
    grid-template-columns: auto minmax(0, 1fr) 14px;
    row-gap: 6px;
  }

  .pk-row > .date-badge {
    grid-area: 1 / 1 / span 2 / 2;
  }

  .pk-row-copy {
    grid-area: 1 / 2 / 2 / 3;
  }

  .pk-row-meta {
    grid-area: 2 / 2 / 3 / 3;
    justify-content: start;
  }

  .pk-row-chev {
    grid-area: 1 / 3 / span 2 / 4;
  }
}

@media (max-width: 620px) {
  .pk-load-bars {
    grid-template-columns: repeat(6, minmax(0, 1fr));
    row-gap: 14px;
  }

  .pk-load-bars i {
    height: 56px;
  }

  .pk-row {
    grid-template-columns: auto minmax(0, 1fr);
    gap: 12px;
    row-gap: 6px;
  }

  .pk-row-chev {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pk-spot-card,
  .pk-spot-foot b,
  .pk-load figcaption a b,
  .pk-row,
  .pk-row-chev {
    transition: none;
  }

  .pk-spot-card:hover {
    transform: none;
  }
}

/* ============================================================
   /program-kerja/[slug] : berkas program
   ============================================================ */

/*
 * Satu halaman padat, tanpa satu pun foto.
 *
 * Versi sebelumnya membuka dengan foto besar yang diambil dari dokumentasi
 * kegiatan lain: gambar orang tertawa di lapangan dipasang di atas judul
 * "Pelatihan Dasar Organisasi". Gambar yang tidak memotret isinya bukan cuma
 * tidak menolong, ia berbohong. Penggantinya bidang abstrak yang sama dengan
 * hero halaman lain, dan ruang yang tadinya dimakan foto sekarang dipakai oleh
 * keterangan yang benar-benar ada datanya.
 */

.pgd-band {
  position: relative;
  padding: clamp(46px, 6vw, 84px) 0 clamp(34px, 4vw, 56px);
  color: #fff;
  background: var(--hmte-navy-deep);
}

.pgd-band-inner {
  display: grid;
  justify-items: start;
}

.pgd-crumbs {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: clamp(20px, 3vw, 32px);
  font-size: 12.5px;
}

.pgd-crumbs a {
  color: #C6D3E2;
  font-weight: 500;
  text-decoration: none;
}

.pgd-crumbs a:hover {
  color: var(--hmte-gold);
}

.pgd-crumbs span {
  color: rgba(255, 255, 255, 0.34);
}

.pgd-kicker {
  margin: 0 0 12px;
  color: var(--hmte-gold);
  font-size: 12.5px;
  font-weight: 600;
}

.pgd-band h1 {
  max-width: 18ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(31px, 4.6vw, 62px);
  font-weight: 600;
  line-height: 1.04;
  letter-spacing: -0.038em;
  text-wrap: balance;
}

.pgd-lead {
  max-width: 62ch;
  margin: 18px 0 0;
  color: #C6D3E2;
  font-size: 14.5px;
  line-height: 1.72;
  text-wrap: pretty;
}

/* ---- Palang fakta ----
   Empat jawaban yang paling sering dicari, di tempat yang tidak menuntut
   gulir. Dulu hanya ada tiga, dan salah satunya "Anggota bidang", yang tidak
   ada hubungannya dengan program yang sedang dibuka. */

.pgd-facts {
  display: flex;
  gap: clamp(20px, 4vw, 52px);
  flex-wrap: wrap;
  /* Selebar shell, bukan selebar isinya. Induknya memakai justify-items: start,
     jadi tanpa ini garis pemisahnya berhenti di tengah halaman dan terbaca
     seperti tata letak yang belum jadi. */
  width: 100%;
  margin: clamp(26px, 4vw, 40px) 0 0;
  padding-top: clamp(20px, 3vw, 28px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.pgd-facts > div {
  display: grid;
  gap: 6px;
}

.pgd-facts dt {
  color: #9FB4CB;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pgd-facts dd {
  margin: 0;
  color: #fff;
  font-family: var(--font-display);
  font-size: clamp(15px, 1.8vw, 19px);
  font-weight: 600;
  letter-spacing: -0.018em;
}

/* ---- Badan ---- */

.pgd-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.85fr);
  gap: clamp(18px, 2.6vw, 30px);
  align-items: start;
}

.pgd-main {
  display: grid;
  gap: clamp(16px, 2.2vw, 22px);
  min-width: 0;
}

.pgd-block {
  padding: clamp(24px, 3vw, 36px);
  border-radius: var(--sr-lg);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
}

.pgd-block h2 {
  margin: 0 0 16px;
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: clamp(20px, 2.2vw, 26px);
  font-weight: 600;
  letter-spacing: -0.028em;
}

.pgd-block > p {
  max-width: 70ch;
  margin: 0 0 14px;
  color: var(--sr-ink-soft);
  font-size: 14.5px;
  line-height: 1.75;
  text-wrap: pretty;
}

.pgd-block > p:last-child {
  margin-bottom: 0;
}

.pgd-block-quiet {
  background: var(--sr-card-quiet);
  box-shadow: none;
}

/* Penanda butir memakai warna bidangnya, bukan bullet bawaan. Ini satu-satunya
   tempat warna bidang muncul di kolom utama, dan itu cukup untuk mengikat
   halaman ini ke bidangnya tanpa mewarnai seluruh permukaan. */
.pgd-objectives {
  display: grid;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.pgd-objectives li {
  position: relative;
  padding-left: 26px;
  color: var(--sr-ink);
  font-size: 14.5px;
  line-height: 1.6;
}

.pgd-objectives li::before {
  content: '';
  position: absolute;
  top: 0.55em;
  left: 0;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--div);
}

/* ---- Tahapan ---- */

.pgd-timeline {
  display: grid;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: none;
}

.pgd-timeline li {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 16px;
  padding: 16px 0;
}

.pgd-timeline li + li {
  box-shadow: inset 0 1px 0 rgba(var(--hmte-navy-rgb), 0.08);
}

.pgd-timeline-index {
  display: grid;
  place-content: center;
  align-self: start;
  width: 46px;
  height: 46px;
  border-radius: var(--sr-sm);
  color: var(--div);
  background: var(--div-tint);
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.pgd-timeline h3 {
  margin: 0;
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: 16.5px;
  font-weight: 600;
  line-height: 1.28;
  letter-spacing: -0.02em;
}

.pgd-timeline-when {
  display: inline-block;
  margin-top: 6px;
  padding: 3px 10px;
  border-radius: var(--sr-pill);
  background: rgba(var(--hmte-navy-rgb), 0.055);
  color: var(--sr-ink-soft);
  font-size: 11.5px;
  font-weight: 600;
}

.pgd-timeline p {
  max-width: 62ch;
  margin: 9px 0 0;
  color: var(--sr-ink-soft);
  font-size: 13.5px;
  line-height: 1.68;
  text-wrap: pretty;
}

/* ---- Rel kanan ----
   Lengket di layar lebar: kolom kirinya bisa jauh lebih panjang, dan berkas
   serta penanggung jawab justru paling dibutuhkan saat pembaca sedang di tengah
   tahapan. */

.pgd-rail {
  display: grid;
  gap: clamp(14px, 1.8vw, 18px);
  position: sticky;
  top: 88px;
  min-width: 0;
}

.pgd-card {
  padding: 20px 22px 22px;
  border-radius: var(--sr-lg);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
}

.pgd-card h2 {
  margin: 0 0 14px;
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.pgd-card ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.pgd-card-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 14px;
  color: var(--div);
  font-size: 12.5px;
  font-weight: 600;
  text-decoration: none;
}

.pgd-card-link:hover {
  text-decoration: underline;
}

.pgd-person {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 12px;
  gap: 12px;
  align-items: center;
  padding: 8px 6px;
  border-radius: var(--sr-sm);
  color: var(--sr-ink);
  text-decoration: none;
  transition: background-color 180ms var(--sr-ease);
}

a.pgd-person:hover {
  background: var(--div-tint);
}

a.pgd-person:focus-visible {
  outline: 2px solid var(--div);
  outline-offset: -2px;
}

/* Nama yang tidak cocok dengan pengurus mana pun tidak bisa diklik, jadi ia
   juga tidak boleh menyala saat disentuh kursor. */
.pgd-person-plain {
  grid-template-columns: 38px minmax(0, 1fr);
  cursor: default;
}

.pgd-people li + li .pgd-person {
  box-shadow: inset 0 1px 0 rgba(var(--hmte-navy-rgb), 0.07);
}

.pgd-avatar {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: var(--div);
  background: var(--div-tint);
  font-family: var(--font-display);
  font-size: 12.5px;
  font-weight: 700;
}

.pgd-people-copy {
  display: grid;
  gap: 1px;
  min-width: 0;
}

.pgd-people-copy strong {
  overflow: hidden;
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pgd-people-copy small {
  overflow: hidden;
  color: var(--sr-ink-soft);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pgd-person-chev {
  color: var(--sr-ink-faint);
  font-size: 17px;
  line-height: 1;
}

.pgd-files li + li {
  margin-top: 6px;
}

.pgd-files a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--sr-md);
  color: var(--sr-ink);
  background: var(--sr-card-quiet);
  text-decoration: none;
  transition: background-color 180ms var(--sr-ease);
}

.pgd-files a:hover {
  background: var(--div-tint);
}

.pgd-files a:focus-visible {
  outline: 2px solid var(--div);
  outline-offset: -2px;
}

.pgd-files span {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.pgd-files strong {
  overflow: hidden;
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.35;
  text-overflow: ellipsis;
}

.pgd-files small {
  color: var(--sr-ink-soft);
  font-size: 11.5px;
}

.pgd-files b {
  flex: 0 0 auto;
  color: var(--div);
  font-size: 15px;
}

/* ---- Peta bulan ---- */

.pgd-schedule-label {
  margin: 0 0 14px;
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.022em;
}

.pgd-months {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.pgd-months li {
  display: grid;
  place-items: center;
  min-height: 30px;
  border-radius: var(--sr-xs);
  background: rgba(var(--hmte-navy-rgb), 0.05);
  color: var(--sr-ink-soft);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.pgd-months li[data-active='true'] {
  color: #fff;
  background: var(--div);
}

.pgd-schedule-note {
  margin: 12px 0 0;
  color: var(--sr-ink-soft);
  font-size: 12.5px;
  line-height: 1.6;
}

.pgd-related li + li {
  margin-top: 2px;
}

.pgd-related a {
  display: grid;
  gap: 2px;
  padding: 9px 8px;
  border-radius: var(--sr-sm);
  color: var(--sr-ink);
  text-decoration: none;
  transition: background-color 180ms var(--sr-ease);
}

.pgd-related a:hover {
  background: var(--div-tint);
}

.pgd-related a:focus-visible {
  outline: 2px solid var(--div);
  outline-offset: -2px;
}

.pgd-related strong {
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.32;
}

.pgd-related small {
  color: var(--sr-ink-soft);
  font-size: 12px;
}

@media (max-width: 940px) {
  .pgd-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  /* Lengket kehilangan gunanya begitu rel turun ke bawah kolom utama, dan
     malah bisa mengunci sebagian layar di ponsel. */
  .pgd-rail {
    position: static;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pgd-person,
  .pgd-files a,
  .pgd-related a {
    transition: none;
  }
}

/* ============================================================
   /agenda : peta tahun + isi bulan
   ============================================================ */

.ag-bento {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: clamp(28px, 4vw, 44px);
}

.ag-lead {
  position: relative;
  display: flex;
  align-items: center;
  grid-column: span 2;
  grid-row: span 3;
  min-height: 300px;
  padding: clamp(28px, 3.5vw, 52px);
  overflow: hidden;
  border-radius: var(--sr-lg);
  color: #fff;
  background: var(--hmte-navy-deep);
  isolation: isolate;
}

.ag-lead-copy {
  position: relative;
  z-index: 1;
}

.ag-lead-copy > p:first-child {
  margin: 0 0 14px;
  color: var(--hmte-gold);
  font-size: 12.5px;
  font-weight: 600;
}

.ag-lead-copy h1 {
  max-width: 15ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(28px, 3.6vw, 46px);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: -0.035em;
  text-wrap: balance;
}

.ag-lead-copy h1 span {
  color: var(--hmte-gold);
}

.ag-lead-note {
  max-width: 48ch;
  margin: 16px 0 0;
  color: #C6D3E2;
  font-size: 14px;
  line-height: 1.72;
  text-wrap: pretty;
}

.ag-tile {
  display: grid;
  align-content: center;
  gap: 4px;
  padding: 18px 22px;
}

.ag-tile b {
  color: var(--hmte-navy);
  font-family: var(--font-display);
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
}

.ag-tile span {
  color: var(--sr-ink-soft);
  font-size: 13px;
  font-weight: 500;
}

/* ---- Saringan bidang ---- */

.ag-filter {
  display: flex;
  margin-bottom: 16px;
}

/* ---- Peta tahun ----
   Satu-satunya visualisasi waktu di seluruh situs. Dua belas tegel setara,
   tanpa garis pemisah: jarak antar tegel yang memisahkan. */

.ag-year {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: clamp(20px, 3vw, 30px);
}

.ag-month {
  display: grid;
  align-content: start;
  gap: 8px;
  min-height: 104px;
  padding: 14px 15px 13px;
  border: 0;
  border-radius: var(--sr-md);
  color: var(--sr-ink);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
  text-align: left;
  cursor: pointer;
  transition:
    transform 260ms var(--sr-ease),
    box-shadow 260ms var(--sr-ease),
    background-color 260ms var(--sr-ease);
}

.ag-month:hover {
  transform: translateY(-2px);
  box-shadow: var(--sr-shadow-2);
}

.ag-month:focus-visible {
  outline: 2px solid var(--hmte-navy);
  outline-offset: 2px;
}

.ag-month[data-active='true'] {
  color: #fff;
  background: var(--hmte-navy-deep);
  box-shadow: var(--sr-shadow-2);
}

.ag-month-name {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--sr-ink-soft);
  font-size: 12.5px;
