/*
 * Dua kepadatan dalam satu halaman.
 *
 * Yang masih berlaku tampil lega dengan balok tanggal pejal; yang sudah lewat
 * tampil padat, tenang, dan baloknya mengecil. Perbedaan ukuran di sini MEMBAWA
 * KETERANGAN, bukan variasi visual: pembaca tahu mana yang menuntut tindakan
 * tanpa perlu membandingkan tanggal satu per satu.
 */

.pgm-hero {
  position: relative;
  padding: clamp(48px, 6.5vw, 92px) 0 clamp(36px, 4.5vw, 60px);
  color: #fff;
  background: var(--hmte-navy-deep);
}

.pgm-hero-inner {
  display: grid;
  justify-items: start;
}

.pgm-hero-kicker {
  margin: 0 0 14px;
  color: var(--hmte-gold);
  font-size: 12.5px;
  font-weight: 600;
}

.pgm-hero h1 {
  max-width: 15ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 66px);
  font-weight: 600;
  line-height: 1.04;
  letter-spacing: -0.038em;
  text-wrap: balance;
}

.pgm-hero h1 span {
  color: var(--hmte-gold);
}

.pgm-hero-lead {
  max-width: 60ch;
  margin: 20px 0 0;
  color: #C6D3E2;
  font-size: 14.5px;
  line-height: 1.72;
  text-wrap: pretty;
}

.pgm-hero-facts {
  display: flex;
  gap: clamp(24px, 5vw, 60px);
  flex-wrap: wrap;
  /* Sama alasannya dengan .pgd-facts. */
  width: 100%;
  margin: clamp(26px, 4vw, 40px) 0 0;
  padding-top: clamp(20px, 3vw, 28px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.16);
}

.pgm-hero-facts > div {
  display: grid;
  gap: 5px;
}

.pgm-hero-facts dt {
  color: #9FB4CB;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pgm-hero-facts dd {
  margin: 0;
  color: var(--hmte-gold);
  font-family: var(--font-display);
  font-size: clamp(26px, 3vw, 36px);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.03em;
}

/* ---- Papan ---- */

.pgm-section + .pgm-section {
  margin-top: clamp(40px, 6vw, 72px);
}

.pgm-subhead {
  max-width: 52ch;
  margin: 10px 0 0;
  color: var(--sr-ink-soft);
  font-size: 14px;
  line-height: 1.65;
  text-wrap: pretty;
}

.pgm-board {
  display: grid;
  gap: 14px;
}

.pgm-board[data-dense="true"] {
  gap: 8px;
}

.pgm-notice {
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr);
  gap: clamp(16px, 2.4vw, 26px);
  padding: clamp(18px, 2.4vw, 26px);
  border-radius: var(--sr-lg);
  background: var(--sr-card);
  box-shadow: var(--sr-shadow-1);
}

.pgm-notice[data-state="archive"] {
  grid-template-columns: 62px minmax(0, 1fr);
  gap: 16px;
  padding: 14px 18px;
  background: var(--sr-card-quiet);
  box-shadow: none;
}

/* ---- Balok tanggal ---- */

.pgm-date {
  display: grid;
  place-content: center;
  gap: 2px;
  align-self: start;
  min-height: 88px;
  padding: 10px 6px;
  border-radius: var(--sr-md);
  color: #fff;
  background: var(--hmte-navy-deep);
  text-align: center;
}

.pgm-date b {
  font-family: var(--font-display);
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
}

.pgm-date span {
  color: var(--hmte-gold);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.pgm-date small {
  color: #B9C9DC;
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.05em;
}

/* Yang sudah lewat kehilangan warna emasnya dan mengecil. Balok yang tetap
   pejal navy akan menuntut perhatian yang sama dengan yang masih berlaku. */
.pgm-notice[data-state="archive"] .pgm-date {
  min-height: 58px;
  padding: 8px 4px;
  color: var(--sr-ink-soft);
  background: rgba(var(--hmte-navy-rgb), 0.07);
}

.pgm-notice[data-state="archive"] .pgm-date b {
  font-size: 20px;
}

.pgm-notice[data-state="archive"] .pgm-date span,
.pgm-notice[data-state="archive"] .pgm-date small {
  color: var(--sr-ink-soft);
}

.pgm-notice[data-state="archive"] .pgm-date small {
  display: none;
}

/* ---- Isi ---- */

.pgm-notice-body {
  display: grid;
  align-content: start;
  gap: 9px;
  min-width: 0;
}

.pgm-notice h3 {
  margin: 0;
  color: var(--sr-ink);
  font-family: var(--font-display);
  font-size: clamp(18px, 2.1vw, 23px);
  font-weight: 600;
  line-height: 1.22;
  letter-spacing: -0.026em;
  text-wrap: balance;
}

.pgm-notice[data-state="archive"] h3 {
  font-size: 16px;
  letter-spacing: -0.02em;
}

.pgm-notice-excerpt {
  max-width: 68ch;
  margin: 0;
  color: var(--sr-ink-soft);
  font-size: 14px;
  line-height: 1.68;
  text-wrap: pretty;
}

.pgm-notice[data-state="archive"] .pgm-notice-excerpt {
  display: -webkit-box;
  overflow: hidden;
  font-size: 13px;
  line-height: 1.58;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.pgm-notice-date {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin: 0;
  color: var(--sr-ink-soft);
  font-size: 12.5px;
  font-weight: 600;
}

.pgm-notice-date span {
  padding: 3px 10px;
  border-radius: var(--sr-pill);
  background: rgba(var(--hmte-navy-rgb), 0.06);
  font-size: 11.5px;
  font-weight: 600;
}

/* ---- Isi lengkap ----
   <details> bawaan peramban, tanpa satu baris JavaScript. Halaman pengumuman
   tidak punya rute rincian, jadi tanpa ini field `body` yang diketik pengurus
   tidak punya tempat sama sekali untuk muncul. */

.pgm-detail {
  margin-top: 3px;
}

.pgm-detail summary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  border-radius: var(--sr-pill);
  background: rgba(var(--hmte-navy-rgb), 0.06);
  color: var(--sr-ink);
  cursor: pointer;
  font-size: 12.5px;
  font-weight: 600;
  list-style: none;
}

.pgm-detail summary::-webkit-details-marker {
  display: none;
}

.pgm-detail summary:hover {
  background: rgba(var(--hmte-navy-rgb), 0.1);
}

.pgm-detail summary:focus-visible {
  outline: 2px solid var(--hmte-navy);
  outline-offset: 2px;
}

.pgm-detail summary b {
  color: var(--sr-ink-soft);
  font-size: 15px;
  line-height: 1;
  transition: transform 220ms var(--sr-ease);
}

.pgm-detail[open] summary b {
  transform: rotate(45deg);
}

.pgm-detail > div {
  padding: 16px 2px 2px;
}

.pgm-detail p {
  max-width: 70ch;
  margin: 0 0 12px;
  color: var(--sr-ink-soft);
  font-size: 14px;
  line-height: 1.75;
  text-wrap: pretty;
}

.pgm-detail p:last-child {
  margin-bottom: 0;
}

/* ---- Ajakan aspirasi ---- */

.pgm-aspirasi {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(20px, 4vw, 48px);
  flex-wrap: wrap;
  margin-top: clamp(40px, 6vw, 72px);
  padding: clamp(26px, 3.4vw, 40px);
  border-radius: var(--sr-lg);
  color: #fff;
  background: var(--hmte-navy-deep);
}

.pgm-aspirasi h2 {
  max-width: 24ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(21px, 2.4vw, 28px);
  font-weight: 600;
  line-height: 1.16;
  letter-spacing: -0.028em;
  text-wrap: balance;
}

.pgm-aspirasi p {
  max-width: 58ch;
  margin: 12px 0 0;
  color: #C6D3E2;
  font-size: 14px;
  line-height: 1.68;
  text-wrap: pretty;
}

.pgm-aspirasi a {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
  min-height: 46px;
  padding: 0 22px;
  border-radius: var(--sr-pill);
  color: var(--hmte-navy-deep);
  background: var(--hmte-gold);
  font-size: 13.5px;
  font-weight: 600;
  text-decoration: none;
  transition: background-color 200ms var(--sr-ease);
}

.pgm-aspirasi a:hover {
  background: #fff;
}

@media (max-width: 620px) {
  .pgm-notice,
  .pgm-notice[data-state="archive"] {
    grid-template-columns: minmax(0, 1fr);
    gap: 14px;
  }

  /* Balok tanggal jadi baris mendatar supaya tidak memakan satu blok penuh
     di atas judulnya. */
  .pgm-date {
    display: flex;
    align-items: baseline;
    justify-self: start;
    gap: 7px;
    min-height: 0;
    padding: 7px 14px;
  }

  .pgm-date b {
    font-size: 19px;
  }

  .pgm-notice[data-state="archive"] .pgm-date {
    min-height: 0;
    padding: 6px 12px;
  }

  .pgm-notice[data-state="archive"] .pgm-date small {
    display: block;
  }

  .pgm-aspirasi a {
    width: 100%;
    justify-content: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pgm-detail summary b,
  .pgm-aspirasi a {
    transition: none;
  }
}

